.rv-confirm-list li:first-child, .confirm-dialog__list li:first-child { border-top: 0; }
/* A Go to at the right of each pending item (Chris, 2026-09-30: "a button to the right to go to that item") */
.rv-confirm-list li.rv-todo-go { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.rv-todo-text { min-width: 0; flex: 1 1 auto; }
.rv-go-btn { flex: none; display: inline-flex; align-items: center; gap: 4px; padding: 4px 10px 4px 11px;
  border: 1px solid var(--d-bd-cfd4e2); border-radius: 999px; background: var(--surface); color: var(--accent-ink); font: inherit;
  font-size: 0.78125rem; font-weight: 700; line-height: 1.1; white-space: nowrap; cursor: pointer;
