.rv-dir .rv-dir-confirm { flex: none; min-height: 40px; padding: 0 22px; border: 0; border-radius: 9px; cursor: pointer;
  background: var(--accent); color: var(--on-fill); font: inherit; font-size: 0.92rem; font-weight: 600; }
.rv-dir .rv-dir-confirm:hover { background: var(--accent-hover); }
.rv-dir .rv-dir-confirm:disabled { opacity: 0.45; cursor: default; background: var(--accent); }
/* Once a direction is picked: grey + lock the whole card, keep the chosen role lit. */
