.rv-demo-list { margin: 8px 0 0; padding-left: 18px; }
.rv-demo-list li { margin: 3px 0; font-size: 0.9rem; }
.rv-demo-tag { font-size: 0.76rem; padding: 1px 7px; border-radius: 6px; margin-left: 6px; }
