.rv-cp-area, .rv-cp-act, .rv-cp-input { width: 100%; box-sizing: border-box; padding: 7px 10px;
  border: 1px solid var(--d-bd-cdd1dd); border-radius: 8px; font: inherit; }
.rv-cp-area { font-weight: 600; }
.rv-cp-act, .rv-cp-input { resize: vertical; }
.rv-cp-area:focus, .rv-cp-act:focus, .rv-cp-input:focus, .rv-cp-date:focus, select.rv-cp-input:focus {
  outline: none; border-color: var(--accent-line); box-shadow: 0 0 0 3px var(--d-sh-252a59-a12); }
.rv-cp-mode { display: flex; flex-direction: column; gap: 3px; }
.rv-cp-mode-lbl { font-size: 0.78rem; color: var(--d-fg-6b7280); font-weight: 600; }
.rv-cp-daterow { display: flex; align-items: center; gap: 8px; }
.rv-cp-datelbl { font-size: 0.8rem; color: var(--d-fg-6b7280); }
.rv-cp-date { padding: 6px 9px; border: 1px solid var(--d-bd-cdd1dd); border-radius: 8px; font: inherit; }
.rv-cp-remove { align-self: flex-start; padding: 3px 12px; border: 1px solid var(--d-bd-e0c3c3); border-radius: 999px;
  background: var(--surface); color: var(--d-fg-9a3b3b); font: inherit; font-size: 0.78rem; font-weight: 600; cursor: pointer; }
.rv-cp-remove:hover { background: var(--d-bg-fbeaea); }
.rv-cp-add { margin-top: 10px; padding: 6px 14px; border: 1px dashed var(--d-bd-b9c0d4); border-radius: 8px;
