.rv-cp-add:hover { background: var(--d-bg-eef1f7); }
.rv-cp-grp { margin-top: 8px; }
.rv-cp-grp-lbl { font-size: 0.82rem; font-weight: 700; color: var(--accent-ink); margin: 8px 0 4px; }
.rv-cp-field { display: flex; flex-direction: column; gap: 3px; margin-bottom: 8px; }
.rv-cp-lbl { font-size: 0.82rem; font-weight: 600; color: var(--d-fg-333333); }
.rv-cp-hint { font-size: 0.76rem; color: var(--d-fg-6b7280); }
