.rv-cpf-lbl { font-weight: 600; color: var(--d-fg-5b6275); }
.rv-cpf-date { font-size: 0.76rem; color: var(--d-fg-6b7186); margin-top: 4px; }
.rv-cpf-lbl2 { font-size: 0.72rem; font-weight: 700; color: var(--d-fg-6b7186); text-transform: uppercase; letter-spacing: 0.04em; }
.rv-cpf-val { font-size: 0.86rem; color: var(--ink); margin-top: 2px; overflow-wrap: anywhere; }
