.rv-mgr-pin { display: flex; flex-direction: column; gap: 10px; }
.rv-mgr-table { width: 100%; border-collapse: collapse; font-size: 0.82rem; }
.rv-mgr-table th { text-align: left; font-size: max(10px, 0.68rem); font-weight: 800; letter-spacing: .04em;
