.rv-mgr-their { background: var(--d-bg-f3f6fc); }
.rv-mgr-foot { font-size: 0.78rem; color: var(--d-fg-4b5169); font-weight: 600; padding-top: 2px; }
.rv-mgr-modov { font-size: 0.82rem; font-weight: 700; color: var(--ink); margin-top: 6px;
