.rv-mgr-goal-l { font-size: 0.8rem; color: var(--d-fg-4b5169); margin-top: 3px; }
/* The per-line moderation control (PM KPI review, actionable lines). */
.rv-mod-cell { display: flex; flex-direction: column; gap: 5px; align-items: flex-start; min-width: 160px; }
.rv-mod-val { width: 100%; font: inherit; font-size: 0.8rem; color: var(--ink);
  background: var(--surface); border: 1px solid var(--d-bd-cdd1dd); border-radius: 7px; padding: 5px 8px; }
.rv-mod-val:focus { outline: none; border-color: var(--accent-line); box-shadow: 0 0 0 3px var(--d-sh-252a59-a12); }
