.rv-mod-arrow { color: var(--d-fg-9099ad); font-weight: 700; }
.rv-mgr-wait { font-size: 0.78rem; color: var(--d-fg-6b7280); margin-right: 6px; }
/* Team-summary <-> Individual toggle + the whole-team score table. */
.rv-mgr-wrap { display: flex; flex-direction: column; gap: 10px; }
.rv-mgr-toggle { align-self: flex-start; max-width: 340px; }
.rv-mgr-sumtable tbody tr { cursor: pointer; }
.rv-mgr-sumtable tbody tr:hover td { background: var(--d-bg-eef1f7); }
.rv-mgr-sumstatus { color: var(--d-fg-6b7280); font-size: 0.78rem; white-space: nowrap; }
/* Bulk-approve on the summary: a checkbox column on ready rows + an Approve control. */
.rv-sum-chk { width: 34px; text-align: center; }
.rv-sum-chk input { cursor: pointer; }
.rv-sum-foot { display: flex; justify-content: flex-end; margin-top: 10px; }
/* IDP manager review: debounced comment textareas, the career reference block and
