.rv-idp-pbox-h { font-size: 0.86rem; color: var(--ink); }
.rv-idp-dl { display: grid; grid-template-columns: 96px minmax(0, 1fr); gap: 5px 10px; margin: 0; font-size: 0.82rem;
  line-height: 1.45; }
.rv-idp-dl dt { color: var(--d-fg-5a6275); font-weight: 700; }
.rv-idp-dl dd { margin: 0; color: var(--d-fg-333948); overflow-wrap: anywhere; }
.rv-idp-foot { display: flex; align-items: center; gap: 12px; border-top: 1px solid var(--line-soft); padding-top: 12px;
  margin-top: 4px; }
