.rv-rmk-btn { position: relative; display: inline-flex; align-items: center; justify-content: center;
  width: 32px; height: 32px; padding: 0; border: 1px solid var(--d-bd-d7dcea); border-radius: 9px; background: var(--surface);
  color: var(--accent-ink); cursor: pointer; transition: background .12s, border-color .12s, box-shadow .12s; }
