@media (prefers-reduced-motion: reduce) { .rv-rmk-btn[data-state="loading"] .rv-rmk-dot { animation: none; } }

/* The popout: one card for the page, fixed beside the icon (positioned by journey_chat.js rmkPlace). */
.rv-rmk-pop { position: fixed; z-index: 1200; box-sizing: border-box; background: var(--surface); color: var(--ink);
  border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px 12px;
