.rv-tbox-table th .col-menu-btn:focus-visible { outline: 2px solid var(--accent-line); outline-offset: -2px; }
.rv-tbox-table td { padding: 6px 8px; border-bottom: 1px solid var(--line-soft); vertical-align: middle; overflow: hidden; }
.rv-tbox-tdname .rv-tbox-pname { display: block; }
.rv-tbox-tddept { white-space: nowrap; text-overflow: ellipsis; color: var(--ink-2); }
.rv-tbox-tdgrade { font-variant-numeric: tabular-nums; }
.rv-tbox-table td.rv-tbox-tdact { padding: 6px 12px 6px 6px; }
.rv-tbox-table .rv-tbox-acts { gap: 10px; }
.rv-tbox-bandw { display: inline-flex; align-items: center; gap: 4px; max-width: 100%; }
/* the AI insight (2026-10-07): an icon per person in the list's AI column and in place of the panel's initials */
.rv-tbox-aih { display: block; padding: 9px 4px; text-align: center; font-weight: 700; }
.rv-tbox-table td.rv-tbox-tdai { padding: 4px 2px; text-align: center; }
.rv-tbox-insbtn.rv-rmk-btn { width: 30px; height: 30px; flex: none; border-radius: 50%; }
.rv-tbox-insbtn.rv-rmk-btn .rv-ico { width: 15px; height: 15px; }
.rv-tb-ins .rv-ps-head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.rv-tb-facts { display: grid; gap: 4px; margin: 8px 0 10px; font-size: 0.78125rem; }
.rv-tb-fact { display: flex; align-items: center; gap: 8px; min-width: 0; }
.rv-tb-fk { flex: none; width: 86px; color: var(--d-fg-5b6178); }
.rv-tb-ff { min-width: 0; color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rv-tb-dec { margin: 8px 0 0; font-size: 0.8125rem; line-height: 1.5; color: var(--d-fg-1f2335); }
.rv-tb-open { display: inline-block; margin-top: 10px; }
.rv-tbox-trailbtn { flex: none; width: 24px; height: 24px; padding: 0; border: 0; border-radius: 6px; background: none;
