.rv-tbox-trailbtn:focus-visible { outline: 2px solid var(--accent-line); outline-offset: 1px; }
.rv-tbox-trailbtn .rv-ico { width: 15px; height: 15px; }
/* the column menu, fixed to the page (the chat scrolls) */
.col-menu.rv-tbox-cm { position: fixed; z-index: 1300; }
.col-menu.rv-tbox-cm .cm-sort button.is-on { font-weight: 700; color: var(--accent-ink); background: var(--d-bg-eef0f8); }
