.od-bu-r > span { white-space: nowrap; }
.od-bu-r { display: grid; grid-template-columns: minmax(0, 1fr) 5.5rem 4.375rem; gap: 8px; align-items: center; padding: 4px 2px;
  border-top: 1px solid var(--line-soft); font-size: 0.78rem; }
