.od-box-units { display: flex; flex-direction: column; gap: 5px; max-height: 300px; overflow-y: auto; }
.od-box-u { width: 100%; min-height: 44px; display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 5px 10px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface); font: inherit; text-align: left;
  cursor: pointer; }
