@media (max-width: 600px) { .od-tiles { grid-template-columns: minmax(0, 1fr); } }
@media (max-width: 900px) {
  .od-grid { grid-template-columns: minmax(0, 1fr); }
  .od-grid > *, .od-grid > * + * { grid-column: 1 / -1; order: 0; }
  .od-steps { grid-auto-flow: row; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 14px 0; }
  .od-link { display: none; }
  .od-row, .od-yr, .od-crow { grid-template-columns: minmax(0, 1fr) auto 16px; }
