.adm-main { flex: 1; min-width: 0; padding: 16px 24px 40px; box-sizing: border-box; }
.adm-head { margin: 0 0 16px; }
.adm-head-row { display: flex; align-items: center; gap: 12px; }
.adm-head-title { display: flex; align-items: center; gap: 9px; margin: 0; font-size: 1.35rem; font-weight: 800; color: var(--accent-ink); }
