.adm-state { font-size: .72rem; font-weight: 700; border-radius: 999px; padding: 3px 10px; }
.adm-state.is-on { background: var(--d-bg-d7f0e0); color: var(--d-fg-1a7a54); }
.adm-state.is-off { background: var(--surface-3); color: var(--muted); }
.adm-tabs { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 10px; border-bottom: 1px solid var(--line); }
.adm-tabs a { padding: 9px 14px; font-size: .92rem; color: var(--d-fg-4b5164); text-decoration: none; border-bottom: 2px solid transparent; margin-bottom: -1px; }
.adm-tabs a:hover { color: var(--accent-ink); text-decoration: none; }
.adm-tabs a.is-active { color: var(--accent-ink); font-weight: 700; border-bottom-color: var(--accent-line); }
.adm-subnav { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.adm-subnav a { font-size: .82rem; padding: 6px 12px; border-radius: 999px; border: 1px solid var(--line-strong); background: var(--surface); color: var(--ink-2); text-decoration: none; }
.adm-subnav a:hover { border-color: var(--accent-line); text-decoration: none; }
.adm-subnav a.is-active { background: var(--accent); border-color: var(--accent-line); color: var(--on-fill); font-weight: 700; }
/* the top bar's search, and the search itself */
.adm-search-trigger { display: inline-flex; align-items: center; gap: 8px; min-height: 34px; min-width: 300px; padding: 0 10px 0 12px; margin-right: 8px; border: 0; border-radius: 8px; background: var(--k-ffffff-a12); color: var(--k-dfe2f0); font: inherit; font-size: .85rem; cursor: pointer; }
.adm-search-trigger:hover { background: var(--k-ffffff-a18); }
.adm-search-trigger span { flex: 1; text-align: left; }
