.adm-search[hidden] { display: none; }
.adm-search { position: fixed; inset: 0; z-index: 1000; display: flex; justify-content: center; align-items: flex-start; padding-top: 12vh; background: var(--d-bg-141834-a35); }
.adm-search-box { width: min(680px, calc(100vw - 32px)); background: var(--surface); border-radius: 14px; box-shadow: 0 18px 50px var(--d-sh-141834-a3); overflow: hidden; }
.adm-search-input { display: flex; align-items: center; gap: 10px; height: 56px; padding: 0 16px; border-bottom: 1px solid var(--line); color: var(--muted); }
.adm-search-input input { flex: 1; min-width: 0; border: 0; outline: none; font: inherit; font-size: 1rem; color: var(--ink); background: transparent; }
.adm-search-input kbd, .adm-kbd { font: inherit; font-size: max(10px, .7rem); border: 1px solid var(--line-strong); border-radius: 4px; padding: 1px 6px; }
.adm-search-list { max-height: min(56vh, 460px); overflow-y: auto; padding: 6px; }
.adm-search-grp { font-size: max(10px, .66rem); font-weight: 800; letter-spacing: .07em; text-transform: uppercase; color: var(--faint); padding: 8px 10px 4px; }
.adm-search-opt { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; color: var(--ink); text-decoration: none; }
.adm-search-opt:hover, .adm-search-opt.is-cur { background: var(--d-bg-eef1fa); text-decoration: none; }
.adm-search-opt .adm-search-txt { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.adm-search-opt b { font-size: .9rem; color: var(--accent-ink); }
.adm-search-opt small { font-size: .78rem; color: var(--muted); }
.adm-search-val { flex: none; max-width: 42%; font-size: .78rem; color: var(--ink-2); text-align: right; }
.adm-search-empty { padding: 18px 12px; font-size: .88rem; color: var(--muted); }
.adm-search-foot { margin: 0; padding: 8px 14px; border-top: 1px solid var(--line); font-size: .74rem; color: var(--faint); }
/* a module's Settings page */
.adm-set { display: flex; align-items: flex-start; gap: 20px; }
.adm-set-index { position: sticky; top: calc(var(--topbar-h) + 12px); flex: 0 0 210px; display: flex; flex-direction: column; gap: 2px; }
.adm-set-index a { display: flex; justify-content: space-between; gap: 8px; padding: 8px 10px; border-radius: 8px; font-size: .85rem; color: var(--ink-2); text-decoration: none; }
.adm-set-index a:hover { background: var(--surface); text-decoration: none; }
.adm-set-idx-scope { font-size: max(10px, .68rem); font-weight: 600; color: var(--faint); text-align: right; }
.adm-set-index p { margin: 10px 10px 0; line-height: 1.4; }
.adm-set-cards { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 12px; }
.adm-set-card { scroll-margin-top: calc(var(--topbar-h) + 12px); }
