.adm-set-last { flex: 1; font-size: .76rem; color: var(--faint); text-align: right; }
.adm-set-open, .adm-need-go, .adm-rep-dl { flex: none; font-size: .82rem; font-weight: 700; white-space: nowrap; border: 1px solid var(--line-strong); border-radius: 8px; padding: 6px 11px; text-decoration: none; }
.adm-set-open:hover, .adm-need-go:hover, .adm-rep-dl:hover { border-color: var(--accent-line); text-decoration: none; }
/* the download panel (2026-10-23): Download... is a button opening it; the panel's fields down the left */
button.adm-rep-dl { background: var(--surface); color: var(--accent-ink); font: inherit; font-size: .82rem; font-weight: 700; cursor: pointer; }
/* Data downloads (Chris 10 Nov): a direct Download lines up with Download... in width and colour */
.adm-rep-files .adm-rep-fmt ~ .adm-rep-dl { min-width: 6.5rem; text-align: center; box-sizing: border-box; }
.adm-rep-files .adm-rep-fmt ~ a.adm-rep-dl { background: var(--surface); color: var(--accent-ink); }
.dl-field { display: flex; flex-direction: column; gap: 4px; margin: 0 0 12px; }
.dl-field[hidden], .dl-note[hidden], .dl-unitlist[hidden] { display: none; }
.dl-lab { font-size: .8rem; font-weight: 700; color: var(--d-fg-2f3552); padding: 0; }
.dl-field select { max-width: none; width: 100%; }
.dl-fixed { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; border: 1px solid var(--d-bd-e3e5ee);
  border-radius: 8px; padding: 8px 10px; background: var(--d-bg-f4f5f9); font-size: .9rem; color: var(--d-fg-1d2033); }
fieldset.dl-units { border: 0; margin: 0; padding: 0; min-width: 0; }
.dl-units-n { font-weight: 400; color: var(--muted); }
.dl-unitlist { border: 1px solid var(--d-bd-cfd3e2); border-radius: 8px; padding: 3px 0; max-height: 280px; overflow-y: auto; }
.dl-tk { display: flex; align-items: center; gap: 8px; padding: 6px 10px; font-size: .88rem; color: var(--d-fg-1d2033); cursor: pointer; }
.dl-tk input { margin: 0; accent-color: var(--accent-ink); flex: none; }
.dl-tk .muted { margin-left: auto; padding-left: 8px; }
.dl-tk-all { border-bottom: 1px solid var(--line-soft); font-weight: 600; }
.dl-note { margin: 4px 0 0; line-height: 1.45; }
.dl-what { margin: 0 0 6px; font-size: .95rem; }
.dl-dates .adm-field-date { display: block; }
.dl-dates .odp-trig[data-odp="range"] { width: 100%; }
.adm-set-desc { margin: 6px 0 0; }
.adm-set-rows { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr); column-gap: 16px; margin: 8px 0 0; }
.adm-set-rows div { display: contents; }
.adm-set-rows dt, .adm-set-rows dd { margin: 0; padding: 7px 0; border-top: 1px solid var(--line-soft); font-size: .88rem; }
.adm-set-rows dt { color: var(--muted); }
.adm-set-rows dd { font-weight: 600; color: var(--ink); }
.adm-scope { font-size: max(10px, .68rem); font-weight: 800; white-space: nowrap; padding: 2px 8px; border-radius: 999px; background: var(--surface-3); color: var(--ink-2); }
.adm-scope.is-bg { background: var(--d-bg-dff2ec); color: var(--d-fg-155e52); }
.adm-scope.is-cycle, .adm-scope.is-default_cycle, .adm-scope.is-cycle_unit { background: var(--info-tint); color: var(--info-ink); }
.adm-dates { margin-top: 8px; }
.adm-now { font-size: .74rem; font-weight: 700; border-radius: 999px; padding: 2px 8px; white-space: nowrap; }
.adm-now.is-open { background: var(--d-bg-d7f0e0); color: var(--d-fg-1a7a54); }
.adm-now.is-not_open { background: var(--info-tint); color: var(--info-ink); }
.adm-now.is-closed { background: var(--surface-3); color: var(--muted); }
.adm-readonly { margin: 10px 0 0; }
.adm-subcard { margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--line-soft); }
.adm-set-also { margin: 10px 0 0; }
/* A setting's form (Chris, 2026-10-19: "the interface is weirdly off, fix them with a clean and easy look"): fields
   down the left, short fields kept short, the buttons in a footer at the card's right edge under a hairline. The form
   spans its card, so a button never floats in the middle of it. */
.adm-set-form { display: grid; gap: 12px; margin-top: 12px; max-width: none; }
.adm-set-form > label:not(.switch):not(.calib-rule-opt):not(.checkbox),
.adm-set-form > .calib-rule-mode, .adm-set-form > fieldset { max-width: 560px; }
.adm-set-form > label > input:not([type="checkbox"]):not([type="radio"]), .adm-set-form > label > select { max-width: 26.25rem; }
.adm-set-form input[type="number"] { width: 6.875rem; max-width: 6.875rem; }
.adm-set-form select.adm-num-select { width: 9.375rem; max-width: 9.375rem; }   /* a number, or No maximum (2026-10-23) */
.adm-set-form input[type="datetime-local"] { width: 15rem; max-width: 100%; }
.adm-set-form > .actions { justify-content: flex-end; margin: 4px 0 0; padding-top: 12px;
  border-top: 1px solid var(--line-soft); }
.adm-set-form > .actions > .muted { margin-right: auto; }   /* a footer's note on the left, its button on the right */
.adm-set-form > p { margin: 0; }
/* a number field reads like every other field; a pair of them ("Minimum / Maximum") sits side by side at the start */
.adm-set-form input[type="number"] { box-sizing: border-box; height: 34px; padding: 0 10px; border: 1px solid var(--line);
  border-radius: 8px; font: inherit; font-size: .9rem; background: var(--surface); }
.adm-set-form .succ-form { display: flex; flex-wrap: wrap; gap: 12px 24px; }
.adm-set-form .succ-form label { display: flex; flex-direction: column; gap: 4px; }
.adm-set-form label.switch .switch-label { font-size: .9rem; }
.adm-set-form .tier-edit { margin: 0; }
/* "Why this matters" sits apart from the form under it, and only its words take the click */
.adm-set-card details.muted { margin: 8px 0 4px; }
.adm-set-card details.muted > summary { width: max-content; max-width: 100%; cursor: pointer; }
.adm-set-card details.muted[open] > p { margin: 6px 0 0; }
/* what needs you: a module's Overview and Home */
.adm-needs { margin-bottom: 16px; }
.adm-needs-head { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; }
.adm-needs-head h2 { margin: 0; font-size: 1.02rem; color: var(--accent-ink); }
.adm-needs-list { list-style: none; margin: 10px 0 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.adm-need { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; padding: 9px 12px; border: 1px solid var(--line); border-radius: 10px; }
.adm-need.is-done { background: var(--d-bg-fafbfc); border-color: var(--line-soft); }
.adm-need-mark { flex: none; box-sizing: border-box; width: 22px; height: 22px; border-radius: 50%; border: 2px solid var(--line-strong); display: inline-flex; align-items: center; justify-content: center; font-size: .72rem; font-weight: 800; }
.adm-need.is-done .adm-need-mark { border: 0; background: var(--d-bg-d7f0e0); color: var(--d-fg-1a7a54); }
.adm-need.is-partial .adm-need-mark { border-color: var(--d-bd-f0a500); }
.adm-need-body { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.adm-need-body b { font-size: .9rem; }
/* N of M on each step, and a step that waits on others (admin round 4, canvas row 1) */
.adm-need-prog { flex: none; width: 12.5rem; display: flex; flex-direction: column; gap: 4px; align-items: flex-end; }
.adm-need-n { font-size: .8rem; color: var(--rl-ink-2, var(--muted)); text-align: right; }   /* wraps at a larger text size (was nowrap: it ran into its caption) */
.adm-need-bar { display: block; width: 100%; height: 5px; border-radius: 3px; background: var(--d-bg-eceef4); overflow: hidden; }
.adm-need-bar i { display: block; height: 100%; background: var(--d-bg-2f64d6); border-radius: 3px; }
.adm-need.is-done .adm-need-bar i { background: var(--ok-fill); }
.adm-need.is-waiting .adm-need-bar i { background: var(--d-bg-9aa1b5); }
.adm-need.is-waiting .adm-need-mark { border-color: var(--d-bd-b8bdcc); border-style: dashed; }
.adm-need-wait { flex: none; width: 14.375rem; text-align: right; font-size: .8rem; color: var(--muted); }
.adm-need-go, .adm-need-done { min-width: 0; }
.adm-need > .adm-need-go, .adm-need > .adm-need-done { width: 14.375rem; box-sizing: border-box; text-align: center; }
@media (max-width: 900px) { .adm-need { flex-wrap: wrap; } .adm-need-prog { width: 100%; align-items: stretch; }
  .adm-need-wait, .adm-need > .adm-need-go, .adm-need > .adm-need-done { width: auto; } }
.adm-need.is-done .adm-need-body b { color: var(--muted); font-weight: 600; }
.adm-need-done { flex: none; font-size: .8rem; font-weight: 700; color: var(--d-fg-1a7a54); }
.adm-home { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: 16px; align-items: start; }
/* Larger and XL at 1024 (polish list, 9 Nov 2026): two columns left the list's words 67px, so "Open ›" was drawn over them; one column up to 1100 */
@media (max-width: 1100px) { html:is([data-text=l], [data-text=xl]) .adm-home { grid-template-columns: minmax(0, 1fr); } }
.adm-home-list { list-style: none; margin: 8px 0 0; padding: 0; }
.adm-home-list li { display: flex; align-items: center; gap: 12px; padding: 9px 2px; border-bottom: 1px solid var(--line-soft); }
.adm-home-mod { flex: none; width: 140px; font-size: max(10px, .7rem); font-weight: 800; letter-spacing: .03em; text-transform: uppercase; color: var(--mc, var(--accent-ink)); }
.adm-home-what { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.adm-home-what b { font-size: .9rem; }
.adm-home .admin-card + .admin-card { margin-top: 0; }
.adm-home-notes h2 { margin: 0; }
.adm-home-notes .adm-home-list li { font-size: .88rem; color: var(--ink-2); }
/* Home's business group x module grid (canvas J1, 2026-10-10) */
.hm-now { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.hm-open { font-size: .8rem; font-weight: 700; border-radius: 999px; padding: 4px 10px; background: var(--d-bg-e6f4ee); color: var(--d-fg-1a7a54);
  white-space: nowrap; }
.hm { margin: 0 0 16px; padding: 0; overflow: hidden; }
.hm-title { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 4px 12px; padding: 12px 16px 8px; }
.hm-title b { color: var(--accent-ink); font-size: .98rem; }
.hm-table { width: 100%; border-collapse: collapse; font-size: .84rem; }
.hm-table th, .hm-table td { padding: 8px 10px; text-align: left; vertical-align: middle; border-top: 1px solid var(--d-bd-f1f2f6); }
.hm-table th:first-child, .hm-table td:first-child { padding-left: 16px; }
.hm-table thead th { background: var(--surface-2); font-size: .76rem; font-weight: 700; color: var(--muted); white-space: nowrap; }
.hm-table thead th a { color: inherit; text-decoration: none; display: inline-flex; align-items: center; gap: 6px; }
.hm-table thead th a:hover { color: var(--accent-ink); }
.hm-table tbody th { font-weight: 700; color: var(--ink); min-width: 120px; max-width: 200px; font-size: .8rem; }
.hm-table td.hm-people { white-space: nowrap; padding-right: 14px; }
.hm-table td.hm-people b { font-weight: 600; color: var(--ink); }
.hm-table .hm-people-all { color: var(--muted); font-weight: 400; }
.hm-total th, .hm-total td { background: var(--surface-2); }
/* Larger and XL at 1024 (Chris's polish list, 9 Nov 2026): the Employees table was 801 wide in a 696 card and scrolled inside it. Three headings read short (full
   words in the th's title and aria-label) and the cells' side padding is 8px (16px between columns, over the 14px minimum), so it fits and every heading stays on one line */
.hm-table .hm-hs { display: none; }
html:is([data-text=l], [data-text=xl]) .hm-table .hm-hl { display: none; }
html:is([data-text=l], [data-text=xl]) .hm-table .hm-hs { display: inline; }
html:is([data-text=l], [data-text=xl]) .hm-table :is(th, td) { padding-left: 8px; padding-right: 8px; }
html:is([data-text=l], [data-text=xl]) .hm-table :is(th, td):first-child { padding-left: 16px; }
html:is([data-text=l], [data-text=xl]) .hm-cell { min-width: 88px; }
.hm-foot { margin: 0; padding: 8px 16px 12px; }   /* what the total holds beyond the rows (a closed group's leavers) */
.hm-cell { display: flex; flex-direction: column; gap: 4px; min-width: 96px; color: inherit; text-decoration: none; }
a.hm-cell:hover { text-decoration: none; }
a.hm-cell:hover { background: var(--d-bg-f5f7fc); box-shadow: 0 0 0 4px var(--d-bg-f5f7fc); border-radius: 8px; }
a.hm-cell:hover .hm-pct b { color: var(--accent-ink); }
.hm-pct { display: flex; align-items: baseline; gap: 8px; }
.hm-pct b { font-size: .95rem; }
.hm-pct { flex-wrap: wrap; }
.hm-pct span { font-size: .72rem; color: var(--d-fg-6b7286); }
.hm-bar { height: 5px; border-radius: 3px; background: var(--surface-3); overflow: hidden; }
.hm-bar span { display: block; height: 5px; }
.hm-ok b { color: var(--d-fg-1a7a54); } .hm-ok .hm-bar span { background: var(--ok-fill); }
.hm-mid b { color: var(--d-fg-7a4b00); } .hm-mid .hm-bar span { background: var(--d-bg-e0a42d); }
.hm-low b { color: var(--d-fg-b42318); } .hm-low .hm-bar span { background: var(--d-bg-e07068); }
.hm-none b { color: var(--faint); }

/* The stage switch strip (Chris, 2026-11-09): the existing .seg-toggle, a size smaller, a dot per stage (green open, grey closed, ring not
   open yet), the stage's line beside it and the way back. It wraps; the matrix keeps its own scroller. */
.hm-stage { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; padding: 2px 16px 12px; }
.hm-stage .seg-toggle { max-width: 100%; flex-wrap: wrap; }
.hm-seg a { padding: 8px 14px; font-size: .86rem; line-height: 1.1; display: inline-flex; align-items: center; gap: 7px; white-space: nowrap; }
.hm-dot { width: 7px; height: 7px; border-radius: 50%; flex: none; box-sizing: border-box; background: currentColor; }
.hm-dot-open { color: var(--d-fg-1a7a54); }
.hm-dot-closed { color: var(--faint); }
.hm-dot-later { color: var(--faint); background: transparent; border: 1.5px solid currentColor; }
.hm-seg a.active .hm-dot-open { color: var(--d-fg-7fe0b4); }
.hm-seg a.active .hm-dot-closed, .hm-seg a.active .hm-dot-later { color: var(--d-fg-c9cdea); }
.hm-when { font-size: .8rem; color: var(--muted); display: inline-flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.hm-when b { color: var(--ink); font-weight: 600; }
.hm-now-pill { font-size: .72rem; font-weight: 700; border-radius: 999px; padding: 3px 9px; background: var(--d-bg-e6f4ee); color: var(--d-fg-1a7a54); }
.hm-back { font-size: .8rem; font-weight: 600; color: var(--link); text-decoration: none; }
a.hm-back:hover { color: var(--accent-ink); background: var(--d-bg-f5f7fc); box-shadow: 0 0 0 4px var(--d-bg-f5f7fc); border-radius: 8px; text-decoration: none; }
.hm-th { display: inline-flex; align-items: center; gap: 6px; }
.hm-table td.hm-extra { white-space: nowrap; font-size: .84rem; }
.hm-n { font-size: .95rem; font-weight: 700; color: var(--ink); }
.hm-quiet { color: var(--d-fg-6b7286); font-size: .72rem; }
.hm-state { font-weight: 600; }
.hm-state.hm-low { color: var(--d-fg-b42318); }
.hm-state.hm-mid { color: var(--d-fg-7a4b00); }
/* Home's Grade H Appraisal card (2026-11-06, canvas boards H1-H3): the matrix's table, one row a group, a stacked bar of where they are */
.gh-hm-name { display: inline-flex; align-items: center; gap: 8px; }
.gh-sq { display: inline-block; width: 10px; height: 10px; border-radius: 3px; background: var(--gh); flex: none; }
.gh-hm-cap { display: inline-flex; flex-wrap: wrap; align-items: baseline; gap: 2px 8px; }
.gh-hm-full { color: var(--accent-ink); font-weight: 700; white-space: nowrap; text-decoration: none; }
.gh-hm-full:hover { text-decoration: none; color: var(--link); }
.gh-hm-table td.gh-hm-num { font-size: .84rem; white-space: nowrap; }
.gh-hm-table tbody tr { height: 44px; }   /* the matrix's row (its cells are two lines); this card's are one */
.gh-hm-table thead th.gh-hm-numh { white-space: nowrap; }
.gh-hm-n { display: inline-block; font-weight: 600; color: var(--ink); text-decoration: none; }
a.gh-hm-n:hover { text-decoration: none; background: var(--d-bg-f5f7fc); box-shadow: 0 0 0 4px var(--d-bg-f5f7fc); border-radius: 8px; color: var(--accent-ink); }
.gh-hm-n.is-zero { font-weight: 400; color: var(--faint); }
.gh-hm-n.is-low { font-weight: 700; color: var(--d-fg-b42318); }
.gh-hm-of { font-weight: 400; color: var(--muted); }
.gh-hm-bar { display: flex; width: 176px; height: 8px; border-radius: 4px; background: var(--surface-3); overflow: hidden; }
.gh-hm-bar span { display: block; height: 8px; }
.gh-b-ns { background: var(--d-bg-e07068); }
.gh-b-lm { background: var(--d-bg-e0a42d); }
.gh-b-cal { background: var(--gh-soft); }
.gh-b-signed { background: var(--gh); }
.gh-b-rel { background: var(--ok-fill); }
.gh-hm-foot { margin: 0; padding: 10px 16px 12px; border-top: 1px solid var(--line-soft); }
.gh-hm-legend { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 16px; margin: 0; font-size: .75rem; line-height: 1.6; color: var(--muted); }
.gh-hm-legend span { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.gh-hm-legend i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; flex: none; }
.gh-hm-wait { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; padding: 12px 16px; }
.gh-hm-wait b { color: var(--accent-ink); font-size: .98rem; }
.gh-hm-wait .gh-hm-full { margin-left: auto; }
.adm-ready { margin-top: 16px; }
.adm-ready > summary { display: flex; justify-content: space-between; align-items: center; gap: 12px; cursor: pointer; list-style: none; }
.adm-ready > summary::-webkit-details-marker { display: none; }
/* the sheet of every setting */
.adm-sheet-search input { width: 18.75rem; height: 38px; box-sizing: border-box; padding: 0 12px; border: 1px solid var(--line-strong); border-radius: 9px; font: inherit; }
.adm-sheet-filters { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; margin: 0 0 12px; }
.adm-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.adm-chip { min-height: 32px; padding: 0 12px; border: 1px solid var(--line-strong); border-radius: 999px; background: var(--surface); color: var(--ink-2); font: inherit; font-size: .82rem; cursor: pointer; }
.adm-chip.is-on { background: var(--accent); border-color: var(--accent-line); color: var(--on-fill); font-weight: 700; }
.adm-sheet-mod { white-space: nowrap; font-size: .82rem; font-weight: 700; color: var(--ink-2); }
.adm-sheet-mod .adm-side-sq { margin-right: 7px; }
.adm-sheet-open { white-space: nowrap; text-align: right; }
.adm-sheet-count { margin: 10px 0 0; }
/* reports */
.adm-rep { margin-bottom: 12px; }
.adm-rep-h { display: flex; align-items: center; gap: 9px; margin: 0 0 6px; font-size: 1rem; color: var(--accent-ink); }
.adm-rep-files { list-style: none; margin: 0; padding: 0; }
.adm-rep-files li { display: flex; align-items: center; gap: 12px; padding: 9px 0; border-top: 1px solid var(--line-soft); }
.adm-rep-name { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.adm-rep-fmt { flex: none; font-size: max(10px, .68rem); font-weight: 800; padding: 2px 8px; border-radius: 999px; background: var(--surface-3); color: var(--ink-2); }
.adm-rep-pages { margin: 8px 0 0; }
.adm-tiles { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-bottom: 16px; }
/* Usage's five tiles (Online now, 2026-11-02): the same grid with a fifth column; the others keep four */
.adm-tiles.adm-tiles-5 { grid-template-columns: repeat(5, minmax(0, 1fr)); }
@media (max-width: 1100px) { .adm-tiles.adm-tiles-5 { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.adm-tile { display: flex; flex-direction: column; gap: 2px; }
.adm-tile b { font-size: 1.5rem; color: var(--accent-ink); }
@media (max-width: 900px) {
  .adm-shell { flex-direction: column; }
  .adm-side { flex: none; width: auto; border-right: 0; border-bottom: 1px solid var(--line); }
  .adm-side-in { position: static; max-height: none; flex-direction: row; flex-wrap: wrap; padding: 8px; }
  .adm-side-sec, .adm-side-rule { display: none; }
  .adm-set { flex-direction: column; }
  .adm-set-index { position: static; flex: none; width: 100%; }
  .adm-home { grid-template-columns: 1fr; }
  .adm-tiles, .adm-tiles.adm-tiles-5 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .adm-search-trigger { min-width: 0; }
  .adm-search-trigger span, .adm-search-trigger kbd { display: none; }
}
/* the cycle calendar (2026-10-10, the canvas's B2) */
.adm-cal-pick select { min-width: 13.75rem; }
.adm-cal { display: flex; align-items: flex-start; gap: 14px; }
.adm-cal-chart { flex: 1; min-width: 0; padding: 12px 16px; }
.adm-cal-side { flex: 0 0 280px; display: flex; flex-direction: column; gap: 12px; }
.adm-cal-scale { display: grid; grid-template-columns: 220px minmax(0, 1fr); align-items: end; padding-bottom: 6px; border-bottom: 1px solid var(--line-soft); }
.adm-cal-h { font-size: max(10px, .68rem); font-weight: 800; letter-spacing: .05em; text-transform: uppercase; color: var(--faint); }
.adm-cal-months { display: grid; font-size: .76rem; font-weight: 700; color: var(--muted); }
.adm-cal-months > span { min-width: 0; padding-right: 9px; }   /* a month label keeps 8px+ from the next: a narrow month wraps its year under the name */
.adm-cal-group { display: flex; align-items: center; gap: 8px; padding: 9px 0 3px; font-size: .84rem; color: var(--accent-ink); }
.adm-cal-row { display: grid; grid-template-columns: 220px minmax(0, 1fr); align-items: center; padding: 4px 6px; margin: 0 -6px; border-radius: 7px; color: var(--ink); text-decoration: none; }
.adm-cal-row:hover { background: var(--d-bg-f4f5f9); text-decoration: none; }
.adm-cal-row.is-sel { background: var(--d-bg-eef1fa); box-shadow: inset 0 0 0 1.5px var(--accent-line); }
.adm-cal-name { padding-left: 18px; padding-right: 8px; font-size: .82rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.adm-cal-track { position: relative; height: 20px; }
.adm-cal-mline { position: absolute; top: -4px; bottom: -4px; width: 1px; background: var(--surface-3); }
.adm-cal-bar { position: absolute; top: 1px; height: 18px; box-sizing: border-box; padding: 0 6px; border-radius: 5px; font-size: max(10px, .68rem); font-weight: 700; line-height: 1.125rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; background: var(--t); color: var(--ink); }
.adm-cal-bar.is-open { background: var(--c); color: var(--on-fill); }
.adm-cal-bar.is-undated { background: repeating-linear-gradient(-45deg, var(--surface), var(--surface) 5px, var(--d-bg-f1f2f6) 5px, var(--d-bg-f1f2f6) 10px); border: 1px dashed var(--d-bd-c4c8d4); color: var(--muted); }
.adm-cal-out { position: absolute; top: 1px; line-height: 1.125rem; font-size: max(10px, .68rem); font-weight: 700; color: var(--ink-2); white-space: nowrap; }
.adm-cal-today { position: absolute; top: -5px; bottom: -5px; width: 2px; margin-left: -1px; background: var(--ai); }
.adm-cal-key { display: flex; flex-wrap: wrap; gap: 14px; margin: 12px 0 0; }
.adm-cal-key span { display: inline-flex; align-items: center; gap: 6px; }
.adm-cal-k { display: inline-block; width: 14px; height: 10px; border-radius: 3px; }
.adm-cal-k.is-today { width: 2px; height: 14px; background: var(--ai); border-radius: 0; }
.adm-cal-k.is-open { background: var(--accent); }
.adm-cal-k.is-tint { background: var(--d-bg-dbe0f0); }
.adm-cal-k.is-undated { background: repeating-linear-gradient(-45deg, var(--surface), var(--surface) 3px, var(--line) 3px, var(--line) 6px); border: 1px dashed var(--d-bd-c4c8d4); }
.adm-cal-edit { box-shadow: 0 0 0 1.5px var(--accent-line); }
.adm-cal-eyebrow { margin: 0; font-size: max(10px, .68rem); font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: var(--c, var(--accent-ink)); }
.adm-cal-edit h2, .adm-cal-card h2 { margin: 2px 0 8px; font-size: 1rem; color: var(--accent-ink); }
.adm-cal-edit label { display: flex; flex-direction: column; gap: 4px; font-size: .8rem; font-weight: 700; color: var(--ink-2); }
.adm-cal-btns { display: flex; gap: 8px; margin-top: 10px; }
.adm-cal-btns .primary { flex: 1; }
.adm-cal-mod { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 4px 0; font-size: .86rem; }
.adm-cal-mod input { width: 16px; height: 16px; accent-color: var(--accent-ink); }
@media (max-width: 1100px) { .adm-cal { flex-direction: column; } .adm-cal-side { flex: none; width: 100%; } }
@media (max-width: 700px) { .adm-cal-scale, .adm-cal-row { grid-template-columns: 150px minmax(0, 1fr); } }
/* the OneHR Admin Agent (2026-10-10): docked on the right of every admin page, in the AI look (red marks the AI) */
.adm-agent[hidden] { display: none; }
.adm-agent { position: fixed; right: 16px; bottom: 84px; z-index: 885; width: 420px; max-width: calc(100vw - 32px);
  height: min(590px, calc(100vh - 140px)); display: flex; flex-direction: column; background: var(--surface); border: 1px solid var(--line);
  border-radius: 16px; overflow: hidden; box-shadow: 0 24px 60px -18px var(--d-sh-141834-a45); }
/* every admin page ends 88px clear of the icon, so the last row and its buttons scroll above it (canvas board A3) */
.adm-main { padding-bottom: 88px; }
.adm-agent-head { display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-bottom: 1px solid var(--line-soft); }
.adm-agent-mark { flex: none; width: 28px; height: 28px; border-radius: 8px; display: inline-flex; align-items: center; justify-content: center; background: var(--ai-tint); color: var(--ai); font-size: 0.9375rem; }
.adm-agent-mark.is-sm { width: auto; height: auto; background: none; font-size: 0.875rem; }
.adm-agent-who { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.adm-agent-who b { font-size: .92rem; color: var(--accent-ink); }
.adm-agent-who span { font-size: .74rem; color: var(--muted); }
.adm-agent-new { border: 1px solid var(--line-strong); background: var(--surface); border-radius: 7px; padding: 5px 9px; font: inherit; font-size: .76rem; color: var(--ink-2); cursor: pointer; }
.adm-agent-x { border: 0; background: none; width: 32px; height: 32px; font-size: 1.25rem; color: var(--muted); cursor: pointer; }
.adm-agent-log { flex: 1; min-height: 0; overflow-y: auto; padding: 14px; display: flex; flex-direction: column; gap: 12px; }
.adm-agent-hello p { margin: 0 0 10px; font-size: .88rem; color: var(--ink-2); }
.adm-agent-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }
.adm-agent-chip { border: 1px solid var(--ai-line); background: var(--ai-tint); color: var(--ai-ink); border-radius: 999px; padding: 6px 11px; font: inherit; font-size: .8rem; text-align: left; cursor: pointer; }
.adm-am-user { align-self: flex-end; max-width: 84%; background: var(--d-bg-eef1fa); border-radius: 12px 12px 4px 12px; padding: 9px 12px; font-size: .88rem; white-space: pre-wrap; }
.adm-am-agent { display: flex; gap: 9px; font-size: .88rem; }
.adm-am-agent > div { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 8px; }
.adm-am-agent p { margin: 0; color: var(--ink); white-space: pre-wrap; }
.adm-am-agent.is-busy p { color: var(--faint); }
.adm-ac { display: flex; flex-direction: column; gap: 3px; padding: 9px 11px; border: 1px solid var(--line); border-radius: 10px; }
.adm-ac b { font-size: .86rem; color: var(--accent-ink); }
.adm-ac-eyebrow { font-size: max(10px, .66rem); font-weight: 800; letter-spacing: .04em; text-transform: uppercase; color: var(--mc, var(--muted)); }
.adm-ac-val { font-size: .82rem; color: var(--ink-2); }
.adm-ac-sub { font-size: .76rem; color: var(--muted); }
.adm-ac-line, .adm-ac-solid { align-self: flex-start; margin-top: 4px; font-size: .8rem; font-weight: 700; border-radius: 8px; padding: 6px 11px; text-decoration: none; }
.adm-ac-line { color: var(--ai-ink); background: var(--ai-tint); border: 1px solid var(--ai-line); }
.adm-ac-solid { color: var(--on-fill); background: var(--ai); border: 1px solid var(--ai); }
.adm-ac-line:hover, .adm-ac-solid:hover { text-decoration: none; filter: brightness(.96); }
.adm-ac-btns { display: flex; flex-wrap: wrap; gap: 8px; }
.adm-ac-scroll { overflow-x: auto; margin: 4px 0 2px; }
.adm-ac-built table { border-collapse: collapse; width: 100%; font-size: .76rem; }
.adm-ac-built th { text-align: left; font-weight: 600; color: var(--muted); padding: 3px 4px; border-bottom: 1px solid var(--line-soft); white-space: nowrap; }
.adm-ac-built td { padding: 4px; border-bottom: 1px solid var(--d-bd-f1f2f6); white-space: nowrap; }
.adm-ac-steps { list-style: none; margin: 4px 0 0; padding: 0; display: flex; flex-direction: column; gap: 5px; font-size: .8rem; }
.adm-ac-steps span { font-size: max(10px, .66rem); font-weight: 800; text-transform: uppercase; color: var(--muted); }
.adm-ac-steps small { color: var(--faint); }
.adm-agent-form { padding: 10px 14px 12px; border-top: 1px solid var(--line-soft); }
.adm-agent-input { display: flex; align-items: flex-end; gap: 8px; border: 1px solid transparent; border-radius: 10px; padding: 4px 4px 4px 12px; }
.adm-agent-input:focus-within { border-color: var(--ai); }
.adm-agent-input textarea { flex: 1; min-width: 0; border: 0; outline: none; resize: none; font: inherit; font-size: .88rem; padding: 7px 0; max-height: 120px; background: transparent; }
.adm-agent-send { flex: none; min-height: 36px; border: 0; border-radius: 8px; background: var(--ai); color: var(--on-fill); font: inherit; font-size: .84rem; font-weight: 700; padding: 0 14px; cursor: pointer; }
.adm-agent-form p { margin: 6px 0 0; font-size: .72rem; color: var(--muted); }
.adm-search-ask b { color: var(--ai-ink); }
.adm-search-ask > span:first-child { color: var(--ai); }
.adm-rep-built .adm-rep-dl + .adm-rep-dl { margin-left: 0; }
@media (max-width: 1100px) { body.adm-agent-on .adm-shell { margin-right: 0; } .adm-agent { width: min(420px, 100vw); } }
.adm-am-agent > .adm-agent-mark { align-self: flex-start; padding-top: 1px; }

/* ---- The person page (canvas row I, 2026-10-10): one person, everything set for them ---- */
.pp { display: flex; flex-direction: column; gap: 10px; }
.pp-crumb a { text-decoration: none; }
.pp-head { display: flex; align-items: center; gap: 14px; padding: 12px 16px; margin: 0; }
.pp-avatar { width: 44px; height: 44px; flex: none; border-radius: 50%; background: var(--d-bg-e2e4f3); color: var(--accent-ink); font-weight: 800; display: flex; align-items: center; justify-content: center; }
.pp-who { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 5px; }
.pp-name-row { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.pp-name { margin: 0; font-size: 1.25rem; color: var(--accent-ink); }
.pp-badges { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.pp-role { font-size: .72rem; font-weight: 700; border-radius: 999px; padding: 2px 8px; background: var(--surface-3); color: var(--ink-2); white-space: nowrap; }
.pp-role.is-lm { background: var(--info-tint); color: var(--info-ink); } .pp-role.is-hod { background: var(--d-bg-d3eef0); color: var(--d-fg-0b5f69); }
.pp-role.is-bu { background: var(--d-bg-ebdff7); color: var(--d-fg-5e2a96); } .pp-role.is-bg { background: var(--d-bg-e2e4f3); color: var(--accent-ink); }
.pp-role.is-mx { background: var(--d-bg-fdf0d5); color: var(--d-fg-7a4b00); }
/* The Line manager / HOD chips and the Roles panel's counts open their people (Chris, 2026-11-06); hover is colour and a ring, never an underline */
a.pp-role.is-link, a.pp-count { text-decoration: none; cursor: pointer; }
a.pp-role.is-link { box-shadow: inset 0 0 0 1px transparent; }
a.pp-role.is-link:hover, a.pp-role.is-link:focus-visible { box-shadow: inset 0 0 0 1px currentColor; text-decoration: none; }
a.pp-count { color: var(--accent-ink); font-weight: 600; border-radius: 4px; padding: 0 4px; margin: 0 -4px; }
/* the HOD row's "heads N: n in <group>, ..." may now be long (any person may head other groups, 2026-11-09): it wraps at the spaces, not past the row */
.pp-r a.pp-count { white-space: normal; min-width: 0; }
a.pp-count:hover, a.pp-count:focus-visible { background: var(--surface-3); text-decoration: none; }
.pp-in { font-size: .78rem; font-weight: 700; color: var(--d-fg-1a7a54); margin: 0 4px 0 4px; }
.pp-out { font-size: .74rem; font-weight: 700; color: var(--d-fg-b42318); }
.pp-cycle select { min-width: 12.5rem; }
.pp-head .pp-cycle { flex: none; flex-shrink: 0; white-space: nowrap; }   /* the cycle picker stays on one line and never shrinks (2026-10-30) */
.pp-head .pp-cycle select { white-space: nowrap; }
.pp-meta .pp-also { display: inline; background: none; border: 0; padding: 0; margin: 0; font: inherit; font-weight: 600; color: var(--accent-ink); cursor: pointer; }
.pp-meta .pp-also:hover { color: var(--d-fg-1d2249); background: var(--d-bg-eef1fa); box-shadow: 0 0 0 3px var(--d-bg-eef1fa); border-radius: 4px; }
.pp-tabs { display: flex; gap: 2px; border-bottom: 1px solid var(--line); }
.pp-tabs a { padding: 7px 12px; color: var(--d-fg-4b5164); text-decoration: none; font-size: .9rem; }
.pp-tabs a.is-on { color: var(--accent-ink); font-weight: 700; border-bottom: 2px solid var(--accent-line); margin-bottom: -1px; }
.pp-past { margin: 0; padding: 8px 12px; border-radius: 10px; background: var(--d-bg-fdf6e3); color: var(--d-fg-6b4b00); font-size: .85rem; }
.pp-grid { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 12px; align-items: start; }
.pp-col { display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.pp-mods { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.pp-mod { margin: 0; padding: 11px 14px; display: flex; flex-direction: column; gap: 4px; border-top: 3px solid var(--mod, var(--accent-line)); font-size: .88rem; }
.pp-mod-h { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.pp-mod-h b { color: var(--accent-ink); font-size: .95rem; }
.pp-mod-h a, .pp-mod a { font-size: .8rem; font-weight: 700; text-decoration: none; }
.pp-mod-convo { grid-column: 1 / -1; }   /* the AI+ conversation (super admin only): one card across both columns */
/* a person's AI+ conversation, in the person page's panel or as a page */
.pp-convo { display: flex; flex-direction: column; gap: 8px; }
.pp-convo-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px;
  margin: 0; font-size: .9rem; color: var(--accent-ink); }
.pp-convo-parts { display: flex; flex-wrap: wrap; gap: 6px; }
.pp-convo-part { border: 1px solid var(--d-bd-d9dce7); border-radius: 999px; padding: 2px 9px; font-size: .74rem; color: var(--d-fg-3a4157); }
.pp-convo-note, .pp-convo-more { margin: 0; }
.pp-convo .rv-transcript { margin-top: 6px; padding-top: 10px; border-top: 1px solid var(--line-soft); }
.pp-convo-page { padding: 14px 18px; }
/* Roles & access (2026-10-20, canvas [design canvas link removed]) */
.rl-tabs { display: flex; gap: 8px; margin: 0 0 14px; }
.rl-tabs a { padding: 7px 14px; border: 1px solid var(--d-bd-d7dbe6); border-radius: 999px; font-size: 0.8125rem; color: var(--ink-2);
  text-decoration: none; background: var(--surface); }
.rl-tabs a.is-on { background: var(--accent); border-color: var(--accent-line); color: var(--on-fill); font-weight: 700; }
