.rl-idle-form { display: contents; }
span.rl-preset { display: inline-flex; align-items: center; cursor: default; }
.rl-more summary { cursor: pointer; color: var(--accent-ink); }
.rl-inline { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-top: 6px; }
