.rl-add-form button.primary { height: 42px; }
.rl-fold { display: flex; align-items: center; gap: 10px; margin: 0 0 4px; }
.rl-foldall { margin-left: auto; border: 0; background: none; color: var(--accent-ink); font: inherit; font-size: 0.78125rem; font-weight: 600;
  text-decoration: underline; cursor: pointer; padding: 4px 0; }
.rl-new { display: inline-block; margin-left: 8px; padding: 1px 6px; border-radius: 4px; background: var(--accent); color: var(--on-fill);
  font-size: max(10px, 0.65625rem); font-weight: 700; letter-spacing: .05em; text-transform: uppercase; vertical-align: 1px; }
.rl-matrix-card { padding: 10px 18px 14px; }
.rl-chips { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 0 0 10px; }
