.fb-grid { display: grid; grid-template-columns: minmax(0, 1.5fr) 72px 92px 110px 130px minmax(0, 1.6fr); gap: 10px; align-items: center; padding: 8px 16px; border-top: 1px solid var(--d-bd-f1f2f6); font-size: .86rem; }
