/* The admin's Talent Box (canvas J2, 2026-10-10; redrawn 2026-10-30, canvas board F): the BG CEO's own card, read only, in the
   BG CEO's own classes (.rv-tbox-*, above); only its frame, the lock pill and the two curve cards are the admin's. */
.atb-card { background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 12px 14px; box-sizing: border-box; min-width: 0; }
.adm-filters + .atb-card { margin-top: 12px; }   /* the layout sweep: 0px under the Business group card, 12px like the curve cards below */
.atb-card [hidden] { display: none !important; }   /* a display rule on .rv-tbox-listwrap / .rv-tbox-filter would beat [hidden] */
.atb-card a.rv-tbox-bu { display: inline-flex; align-items: center; text-decoration: none; }
.atb-card a.rv-tbox-bu.is-on { cursor: default; }
.atb-card a.rv-tbox-pname { display: block; text-decoration: none; }
.atb-card a.rv-tbox-open { display: grid; text-decoration: none; font-size: 1.125rem; line-height: 1; }
.atb-card .rv-tbox-foot { justify-content: flex-end; border-top: 1px solid var(--line-soft); padding-top: 10px; margin-top: 4px; }
.atb-lockpill { flex: none; border: 1px solid var(--line); border-radius: 999px; padding: 4px 12px; font-size: 0.78125rem; color: var(--muted); white-space: nowrap; }
.atb-curves { display: flex; flex-direction: column; gap: 12px; margin-top: 12px; }
.atb-curve { padding: 14px 18px; }
.atb-curve-h { display: flex; align-items: baseline; gap: 4px 10px; flex-wrap: wrap; margin-bottom: 4px; }
.atb-curve-h b { font-size: 0.875rem; color: var(--accent-ink); }
.atb-curve-sub { font-size: 0.78125rem; color: var(--muted); }
.atb-curve .rv-calib-dist .calib-dist-row { margin: 0; min-height: 24px; }
.atb-curve .rv-calib-dist .calib-dist-band, .atb-curve .rv-calib-dist .calib-dist-pct, .atb-curve .rv-calib-dist .calib-dist-gap { font-size: 0.8125rem; }
.atb-curve .rv-calib-dist .calib-dist-pct { color: var(--muted); }
/* ---- Talent Box Round 2 on the admin card (2026-11-15; canvas boards A-E, I, J). The Round toggle sits left of Grid / List; the strip under
   the unit pills enters the actual PAT, chooses Do Round 2 here / Push to BG CEO, or says where a round stands; the one editable card is the
   super admin's admin round. Colour tokens only; AI red only on Suggest with AI, its strip, its marks. ---- */
.atb-card { container-type: inline-size; container-name: atb; }
.atb-card .rv-cal-titlebar .rv-cal-count { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* too narrow for the title, both toggles and the count on one row (1024 wide, or the larger text sizes): the count drops to its own line under them */
@container atb (max-width: 60rem) {
  .atb-card .rv-cal-titlebar { flex-wrap: wrap; row-gap: 4px; }
  .atb-card .rv-cal-titlebar .rv-cal-count { order: 5; flex: 1 1 100%; }
}
.atb-card .rv-tbox-views.is-rounds { margin-left: auto; }
.atb-card .rv-tbox-views.is-rounds + .rv-tbox-views { margin-left: 0; }   /* the bar's own 12px gap sits between the two groups */
.atb-card .rv-tbox-views.is-rounds .rv-tbox-view { text-decoration: none; padding: 0 8px; white-space: nowrap; }
.atb-card .rv-tbox-views.is-rounds .rv-tbox-view:hover { text-decoration: none; background: var(--surface); }
.atb-card .rv-tbox-views.is-rounds .rv-tbox-view[aria-current="page"] { background: var(--accent); color: var(--on-fill); box-shadow: none; }
.atb-tag { flex: none; font-size: max(10px, 0.6875rem); font-weight: 700; line-height: 1.5; border-radius: 999px; padding: 0 7px; white-space: nowrap; }
.atb-tag.is-warn { background: var(--warn-tint); color: var(--warn-ink); }
.atb-tag.is-ok { background: var(--ok-tint); color: var(--ok-ink); }
.atb-tag.is-navy { background: var(--info-tint); color: var(--info-ink); }
.atb-card a.rv-tbox-bu .atb-tag { margin-left: 6px; }
.atb-r2 { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; border: 1px solid var(--line); background: var(--surface-2);
  border-radius: 12px; padding: 10px 14px; min-width: 0; }
.atb-r2.is-ai { background: var(--ai-tint); border-color: var(--ai-line); }
.atb-r2-form { display: contents; }
.atb-r2-k { flex: none; font-size: 0.75rem; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); }
.atb-r2-fig { flex: none; display: flex; flex-direction: column; gap: 1px; }
.atb-r2-v { font-size: 0.9375rem; font-weight: 700; color: var(--ink); font-variant-numeric: tabular-nums; }
.atb-r2-c { font-size: 0.78125rem; color: var(--muted); }
.atb-r2-arrow { flex: none; color: var(--muted); font-size: 1.125rem; }
.atb-r2-say { flex: 1 1 16rem; min-width: 0; font-size: 0.8125rem; line-height: 1.45; color: var(--ink-2); }
.atb-r2-say b { color: var(--ink); }
.atb-r2-say a { color: var(--link); font-weight: 600; text-decoration: none; border-radius: 4px; }
.atb-r2-say a:hover { background: var(--surface-3); }
.atb-r2-acts { flex: 0 1 auto; min-width: 0; max-width: 100%; display: flex; align-items: center; flex-wrap: wrap; gap: 8px; }
.atb-btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 34px; padding: 0 14px; border-radius: 8px;
  border: 1px solid transparent; font: inherit; font-size: 0.8125rem; font-weight: 700; white-space: nowrap; cursor: pointer; }
.atb-btn.is-navy { background: var(--accent); color: var(--on-fill); }
.atb-btn.is-navy:hover:not(:disabled) { background: var(--accent-hover); }
.atb-btn.is-out { background: var(--surface); border-color: var(--line-strong); color: var(--accent-ink); }
