.atb-btn:disabled { opacity: 0.45; cursor: default; }
.atb-btn:focus-visible, .atb-inp:focus-within, .atb-lockby input:focus-visible { outline: 2px solid var(--accent-line); outline-offset: 2px; }
.atb-inp { flex: none; display: inline-flex; align-items: center; gap: 4px; min-height: 34px; padding: 0 10px; border: 1.5px solid var(--accent-line);
  border-radius: 8px; background: var(--surface); color: var(--ink); }
.atb-inp input { width: 5rem; min-width: 0; border: 0; outline: 0; background: transparent; font: inherit; font-size: 0.9375rem; font-weight: 700;
  color: var(--ink); text-align: right; font-variant-numeric: tabular-nums; }
.atb-inp-u { color: var(--muted); font-weight: 600; }
.atb-lockby { flex: none; display: inline-flex; align-items: center; gap: 8px; font-size: 0.8125rem; color: var(--ink-2); }
.atb-lockby input { min-height: 34px; padding: 0 8px; border: 1px solid var(--line-strong); border-radius: 8px; background: var(--surface);
  color: var(--ink); font: inherit; font-size: 0.8125rem; }
.atb-ailist { flex: 1 1 100%; margin: 0; padding-left: 18px; display: grid; gap: 2px; font-size: 0.8125rem; color: var(--ink-2); }
.atb-sgrow { display: flex; align-items: center; min-height: 18px; }
.atb-sg, .atb-sugg { flex: none; font-size: max(10px, 0.6875rem); font-weight: 700; color: var(--ai-ink); background: var(--surface);
  border: 1px dashed var(--ai); border-radius: 999px; padding: 0 6px; white-space: nowrap; }
.atb-sugg.is-list { display: inline-block; margin-top: 2px; margin-left: 25px; }
.atb-vs { font-weight: 600; }
.atb-vs.is-good { color: var(--ok-ink); }
.atb-vs.is-bad { color: var(--warn-ink); }
.atb-lockpill.is-ok { border-color: transparent; background: var(--ok-tint); color: var(--ok-ink); font-weight: 600; }
.atb-lockpill.is-warn { border-color: transparent; background: var(--warn-tint); color: var(--warn-ink); font-weight: 600; }
.atb-note { margin: 0 0 12px; }
.atb-card .rv-tbox-cellh { gap: 8px; }   /* "PIP/Improvement" and "3 moved": 8px apart, not 6 (text separation) */

/* The Group Chief's calibration card in the chat (canvas G2, 2026-10-10): BG, then unit, then department, one row each */
.rv-grp { display: flex; flex-direction: column; gap: 10px; }
.rv-grp-note { margin: 0; font-size: 0.8125rem; color: var(--ink-2); }
.rv-grp-filters { display: flex; flex-direction: column; gap: 6px; }
.rv-grp-frow { display: grid; grid-template-columns: 116px minmax(0, 1fr); align-items: center; gap: 8px; }
.rv-grp-flbl { font-size: max(10px, 0.6875rem); font-weight: 800; letter-spacing: .04em; text-transform: uppercase; color: var(--muted); }
.rv-grp-tablewrap { max-height: 420px; overflow: auto; border: 1px solid var(--line); border-radius: 10px; }
.rv-grp-table { width: 100%; border-collapse: collapse; font-size: 0.8125rem; }
.rv-grp-table th { position: sticky; top: 0; z-index: 1; background: var(--surface-2); text-align: left; font-size: max(10px, 0.71875rem);
  font-weight: 700; color: var(--muted); padding: 7px 10px; }
.rv-grp-table td { padding: 7px 10px; border-top: 1px solid var(--d-bd-f1f2f6); vertical-align: middle; }
