.rv-grp-tick { width: 26px; }
.rv-grp-where { display: block; font-size: max(10px, 0.71875rem); color: var(--d-fg-6b7286); }
.rv-grp-sel { font: inherit; font-size: 0.78125rem; padding: 3px 6px; border: 1px solid var(--line-strong); border-radius: 6px; background: var(--surface); }
.rv-grp-locked { font-weight: 700; color: var(--d-fg-1a7a54); }
.rv-grp-moved { font-size: 0.75rem; font-weight: 700; color: var(--d-fg-7a4b00); }
.rv-grp-foot { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.rv-grp-lockf { margin: 0; }
.rv-tbox-grp { margin-left: 6px; font-size: max(10px, 0.65625rem); font-weight: 700; border-radius: 999px; padding: 1px 7px;
  background: var(--d-bg-fdf0d5); color: var(--d-fg-7a4b00); white-space: nowrap; }

/* ============================================================================================================
   The admin page kit (canvas K2, 2026-10-10): one way to title, filter, list, confirm and save on every admin page
   ============================================================================================================ */
/* the shell names the page; a page title that carries data (a person, a check) stays, at the shell's own scale */
.adm-main .page-head h1 { font-size: 1.25rem; line-height: 1.3; color: var(--accent-ink); }
.adm-lede { margin: 0 0 14px; color: var(--muted); font-size: .92rem; max-width: 900px; }
.adm-lede b { color: var(--accent-ink); }
.adm-headrow { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin: 0 0 14px; }
.adm-headrow .adm-lede { margin: 0; }
.adm-headrow-acts { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
/* a link that is the page's main action looks like the primary button (Users' "Add a person") */
a.primary { display: inline-flex; align-items: center; background: var(--accent); color: var(--on-fill); border: 1px solid var(--accent-line);
  border-radius: var(--rl-btn-radius); font-weight: 600; padding: 7px 14px; text-decoration: none; }
a.primary:hover { background: var(--accent-hover); border-color: var(--d-bd-1d2249); color: var(--on-fill); text-decoration: none; }
/* a table that opens its card sits at the card's top, not 14px under it */
.admin-card > .table-scroll:first-child { margin-top: 0; }
/* filter rows: business group, then unit, then department, one row each */
.admin-card.adm-filters { padding: 12px 16px; display: flex; flex-direction: column; gap: 8px; }
.adm-frows { display: flex; flex-direction: column; gap: 6px; }
.adm-frow { display: grid; grid-template-columns: 120px minmax(0, 1fr); align-items: center; gap: 8px; }
.adm-frow-lbl { font-size: max(10px, .68rem); font-weight: 800; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
.adm-frow-track { display: flex; align-items: center; gap: 6px; min-width: 0; }
.adm-frow-pills { flex: 1 1 auto; min-width: 0; display: flex; gap: 6px; overflow-x: auto; overflow-y: hidden;
  scrollbar-width: none; }
.adm-frow-pills::-webkit-scrollbar { display: none; }
.adm-frow-pill { flex: none; display: inline-flex; align-items: center; gap: 8px; padding: 4px 12px; border-radius: 999px;
  border: 1px solid var(--line-strong); background: var(--surface); color: var(--ink-2); font-size: .8rem; text-decoration: none; white-space: nowrap; }
.adm-frow-pill span { color: var(--faint); font-size: .72rem; }
.adm-frow-pill:hover { text-decoration: none; border-color: var(--accent-line); color: var(--accent-ink); }
.adm-frow-pill.is-on { background: var(--accent); border-color: var(--accent-line); color: var(--on-fill); font-weight: 700; }
.adm-frow-pill.is-on span { color: var(--d-fg-c9cde3); }
.adm-frow-nav { display: none; flex: none; width: 28px; height: 28px; padding: 0; border-radius: 50%; border: 1px solid var(--line-strong);
  background: var(--surface); color: var(--accent-ink); cursor: pointer; align-items: center; justify-content: center; }
.adm-frow-track.is-overflow .adm-frow-nav { display: inline-flex; }
.adm-frow-nav[disabled] { opacity: .35; cursor: default; }
/* the search row under the filter rows */
.adm-fsearch { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.rr-bandvis > summary { cursor: pointer; display: flex; gap: 10px; align-items: center; flex-wrap: wrap; list-style: none; }
.rr-bandvis > summary::-webkit-details-marker { display: none; }
.rr-bandvis[open] > summary { margin-bottom: 10px; }
.bw-all { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin: 4px 0 10px; font-size: .88rem; }
/* the potential band cutoffs card: this cycle first, the default folded under it (2026-10-11) */
.pc-block { border: 1px solid var(--line); border-radius: 10px; padding: 12px 14px; margin: 10px 0 12px; max-width: 560px; }
.pc-h { margin: 0 0 8px; display: flex; gap: 8px; align-items: baseline; }
.pc-form label { display: flex; flex-direction: column; gap: 4px; font-size: .85rem; margin-bottom: 8px; }
.pc-in { display: flex; gap: 8px; align-items: center; }
.pc-in input { width: 96px; }
.pc-default summary { cursor: pointer; color: var(--accent-ink); }
.adm-fsearch select, .adm-fsearch .modern-select { width: auto; flex: 0 0 auto; min-width: 9.375rem; }
/* Search in is one width on every list (2026-10-26): Participants' .rr-filters widens its other selects to 210px */
.adm-fsearch select.modern-select.adm-qin { min-width: 9.375rem; }
.adm-frows + .adm-fsearch { border-top: 1px solid var(--d-bd-f1f2f6); padding-top: 8px; }
.adm-fsearch input[type=search], .adm-fsearch input[type=text] { flex: 1 1 16.25rem; min-width: 12.5rem; text-overflow: ellipsis; min-height: 34px;
  box-sizing: border-box; padding: 0 10px; border: 1px solid var(--line-strong); border-radius: 8px; font: inherit; font-size: .88rem; }
.adm-filters .adm-fsearch .adm-field-date { display: inline-flex; align-items: center; }
.adm-filters .adm-fsearch button.btn-link, .adm-filters .adm-fsearch > a.btn-link { box-sizing: border-box; height: 34px; display: inline-flex; align-items: center; }
.adm-fsearch label.adm-field { display: flex; flex-direction: column; gap: 2px; font-size: .72rem; color: var(--muted); }
.adm-fsearch .adm-count { font-size: .8rem; color: var(--muted); }
/* classes some pages used without a rule (the review, 2026-10-10) */
a.btn, button.btn { display: inline-flex; align-items: center; gap: 6px; padding: 7px 12px; border: 1px solid var(--line);
  border-radius: 7px; background: var(--surface); color: var(--accent-ink); font: inherit; font-size: .85rem; font-weight: 600;
  text-decoration: none; cursor: pointer; }
a.btn:hover, button.btn:hover { background: var(--d-bg-f3f4f8); text-decoration: none; }
a.btn.primary, button.btn.primary { background: var(--accent); border-color: var(--accent-line); color: var(--on-fill); }
.filter-row { display: flex; gap: 12px; flex-wrap: wrap; align-items: flex-end; }
.filter-row label { display: flex; flex-direction: column; gap: 3px; font-size: .78rem; color: var(--muted); }
.flash-info { background: var(--info-tint); color: var(--info-ink); }
/* the one-field question and the notice (base.html openTextPrompt / openNotice) */
.dp-card input[type=text], .dp-card input[type=email], .dp-card input[type=password] { width: 100%; box-sizing: border-box;
  height: 36px; padding: 0 10px; border: 1px solid var(--line-strong); border-radius: 8px; font: inherit; margin: 4px 0 12px; }
/* Leaders and admins > Admins (canvas K8) */
/* the row's actions on one line (a flex cell squeezed them into a column); Change opens under them */
.admin-table td.adm-admins-acts { white-space: nowrap; text-align: right; }
.adm-admins-acts > form, .adm-admins-acts > details { display: inline-block; vertical-align: top; margin: 0 0 0 10px; }
