.adm-inline-edit[open] { display: block !important; margin: 0 0 6px !important; }
.adm-inline-form { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 8px 0; }
.adm-units { border: 0; padding: 0; margin: 8px 0; display: flex; flex-wrap: wrap; gap: 6px 14px; }
.adm-units legend { padding: 0; margin-bottom: 4px; }
.adm-units label { display: inline-flex; align-items: center; gap: 5px; font-size: .86rem; }
.adm-units-group { display: flex; flex-wrap: wrap; gap: 6px 14px; }
.adm-units-group[hidden] { display: none; }
.status-pill.adm-scope-super { background: var(--accent); color: var(--on-fill); }
/* one page with modes (Panels, Import, Calendar): a segmented switch at the top */
.adm-modes { display: inline-flex; border: 1px solid var(--line-strong); border-radius: 9px; overflow: hidden; margin: 0 0 12px; background: var(--surface); }
.adm-modes a { padding: 6px 14px; font-size: .86rem; color: var(--ink-2); text-decoration: none; border-left: 1px solid var(--line-strong); }
