.adm-users td:last-child .btn-link { min-height: 0; padding: 2px 6px; }   /* Open: a link, so the row stays one line high */
.adm-role { display: inline-block; margin: 0 8px 2px 0; font-size: max(10px, .7rem); font-weight: 700; border-radius: 999px; padding: 1px 8px;
  background: var(--d-bg-eef1fa); color: var(--accent-ink); }
