.adm-form-acts { display: flex; gap: 10px; align-items: center; margin-top: 12px; }
/* People > Users > Mark several as left / Bring people back (2026-10-10): the choose bar over the table */
.adm-bulk-bar { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; margin: 0 0 10px; min-height: 34px; }
.adm-bulk-acts { margin-left: auto; display: inline-flex; gap: 10px; align-items: center; }
.adm-bulk-acts[hidden] { display: none; }
.adm-bulk-acts button { white-space: nowrap; }
.adm-bulk-acts select { width: 16.25rem; max-width: 16.25rem; }   /* Give a user role's pick (2026-10-23) */
.admin-table th.adm-cb-col { width: 34px; }
.adm-add-user .pp-fields { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px 14px; }
.adm-add-user .pp-fields label { display: flex; flex-direction: column; gap: 4px; font-size: .8rem; color: var(--muted); }
.pp-acts { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; }
.pp-acts form { margin: 0; }
/* the person page's 360 tab: change a relationship, add someone by name (canvas K7) */
.pp-relsel { height: 30px; font-size: .8rem; padding: 0 6px; }
.pp-addsearch { position: relative; flex-wrap: wrap; }
.pp-addq { flex: 1 1 220px; min-height: 34px; box-sizing: border-box; padding: 0 10px; border: 1px solid var(--line-strong); border-radius: 8px; font: inherit; font-size: .86rem; }
.pp-addres { position: absolute; z-index: 5; top: 40px; left: 0; right: 0; background: var(--surface); border: 1px solid var(--line); border-radius: 10px;
  box-shadow: 0 8px 22px var(--d-sh-252a59-a12); padding: 4px; display: flex; flex-direction: column; max-height: 260px; overflow: auto; }
.pp-addres[hidden] { display: none; }
