.adm-bar .is-ok { background: var(--ok-fill); } .adm-bar .is-mid { background: var(--d-bg-e0a42d); } .adm-bar .is-low { background: var(--d-bg-e07068); }
/* Cycle > Calendar > This cycle (canvas K6) */
.adm-cyc { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; margin-bottom: 16px; }
.adm-cyc-cell { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.adm-cyc-lbl { font-size: max(10px, .68rem); font-weight: 800; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
.adm-cyc-cell > b { color: var(--accent-ink); font-size: 1rem; }
.adm-cyc-form { display: flex; gap: 6px; align-items: center; flex-wrap: wrap; margin: 2px 0; }
.adm-cyc-mods { display: flex; flex-wrap: wrap; gap: 6px; }
.adm-cyc-mod { font-size: .72rem; font-weight: 700; border-radius: 999px; padding: 2px 8px; background: var(--d-bg-e6f4ee); color: var(--d-fg-1a7a54); }
.adm-cyc-mod.is-off { background: var(--surface-3); color: var(--faint); text-decoration: line-through; }
.adm-cal-closef { margin: 6px 0 0; }

/* ---- Ask OneHR on the dashboard (the canvas "OneHR Ask Agent and Admin Standard", row A; 2026-10-11) ---- */
.ask-panel { position: fixed; right: 16px; bottom: 84px; width: 400px; max-width: calc(100vw - 32px);
  height: min(560px, calc(100vh - 140px)); z-index: 880; background: var(--surface); border: 1px solid var(--line);
  border-radius: 16px; overflow: hidden; box-shadow: 0 24px 60px -18px var(--d-sh-141834-a45);
  display: flex; flex-direction: column; }
