.ask-ai { width: 22px; height: 22px; border-radius: 6px; background: var(--ai-tint); color: var(--ai); font-size: max(10px, 0.6875rem);
  font-weight: 800; display: flex; align-items: center; justify-content: center; flex: none; }
.ask-msg.is-agent > p, .ask-body > p { margin: 0; background: var(--surface-2); border-radius: 12px; padding: 10px 12px; }
.ask-body { display: flex; flex-direction: column; gap: 8px; min-width: 0; flex: 1; }
.ask-card { display: flex; align-items: center; gap: 10px; border: 1px solid var(--line); border-radius: 10px;
  padding: 10px 12px; background: var(--surface); color: var(--ink); text-decoration: none; font: inherit; text-align: left;
  cursor: pointer; width: 100%; }
