.ask-note { font-size: max(10px, 0.6875rem); color: var(--faint); }
.ask-try-h { margin: 0 0 8px; font-size: max(10px, 0.6875rem); font-weight: 800; letter-spacing: .08em; color: var(--faint); text-transform: uppercase; }
.ask-try { display: flex; flex-direction: column; gap: 8px; }
.ask-sugg { text-align: left; border: 1px solid var(--ai-line); background: var(--surface); color: var(--ai-ink); border-radius: 10px;
  padding: 10px 12px; font: inherit; font-size: 0.8125rem; font-weight: 600; cursor: pointer; }
.ask-sugg:hover { background: var(--ai-tint); }
.ask-chips { display: flex; flex-wrap: wrap; gap: 6px; padding-left: 30px; }
.ask-chip { border: 1px solid var(--ai-line); background: var(--surface); color: var(--ai-ink); border-radius: 999px;
  padding: 6px 10px; font: inherit; font-size: 0.75rem; cursor: pointer; }
.ask-thinking { margin: 0 0 0 30px; font-size: 0.8125rem; color: var(--faint); }
.ask-form { display: flex; gap: 8px; padding: 12px 18px 6px; border-top: 1px solid var(--line-soft); }
