.rr2-chip { display: inline-flex; align-items: center; gap: 5px; min-height: 28px; padding: 0 10px; border: 1px solid var(--line);
  border-radius: 8px; background: var(--surface); color: var(--d-fg-4b5164); text-decoration: none; }
