.rr2-table td.rr2-person .muted { display: block; margin-top: 1px; }
.rr2-st { font-size: .78rem; font-weight: 700; color: var(--faint); white-space: nowrap; }
.rr2-st.is-ok { color: var(--d-fg-1a7a54); }
.rr2-st.is-warn { color: var(--warn-ink); }
.rr2-st.is-part { color: var(--ink-2); }
.rr2-rep { display: block; margin-top: 2px; font-size: .72rem; color: var(--muted); }
.rr2-table td.rr2-actcol { text-align: right; white-space: nowrap; }
.rr2-act { min-height: 30px; padding: 0 10px; border: 1px solid var(--accent-line); border-radius: 8px; background: var(--surface); color: var(--accent-ink);
  font: inherit; font-size: .76rem; font-weight: 700; cursor: pointer; white-space: nowrap; }
.rr2-act.is-solid { background: var(--accent); color: var(--on-fill); }
.rr2-table tr.rr2-goto > td { background: var(--d-bg-fff7e6) !important; transition: background .3s; }
.rr2-foot { position: sticky; bottom: 0; z-index: 2; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-top: 10px;
  padding: 10px 12px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); }
.rr2-sel { font-size: .84rem; font-weight: 700; color: var(--accent-ink); }
.rr2-note { flex: 1; min-width: 120px; text-align: right; font-size: .78rem; color: var(--muted); }
.rr2-btn { min-height: 36px; padding: 0 14px; border: 1px solid var(--accent-line); border-radius: 8px; background: var(--surface); color: var(--accent-ink);
  font: inherit; font-size: .84rem; font-weight: 700; cursor: pointer; }
