.rr2-btn:disabled { opacity: .45; cursor: default; }
.rr2-revoke { position: relative; }
.rr2-revmenu { position: absolute; right: 0; bottom: calc(100% + 6px); z-index: 5; min-width: 220px; display: flex; flex-direction: column;
  padding: 6px; background: var(--surface); border: 1px solid var(--line); border-radius: 10px; box-shadow: 0 12px 30px -12px var(--d-sh-141834-a35); }
.rr2-revmenu[hidden] { display: none; }
.rr2-revmenu button { text-align: left; padding: 8px 10px; border: 0; border-radius: 7px; background: none; font: inherit; font-size: .84rem;
  color: var(--ink); cursor: pointer; }
