.rr2-dl-k { margin: 0 0 6px; font-size: max(10px, .7rem); font-weight: 800; letter-spacing: .05em; text-transform: uppercase; color: var(--ink-2); }
.rr2-dl-ul { list-style: none; margin: 0; padding: 0; border: 1px solid var(--line); border-radius: 10px; max-height: 180px; overflow-y: auto; }
.rr2-dl-ul li { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: 7px 12px; font-size: .84rem; }
.rr2-dl-ul li + li { border-top: 1px solid var(--line-soft); }
.rr2-dl-ul li .m { color: var(--muted); font-size: .78rem; text-align: right; }
.rr2-held { background: var(--d-bg-fdf6ec); border: 1px solid var(--d-bd-f0d9b5); border-radius: 10px; padding: 10px 12px; display: flex; flex-direction: column; gap: 6px; }
.rr2-held > b { font-size: .84rem; color: var(--d-fg-8a4a12); }
.rr2-held > span { font-size: .78rem; color: var(--d-fg-8a4a12); }
