.ri-verdict.is-bad .ri-verdict-ic { background: var(--d-bg-c0473f); }
.ri-verdict.is-warn .ri-verdict-ic { background: var(--d-bg-c98a16); }
.ri-verdict.is-ok .ri-verdict-ic { background: var(--ok-fill); }
.ri-verdict-t { flex: 1; display: flex; flex-direction: column; gap: 2px; font-size: .88rem; color: var(--d-fg-3b4150); }
.ri-verdict-t b { color: var(--ink); font-size: .95rem; }
/* the KPI import's decisions (2026-10-26, every import in four steps): a line matching its unit's BU KPI, the super
   admin's pick per line between two segments, the chosen one navy */
.kti-decide { border: 1px solid var(--d-bd-f1dcb1); }
.kti-who { font-size: .75rem; font-weight: 700; color: var(--accent-ink); background: var(--d-bg-eef1fa); border-radius: 999px; padding: 3px 10px; white-space: nowrap; }
.kti-group { border: 1px solid var(--line); border-radius: 10px; overflow: hidden; margin: 12px 0; }
.kti-ghead { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; padding: 10px 14px; background: var(--surface-2); border-bottom: 1px solid var(--line); }
.kti-ghead > div { flex: 1; min-width: 240px; display: flex; flex-direction: column; gap: 2px; }
.kti-ghead > div > b { color: var(--accent-ink); }
.kti-all { display: inline-flex; gap: 10px; flex-wrap: wrap; }
.kti-table td { vertical-align: top; }
.kti-fixed { table-layout: fixed; width: 100%; }   /* the KPI targets import's step 3: four fixed columns (board D1); the roster import's tables keep theirs */
.kti-fixed td { overflow-wrap: anywhere; }
.kti-fixed th { white-space: nowrap; }
.kti-c-person { width: 150px; }   /* Person: the name, then "ID · unit" under it (board D1, 2026-11-07; px as the board draws them: Decide keeps the rest at every text size) */
.kti-c-line { width: 240px; }     /* Line in the file */
.kti-c-target { width: 190px; }   /* The file's target, "Weight N%" under it; Decide takes the rest (about 380px at 1280, 324px at the largest text size) */
.kti-fixed .kti-tag { max-width: 100%; box-sizing: border-box; white-space: normal; overflow-wrap: anywhere; border-radius: 12px; line-height: 1.3; vertical-align: top; }   /* a tag with a long unit name wraps inside its column (never clipped, never over the next column); the full words are also its title */
.kti-nm { font-weight: 700; }
.kti-sub { margin-top: 2px; }
.kti-quote { margin-top: 2px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.kti-w { font-size: .78rem; color: var(--ink-2); margin-top: 3px; }
.kti-why { margin-top: 4px; }
/* a decide group's explanation sits inside the group's border, 14px in like its heading and table (2026-11-08: it touched the border) */
.kti-group > .kti-why { margin: 0; padding: 8px 14px; }
.kti-offered { margin: 0; padding: 10px 14px; }
.kti-tlab { font-size: .8rem; font-weight: 600; color: var(--ink); }
/* Decide is a select on every line (the toggle goes): it fills its cell and is never clipped; red until picked */
.kti-pick, .kti-tsel { box-sizing: border-box; max-width: 100%; border: 1px solid var(--line-strong); border-radius: 8px; background: var(--surface); color: var(--ink); font: inherit; font-weight: 600; padding: 0 10px; text-overflow: ellipsis; }
.kti-pick { width: 100%; min-height: 2.125rem; font-size: .8125rem; }
.kti-tsel { min-height: 1.875rem; font-size: .8rem; max-width: 22rem; }
.kti-pick.is-rec { border-color: var(--accent-line); }
.kti-pick.is-open, .kti-tsel.is-open { border: 2px solid var(--danger-ink); color: var(--bad-ink); }
.kti-pick:disabled, .kti-tsel:disabled { opacity: .7; cursor: not-allowed; }
.kti-pick:focus-visible, .kti-tsel:focus-visible { outline: 2px solid var(--accent-line); outline-offset: 2px; }
.kti-group.is-new { border-color: var(--accent-line); }
.kti-tag { display: inline-block; margin-top: 4px; font-size: .72rem; font-weight: 700; border-radius: 999px; padding: 2px 9px; background: var(--d-bg-eef1fa); color: var(--accent-ink); white-space: nowrap; }
.kti-tag.is-same { background: var(--d-bg-e9f5f0); color: var(--d-fg-1a7a54); }
.kti-tag.is-diff { background: var(--d-bg-fdf6e8); color: var(--d-fg-7a4b00); }
/* a group's one written reason (the roster's hand-over, 2026-10-30) */
.kti-reason { display: flex; flex-direction: column; gap: 4px; margin: 12px 14px 14px; font-size: .82rem; font-weight: 600; color: var(--d-fg-2f3552); }
.kti-reason textarea { width: 100%; box-sizing: border-box; border: 1px solid var(--line-strong); border-radius: 8px; padding: 8px 10px;
  font: inherit; font-size: .85rem; font-weight: 400; resize: vertical; }
.kti-reason .muted { font-weight: 400; }
.kti-seg { display: inline-flex; white-space: nowrap; }
.kti-seg label { position: relative; display: inline-flex; }
.kti-seg input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.kti-seg span { display: inline-flex; align-items: center; min-height: 34px; padding: 0 12px; border: 1px solid var(--d-bd-cfd3de); background: var(--surface); color: var(--ink); font-size: .82rem; font-weight: 600; cursor: pointer; }
.kti-seg label:first-child span { border-radius: 8px 0 0 8px; }
.kti-seg label + label span { border-radius: 0 8px 8px 0; margin-left: -1px; }
.kti-seg input:checked + span { background: var(--accent); border-color: var(--accent-line); color: var(--on-fill); }
.kti-seg input:focus-visible + span { outline: 2px solid var(--accent-line); outline-offset: 2px; }
.kti-seg input:disabled + span { cursor: not-allowed; opacity: .6; }
.kti-checks { margin: 12px 0 0; font-size: .85rem; color: var(--d-fg-3b4150); background: var(--surface-2); border-radius: 8px; padding: 8px 12px; }
/* the imports' four steps (2026-10-26): a person, a code or a figure stays on one line */
.imp-t td:first-child, .imp-t td.imp-nw, .imp-t td .muted.small { white-space: nowrap; }
.kti-checks summary { cursor: pointer; font-weight: 700; }
.ri-verdict .adm-rep-dl { flex: none; }
.ri-errs h3 .muted, .ri-chg h3 .muted { font-weight: 400; }
.ri-fix { list-style: none; margin: 8px 0 0; padding: 0; }
.ri-fix li { display: grid; grid-template-columns: 44px minmax(0, 1fr) minmax(0, 260px); gap: 12px; align-items: baseline;
  padding: 7px 0; border-top: 1px solid var(--line-soft); font-size: .88rem; }
.ri-fix li:first-child { border-top: 0; }
.ri-fix li b { color: var(--d-fg-b23a32); text-align: right; }
.ri-look { margin-top: 8px; }
.ri-look td { vertical-align: top; }
.ri-look-n { display: inline-block; min-width: 22px; color: var(--d-fg-9a6100); }
.ri-look-dl { white-space: nowrap; text-align: right; }
.ri-look-a { font-size: .82rem; font-weight: 600; color: var(--accent-ink); text-decoration: none; }
.ri-look-a:hover { color: var(--d-fg-1d2249); background: var(--d-bg-eef1fa); box-shadow: 0 0 0 3px var(--d-bg-eef1fa); border-radius: 4px; }
.ri-check button.primary:disabled { opacity: .45; cursor: not-allowed; }
.ri-go { border-top: 1px solid var(--line-soft); padding-top: 14px; }
.ri-ack { display: inline-flex; align-items: center; gap: 8px; font-size: .9rem; color: var(--ink); }
.ri-head-acts { display: inline-flex; gap: 14px; }

/* People picker; Details card; Data integrity fixes (admin round 4, canvas D2/D3) */
.pick { position: relative; display: inline-flex; flex: 1 1 220px; min-width: 200px; }
.pick .pick-q { width: 100%; }
/* in a stacked field (a label laid out as a column) the picker is one field wide, not a 220px-tall flex item */
.pp-fields label > .pick { flex: none; display: flex; width: 100%; min-width: 0; }
.pick-list { position: absolute; top: calc(100% + 4px); left: 0; z-index: 950; min-width: 100%; width: max-content; max-width: 420px; max-height: 280px; overflow-y: auto; margin: 0; padding: 4px; list-style: none; background: var(--surface); border: 1px solid var(--d-bd-d7dbe6); border-radius: 10px; box-shadow: 0 10px 28px var(--d-sh-1f2330-a16); }
.pick-list li { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 6px; padding: 7px 9px; border-radius: 7px; cursor: pointer; font-size: .85rem; }
.pick-list li span { color: var(--muted); font-size: .78rem; }
.pick-list li small { flex-basis: 100%; color: var(--muted); font-size: .76rem; }
.pick-list li.is-on, .pick-list li:hover { background: var(--d-bg-eef1fa); }
.pick-list li.pick-none { color: var(--faint); cursor: default; }
.pp-dl { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 16px; margin: 8px 0 0; }
.pp-dl dt { font-size: max(10px, .66rem); font-weight: 800; letter-spacing: .07em; text-transform: uppercase; color: var(--faint); }
.pp-dl dd { margin: 0; font-weight: 600; font-size: .9rem; }
.pp-det-form { display: grid; gap: 10px; margin-top: 12px; padding-top: 10px; border-top: 1px solid var(--line-soft); }
.pp-det-form label { display: flex; flex-direction: column; gap: 4px; font-size: .8rem; font-weight: 600; }
.dc-bulk { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; position: sticky; top: calc(var(--topbar-h) + 8px); z-index: 20; }
.dc-bulk label { display: flex; align-items: center; gap: 8px; font-size: .86rem; flex: 1 1 420px; }
.dc-row-fix { display: flex; align-items: center; gap: 8px; min-width: 280px; }
.pp-det-form input:not([type=checkbox]):not([type=radio]) { height: 34px; border: 1px solid var(--line-strong); border-radius: 8px; padding: 0 10px; font: inherit; }
.pp-change .pp-inline { flex-wrap: wrap; }

/* Org structure as one table (admin round 4, canvas O2-O4) */
.org-find { min-height: 34px; font: inherit; font-size: 0.92rem; border: 1px solid var(--line-strong); border-radius: 8px; padding: 0 10px; min-width: 200px; }
#org-bgrow { margin: 0 0 12px; }
.org-table .num { text-align: right; white-space: nowrap; }
.org-table tr.org-g th, .org-table tr.org-g td { background: var(--d-bg-fafbfd); font-weight: 700; }
.org-table tr.org-u th { padding-left: 34px; font-weight: 500; }
.org-table tr.org-edit td { background: var(--page); }
.org-none { color: var(--d-fg-8f3630); font-weight: 700; font-size: .85rem; }
.org-menu { position: relative; display: inline-block; }
.org-menu > summary { list-style: none; cursor: pointer; width: 32px; height: 28px; border: 1px solid var(--d-bd-d7dbe6); border-radius: 8px; display: flex; align-items: center; justify-content: center; font-weight: 800; color: var(--ink-2); }
.org-menu > summary::-webkit-details-marker { display: none; }
.org-menu[open] > summary { border-color: var(--accent-line); }
.org-pop { position: absolute; right: 0; top: calc(100% + 4px); z-index: 30; min-width: 220px; background: var(--surface); border: 1px solid var(--d-bd-d7dbe6); border-radius: 10px; box-shadow: 0 10px 28px var(--d-sh-1f2330-a16); padding: 4px; display: flex; flex-direction: column; }
.org-pop button, .org-pop a { text-align: left; border: 0; background: none; font: inherit; font-size: .86rem; padding: 7px 10px; border-radius: 7px; color: var(--ink); text-decoration: none; cursor: pointer; width: 100%; }
.org-pop button:hover, .org-pop a:hover { background: var(--d-bg-eef1fa); text-decoration: none; }
.org-pop form { margin: 0; }
.org-pop .danger-link { color: var(--d-fg-8f3630); }
.org-none { white-space: nowrap; }

/* A BU CEO of several units: one pill per unit on the calibration card (admin round 4, canvas B3) */
.rv-cal-units { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 0 0 10px; }
.rv-cal-units-lbl { font-size: max(10px, .66rem); font-weight: 800; letter-spacing: .07em; text-transform: uppercase; color: var(--faint); margin-right: 4px; }
.rv-cal-unit { display: inline-flex; flex-direction: column; gap: 1px; padding: 6px 12px; border: 1px solid var(--d-bd-d7dbe6); border-radius: 10px; background: var(--surface); color: var(--ink); text-decoration: none; font-size: .82rem; }
.rv-cal-unit span { font-size: .74rem; color: var(--muted); }
.rv-cal-unit:hover { border-color: var(--accent-line); text-decoration: none; }
.rv-cal-unit.is-on { border-color: var(--accent-line); box-shadow: inset 0 0 0 1px var(--accent-line); background: var(--d-bg-eef1fa); }
.rv-cal-unit.is-locked span { color: var(--d-fg-1a7a54); }

/* Units calibrated together (admin round 4, row 6) */
.adm-join h2, .adm-join + .admin-card h2 { margin: 0 0 10px; font-size: 1rem; }
.adm-join-tbl .adm-join-tick { width: 34px; text-align: center; }
.adm-join-tbl tr.is-off th, .adm-join-tbl tr.is-off td { color: var(--faint); }
.adm-join-why { display: block; font-weight: 400; }
.adm-join-who { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; margin: 12px 0 6px; }
.adm-join-who select.modern-select { width: auto; min-width: 17.5rem; max-width: 100%; }
.adm-join-notes { margin: 8px 0 0; padding-left: 18px; }
.adm-join-acts { display: flex; justify-content: flex-end; margin-top: 10px; }
.adm-joined { list-style: none; margin: 0; padding: 0; }
.adm-joined li { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 10px 0;
  border-top: 1px solid var(--line-soft); }
.adm-joined li:first-child { border-top: 0; }
.adm-joined-t { display: flex; flex-direction: column; gap: 2px; min-width: 0; }

/* units calibrated together (row 6): the business unit row on its own line above the department row */
.rv-cal-filter { flex-wrap: wrap; }
.rv-cal-filter > .rv-cal-unitrow { flex: 1 0 100%; min-width: 0; }

/* The Group Chief's 9-box on the group card (admin round 4, row 7): your calls on both axes, a box filters the list */
.rv-grp-9 { display: grid; grid-template-columns: 56px repeat(3, minmax(0, 1fr)); gap: 4px; margin: 6px 0 10px; }
.rv-grp-9y { align-self: center; font-size: max(10px, 0.6875rem); font-weight: 700; color: var(--d-fg-5b6275); text-transform: uppercase; letter-spacing: .04em; }
.rv-grp-9x { text-align: center; font-size: max(10px, 0.6875rem); color: var(--d-fg-5b6275); }
.rv-grp-9c { display: flex; align-items: baseline; gap: 6px; min-width: 0; padding: 6px 8px; border: 1px solid var(--line);
  border-radius: 8px; background: var(--surface); font: inherit; font-size: 0.75rem; color: var(--d-fg-1f2433); cursor: pointer; text-align: left; }
.rv-grp-9c b { font-size: 0.9375rem; }
.rv-grp-9c span { color: var(--d-fg-5b6275); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rv-grp-9c.is-empty { color: var(--d-fg-9aa0b0); background: var(--d-bg-fafbfd); }
.rv-grp-9c:hover { border-color: var(--d-bd-9aa3b8); }
.rv-grp-9c.is-on { border: 2px solid var(--d-bd-1b2a5c); padding: 5px 7px; background: var(--d-bg-f3f5fb); }
.rv-grp-potsel { margin-left: 2px; }

/* People > Users: an Excel-style menu on the Unit and Department columns (admin round 4, row 8) */
.adm-colf { position: relative; display: inline-block; }
.adm-colf > summary { list-style: none; cursor: pointer; display: inline-flex; gap: 4px; align-items: center;
  padding: 2px 6px; margin: -2px -6px; border-radius: 6px; }
.adm-colf > summary::-webkit-details-marker { display: none; }
.adm-colf > summary:hover, .adm-colf[open] > summary { background: var(--d-bg-eef1fa); color: var(--d-fg-1b2a5c); }
.adm-colf.is-on > summary { color: var(--d-fg-1b2a5c); font-weight: 700; }
.adm-colf-pop { position: absolute; z-index: 30; top: calc(100% + 6px); left: -6px; width: 300px; background: var(--surface);
  border: 1px solid var(--d-bd-d6dae5); border-radius: 10px; box-shadow: 0 10px 30px var(--d-sh-141c3c-a14); padding: 10px;
  text-transform: none; letter-spacing: 0; font-weight: 400; color: var(--d-fg-1f2433); }
.adm-colf-q { width: 100%; box-sizing: border-box; margin: 0 0 6px; padding: 6px 8px; border: 1px solid var(--line-strong);
  border-radius: 8px; font: inherit; font-size: 0.8125rem; }
.adm-colf-list { max-height: 260px; overflow-y: auto; display: flex; flex-direction: column; }
.adm-colf-opt { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; gap: 6px; align-items: center;
  padding: 4px 2px; font-size: 0.8125rem; cursor: pointer; }
.adm-colf-opt span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.adm-colf-opt b { font-weight: 500; color: var(--d-fg-5b6275); font-size: 0.75rem; }
.adm-colf-acts { display: flex; justify-content: flex-end; align-items: center; gap: 12px; margin-top: 8px; }
.adm-roles { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.adm-role.is-lm { background: var(--d-bg-eef1fa); color: var(--accent-ink); }
.adm-role.is-hod { background: var(--d-bg-e2f3f4); color: var(--d-fg-0f6a73); }
.adm-role.is-bu { background: var(--d-bg-f1eafa); color: var(--d-fg-5b2f96); }
.adm-role.is-cg { background: var(--d-bg-e7f4ea); color: var(--d-fg-1f6b35); }
.adm-role.is-bg { background: var(--d-bg-fdf3e1); color: var(--d-fg-7a4b00); }
.adm-role.is-gc { background: var(--d-bg-fbecea); color: var(--d-fg-8f3630); }
.adm-roles .adm-role:last-child { margin-right: 0; }   /* the last chip's 8px is no room to clip into an ellipsis (BGCFO tag, 2026-11-04) */
.adm-colf-opt[hidden] { display: none; }
.pp-role.is-gc { background: var(--d-bg-fbecea); color: var(--d-fg-8f3630); }
.pp-role.is-cg { background: var(--d-bg-e7f4ea); color: var(--d-fg-1f6b35); }

/* the roster check's role changes (admin round 4, row 8) */
.ri-seat-list { list-style: none; margin: 0; padding: 0; }
.ri-seat-list li { padding: 6px 0; border-top: 1px solid var(--line-soft); font-size: 0.8125rem; }
.ri-seat-list li:first-child { border-top: 0; }
.ri-seat-tag { display: inline-block; min-width: 76px; text-align: center; margin-right: 8px; padding: 1px 8px;
  border-radius: 999px; font-size: max(10px, 0.6875rem); font-weight: 700; }
.ri-seat-tag.is-add { background: var(--d-bg-e6f4ef); color: var(--d-fg-1a6a52); }
.ri-seat-tag.is-swap { background: var(--d-bg-fdf3e1); color: var(--d-fg-7a4b00); }
.ri-seat-tag.is-take { background: var(--d-bg-fbecea); color: var(--d-fg-8f3630); }
.ri-seat-note { color: var(--d-fg-7a4b00); }

/* =========================================================================
   Sign-in, forgot password and reset (redesigned 2026-10-15, the canvas "OneHR AI+ Sign-in", in Chin Hin's brand
   guide: Chin Hin Blue #282460, Chin Hin Red #DF1E26, white, Aptos, the Infinite Sail stripes). Committing buttons
   navy; red only for the mark and what's wrong. Prefix ax-.
   ========================================================================= */
/* div.ax only: the sign-in pages' wrapper. The 9-box's axis caption and What you led's grid are span.ax, and a bare
   .ax here once made each of them a whole screen tall (2026-10-16: the BG and BU CEO record views) */
div.ax { --ax-blue: var(--d-cv-282460); --ax-red: var(--d-cv-df1e26); --ax-ink: var(--d-cv-212322); --ax-body: var(--d-cv-3f4244); --ax-muted: var(--d-cv-55585a);
  --ax-line: var(--d-cv-c2c4cc); --ax-soft: var(--d-cv-f3f4f9);
  min-height: 100vh; display: flex; flex-wrap: wrap; align-items: stretch; background: var(--surface);
  font-family: Aptos, "Aptos Display", "Segoe UI", Arial, Helvetica, sans-serif; color: var(--ax-ink); }
.ax [hidden], .ax-modal[hidden], .ax-modal [hidden] { display: none !important; }
.ax a, .ax-modal a { color: var(--ax-blue); }
.ax a:hover, .ax-modal a:hover { color: var(--ax-red); }
.ax-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

/* -- the brand panel -- */
.ax-brand { flex: 1 1 480px; min-width: 0; position: relative; overflow: hidden; background: var(--ax-blue); color: var(--on-fill);
  display: flex; flex-direction: column; justify-content: space-between; gap: 32px; padding: 48px 64px; }
.ax-sail { position: absolute; transform: skewX(-32deg); pointer-events: none; }
.ax-sail-1 { right: -140px; top: 96px; width: 620px; height: 240px;
  background: repeating-linear-gradient(180deg, var(--d-bg-ffffff-a1) 0 2px, transparent 2px 10px); }
.ax-sail-2 { right: -60px; top: 300px; width: 460px; height: 170px;
  background: repeating-linear-gradient(180deg, var(--d-bg-9694e6-a3) 0 2px, transparent 2px 10px); }
.ax-lockup { position: relative; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
/* the app's mark, as in the top bar: the white spark on a red tile, the AI Agent card's tile size (Chris, 2026-10-19) */
.ax-lockup-sq { width: 28px; height: 28px; border-radius: 8px; background: var(--ax-red); color: var(--on-fill); flex: none;
  display: flex; align-items: center; justify-content: center; }
.ax-lockup-name { font-size: 1.5rem; font-weight: 700; letter-spacing: -0.01em; }
.ax-lockup-by { font-size: 0.875rem; color: var(--d-fg-c9cbe6); }
.ax-aiplus { display: inline-flex; align-items: center; gap: 6px; padding: 5px 11px; border-radius: 999px; background: var(--surface);
  color: var(--ax-red); font-size: 0.8125rem; font-weight: 700; letter-spacing: 0.02em; }
.ax-brand-body { position: relative; display: flex; flex-direction: column; gap: 24px; max-width: 520px; }
.ax-headline { margin: 0; font-size: 2.75rem; line-height: 1.08; font-weight: 700; letter-spacing: -0.02em; }
.ax-lede { margin: 0; font-size: 1.125rem; line-height: 1.55; color: var(--d-fg-dadcf0); }
.ax-tagline { position: relative; margin: 0; font-size: max(10px, 0.6875rem); letter-spacing: 0.14em; text-transform: uppercase; color: var(--d-fg-b4b6dd); }
/* the logo with its brand line set under it, one lockup: the logo 40px tall (248px wide, its "H" 32px -- the exclusion
   zone kept clear around the pair), the brand line justified to exactly the logo's width so they line up whatever
   font the machine has (Aptos on Windows, a fallback on a Mac) */
.ax-brand-foot { position: relative; align-self: flex-start; width: 248px; display: flex; flex-direction: column; gap: 10px; }
.ax-chlogo { display: block; width: 248px; height: 40px; flex: none; }
.ax-brand-foot .ax-tagline { font-size: max(10px, 0.625rem); letter-spacing: 0.04em; white-space: nowrap; text-align: justify;
  text-align-last: justify; }
.ax-points { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 12px; font-size: 0.9375rem; color: var(--d-fg-e6e7f5); }
.ax-points li { display: flex; align-items: center; gap: 12px; }
.ax-points svg { flex: none; color: var(--on-fill); }

/* the assistant card: one 12-second loop, every bubble holds its place (opacity only), so nothing jumps */
.ax-demo { margin: 0; max-width: 440px; background: var(--surface); color: var(--ax-ink); border-radius: 16px; padding: 14px 18px 16px;
  display: flex; flex-direction: column; gap: 10px; box-shadow: 0 18px 40px var(--d-sh-0a0a28-a3); }
.ax-demo-head { display: flex; align-items: center; gap: 10px; }
.ax-spark-tile { width: 28px; height: 28px; border-radius: 8px; background: var(--ax-red); color: var(--on-fill);
  display: flex; align-items: center; justify-content: center; flex: none; }
.ax-demo-name { font-size: 0.8125rem; font-weight: 700; color: var(--ax-blue); }
.ax-demo-pause { margin: -8px -10px -8px auto; width: 44px; height: 44px; padding: 0; border: 0; background: transparent;
  border-radius: 10px; color: var(--ax-muted); display: flex; align-items: center; justify-content: center; cursor: pointer; }
.ax-demo-pause:hover { background: var(--ax-soft); color: var(--ax-blue); }
.ax-demo-pause .ax-ico-play { display: none; }
.ax-demo.is-paused .ax-ico-play { display: block; }
.ax-demo.is-paused .ax-ico-pause { display: none; }
.ax-demo-feed { display: flex; flex-direction: column; gap: 9px; }
.ax-demo-step { display: flex; flex-direction: column; gap: 8px; }
.ax-bub { margin: 0; align-self: flex-start; max-width: 88%; background: var(--ax-soft); border-radius: 12px 12px 12px 4px;
  padding: 8px 12px; font-size: 0.84375rem; line-height: 1.45; }
.ax-bub-me { align-self: flex-end; background: var(--ax-blue); color: var(--on-fill); border-radius: 12px 12px 4px 12px; }
.ax-bub-done { justify-self: stretch; max-width: none; display: flex; flex-direction: column; gap: 6px; }
.ax-done-row { display: flex; gap: 14px; flex-wrap: wrap; font-size: 0.8125rem; font-weight: 600; color: var(--ax-blue); }
.ax-done-row span { display: inline-flex; align-items: center; gap: 6px; }
.ax-chips { display: flex; gap: 8px; flex-wrap: wrap; }
.ax-chip { padding: 5px 11px; border-radius: 999px; border: 1px solid var(--ax-blue); background: var(--surface); color: var(--ax-blue);
  font-size: 0.78125rem; font-weight: 600; }
.ax-chip-quiet { border-color: var(--d-bd-c9cbd3); color: var(--ax-body); }
.ax-slot { display: grid; }
.ax-slot > * { grid-area: 1 / 1; }
.ax-typing { align-self: start; justify-self: start; opacity: 0; display: inline-flex; gap: 4px; background: var(--ax-soft);
  border-radius: 12px; padding: 12px 14px; }
.ax-dot { width: 6px; height: 6px; border-radius: 999px; background: var(--d-bg-6b6e80); }
@keyframes axIn1 { 0% { opacity: 0; transform: translateY(6px); } 4% { opacity: 1; transform: none; } 92% { opacity: 1; transform: none; } 97%, 100% { opacity: 0; } }
@keyframes axIn2 { 0%, 18% { opacity: 0; transform: translateY(6px); } 21% { opacity: 1; transform: none; } 92% { opacity: 1; transform: none; } 97%, 100% { opacity: 0; } }
@keyframes axT3 { 0%, 24% { opacity: 0; } 26%, 34% { opacity: 1; } 36%, 100% { opacity: 0; } }
@keyframes axIn3 { 0%, 36% { opacity: 0; transform: translateY(6px); } 39% { opacity: 1; transform: none; } 92% { opacity: 1; transform: none; } 97%, 100% { opacity: 0; } }
@keyframes axT5 { 0%, 50% { opacity: 0; } 52%, 60% { opacity: 1; } 62%, 100% { opacity: 0; } }
@keyframes axIn5 { 0%, 62% { opacity: 0; transform: translateY(6px); } 65% { opacity: 1; transform: none; } 92% { opacity: 1; transform: none; } 97%, 100% { opacity: 0; } }
@keyframes axTap { 0%, 14% { background: var(--surface); color: var(--d-fg-282460); } 16%, 92% { background: var(--d-bg-282460); color: var(--on-fill); } 97%, 100% { background: var(--surface); color: var(--d-fg-282460); } }
@keyframes axDot { 0%, 80%, 100% { opacity: .25; } 40% { opacity: 1; } }
.ax-a1 { animation: axIn1 12s infinite; }
.ax-a2 { animation: axIn2 12s infinite; }
.ax-t3 { animation: axT3 12s infinite; }
.ax-a3 { animation: axIn3 12s infinite; }
.ax-t5 { animation: axT5 12s infinite; }
.ax-a5 { animation: axIn5 12s infinite; }
.ax-tap { animation: axTap 12s infinite; }
.ax-dot { animation: axDot 1.2s infinite; }
.ax-dot2 { animation-delay: .2s; }
.ax-dot3 { animation-delay: .4s; }
/* three scenes, one after another over 36 seconds (2026-10-16): each runs the 12-second steps above, and the scene
   in view, and its part above the feed, change at each 12-second mark, where every bubble has faded out */
.ax-parts { margin: 0; padding: 0; list-style: none; display: flex; gap: 6px; }
.ax-part { padding: 3px 10px; border-radius: 999px; background: var(--ax-soft); color: var(--ax-muted); font-size: max(10px, 0.71875rem);
  font-weight: 600; }
.ax-scenes { display: grid; }
.ax-scenes > .ax-scene { grid-area: 1 / 1; display: flex; flex-direction: column; gap: 9px; visibility: hidden; }
@keyframes axScene1 { 0%, 33.3% { visibility: visible; } 33.34%, 100% { visibility: hidden; } }
@keyframes axScene2 { 0%, 33.3% { visibility: hidden; } 33.34%, 66.6% { visibility: visible; } 66.67%, 100% { visibility: hidden; } }
@keyframes axScene3 { 0%, 66.6% { visibility: hidden; } 66.67%, 100% { visibility: visible; } }
@keyframes axPart1 { 0%, 33.3% { background: var(--ax-blue); color: var(--on-fill); } 33.34%, 100% { background: var(--ax-soft); color: var(--ax-muted); } }
@keyframes axPart2 { 0%, 33.3% { background: var(--ax-soft); color: var(--ax-muted); } 33.34%, 66.6% { background: var(--ax-blue); color: var(--on-fill); } 66.67%, 100% { background: var(--ax-soft); color: var(--ax-muted); } }
@keyframes axPart3 { 0%, 66.6% { background: var(--ax-soft); color: var(--ax-muted); } 66.67%, 100% { background: var(--ax-blue); color: var(--on-fill); } }
.ax-scene-1 { animation: axScene1 36s infinite step-end; }
.ax-scene-2 { animation: axScene2 36s infinite step-end; }
.ax-scene-3 { animation: axScene3 36s infinite step-end; }
.ax-part-1 { animation: axPart1 36s infinite step-end; }
.ax-part-2 { animation: axPart2 36s infinite step-end; }
.ax-part-3 { animation: axPart3 36s infinite step-end; }
.ax-demo.is-paused * { animation-play-state: paused !important; }
@media (prefers-reduced-motion: reduce) {
  .ax-demo * { animation: none !important; }
  .ax-scenes > .ax-scene-1 { visibility: visible; }
  .ax-part-1 { background: var(--ax-blue); color: var(--on-fill); }
  .ax-demo .ax-typing { opacity: 0 !important; }
  .ax-demo .ax-tap { background: var(--d-bg-282460); color: var(--on-fill); }
  .ax-demo-pause { display: none; }
}

/* the easter egg (Chris, 2026-10-16: "go with A and B, after the spark, transition to the background change, but don't
   change the wording"): five quick taps on AI+ turn its spark a fifth each and fill a dot; the fifth sets off a burst of
   sparks, then the sail stripes sweep in across the panel, settle, and sweep away. Pure decoration: no words change. */
.ax-aiplus[data-egg] { position: relative; user-select: none; -webkit-user-select: none; touch-action: manipulation;
  cursor: pointer; transition: transform .15s ease-out, box-shadow .15s ease-out; }
/* it invites the tap (Chris, 2026-10-16: "make it more obvious when user hover, it should enlarge and the mouse should
   become like a pressing"): it grows on hover, the hand cursor shows, and it gives a little on the press */
.ax-aiplus[data-egg]:hover { transform: scale(1.1); box-shadow: 0 6px 18px var(--d-sh-0a0a28-a35); }
.ax-aiplus[data-egg]:active { transform: scale(.96); }
.ax-aiplus[data-egg] > svg { transition: transform .25s ease-out; }
.ax-egg-dots { position: absolute; left: 50%; top: calc(100% + 8px); transform: translateX(-50%); display: flex; gap: 5px;
  pointer-events: none; }
.ax-egg-dots > i { width: 6px; height: 6px; border-radius: 999px; background: var(--d-bg-ffffff-a28); }
.ax-egg-dots > i.is-on { background: var(--surface); }
.ax-aiplus.is-egg { animation: axEggGlow 1.2s ease-out 2; }
@keyframes axEggGlow { from { box-shadow: 0 0 0 0 var(--d-sh-df1e26-a55); } to { box-shadow: 0 0 0 18px var(--d-sh-df1e26-a0); } }
.ax-egg-burst { position: absolute; left: 50%; top: 50%; width: 0; height: 0; z-index: 3; pointer-events: none; }
/* the flight eases out over the whole 2.4s; the fade is its own linear track, so a spark stays bright most of the way */
.ax-egg-spark { position: absolute; left: 0; top: 0; opacity: 0;
  animation: axEggBurst 2.4s cubic-bezier(.15,.7,.3,1) var(--d) both, axEggFade 2.4s linear var(--d) both; }
@keyframes axEggBurst {
  from { transform: translate(-50%, -50%) scale(.3) rotate(0deg); }
  to { transform: translate(calc(-50% + var(--dx)), calc(-50% + var(--dy))) scale(1) rotate(var(--r)); }
}
@keyframes axEggFade { 0% { opacity: 0; } 8% { opacity: 1; } 60% { opacity: 1; } 100% { opacity: 0; } }
.ax-egg-sea { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.ax-egg-band { position: absolute; top: -20%; height: 140%; left: var(--l); width: var(--w); transform: skewX(-32deg);
  opacity: 0; }
.ax-egg-band.is-white { background: repeating-linear-gradient(180deg, var(--d-bg-ffffff-a14) 0 2px, transparent 2px 10px); }
.ax-egg-band.is-lilac { background: repeating-linear-gradient(180deg, var(--d-bg-9694e6-a34) 0 2px, transparent 2px 10px); }
.ax-egg-band.is-glass { background: var(--d-bg-ffffff-a07); }
.ax-egg-band.is-red { background: var(--d-bg-df1e26-a5); }
.ax-egg-sea.is-in .ax-egg-band { animation: axEggSweep 1.1s cubic-bezier(.2,.7,.2,1) var(--d) both; }
.ax-egg-sea.is-out .ax-egg-band { animation: axEggAway .9s ease-in var(--d) both; }
@keyframes axEggSweep {
  from { transform: translateX(110vw) skewX(-32deg); opacity: 0; }
  25% { opacity: 1; }
  to { transform: skewX(-32deg); opacity: 1; }
}
@keyframes axEggAway {
  from { transform: skewX(-32deg); opacity: 1; }
  to { transform: translateX(-60vw) skewX(-32deg); opacity: 0; }
}
/* the assistant card's own line while the egg plays: in the scenes' cell, the loop's scenes and part pills kept in place
   but hidden (the !important beats their visibility animations), so the card never changes size */
.ax-demo .ax-scenes > .ax-egg-scene { visibility: visible; }
.ax-demo.is-egg .ax-scenes > .ax-scene:not(.ax-egg-scene), .ax-demo.is-egg .ax-parts { visibility: hidden !important; }
.ax-egg-say { animation: axEggSay .35s ease-out .3s both; }
.ax-demo.is-paused .ax-egg-say { animation-play-state: running !important; }   /* shows even with the loop paused */
@keyframes axEggSay { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
/* the OneHR mascot (Chris, 2026-10-19, canvas "OneHR Easter Egg Mascot": "out of the pill then rides the stripes"):
   its path is set by static/auth.js from the real layout; here only its size, its wave and its blink. Above the stripes
   and the words, under the sparks; it never takes a click. On a phone it is smaller and says the card's line. */
.ax-egg-mascot { position: absolute; left: 0; top: 0; z-index: 2; width: 96px; height: 106px; pointer-events: none;
  filter: drop-shadow(0 8px 14px var(--d-sh-0a0a28-a35)); }
.ax-egg-mascot.is-phone { width: 56px; height: 62px; }
.ax-egg-mascot > svg { display: block; width: 100%; height: 100%; overflow: visible; }
.ax-egg-arm { transform-box: view-box; transform-origin: 100px 110px; animation: axEggWave .45s ease-in-out 3.4s 6 alternate both; }
.ax-egg-mascot.is-phone .ax-egg-arm { animation-delay: 1.3s; animation-iteration-count: 10; }
@keyframes axEggWave { from { transform: rotate(-14deg); } to { transform: rotate(-48deg); } }
.ax-egg-eyes { transform-box: view-box; transform-origin: 100px 104px; animation: axEggBlink 3.2s infinite; }
@keyframes axEggBlink { 0%, 91% { transform: none; } 94% { transform: scaleY(.15); } 97%, 100% { transform: none; } }
.ax-egg-bubble { position: absolute; right: 12px; z-index: 2; margin: 0; max-width: min(240px, calc(100% - 24px));
  padding: 8px 12px; border-radius: 12px 4px 12px 12px; background: var(--surface); color: var(--d-fg-282460); font-size: 0.8125rem; line-height: 1.4;
  font-weight: 600; box-shadow: 0 8px 22px var(--d-sh-0a0a28-a3); pointer-events: none; animation: axEggSay .35s ease-out 1.2s both; }
@media (prefers-reduced-motion: reduce) {
  .ax-aiplus[data-egg], .ax-aiplus[data-egg] > svg { transition: none; }
  .ax-aiplus.is-egg, .ax-egg-sea.is-in .ax-egg-band, .ax-egg-sea.is-out .ax-egg-band { animation: none; }
  .ax-egg-burst { display: none; }
  .ax-egg-sea.is-in .ax-egg-band { opacity: 1; }   /* the stripes just appear, and go */
  .ax-egg-sea.is-out .ax-egg-band { opacity: 0; }
  .ax-egg-arm, .ax-egg-eyes, .ax-egg-bubble { animation: none; }   /* the mascot just appears at its spot, and goes */
}

/* -- the form side -- */
.ax-main { flex: 1 1 420px; min-width: 0; background: var(--surface); display: flex; align-items: center; justify-content: center;
  padding: 48px 32px; }
.ax-card { width: 100%; max-width: 400px; display: flex; flex-direction: column; gap: 24px; }
.ax-head { display: flex; flex-direction: column; gap: 8px; }
.ax-h { margin: 0; font-size: 2.125rem; font-weight: 700; color: var(--ax-blue); letter-spacing: -0.015em; line-height: 1.15; }
.ax-sub { margin: 0; font-size: 1rem; line-height: 1.55; color: var(--ax-muted); }
.ax-tile { width: 48px; height: 48px; border-radius: 12px; background: var(--d-bg-ececf8); color: var(--ax-blue);
  display: flex; align-items: center; justify-content: center; flex: none; }
.ax-form { display: flex; flex-direction: column; gap: 18px; }
.ax-field { display: flex; flex-direction: column; gap: 8px; }
.ax-field label { font-size: 0.875rem; font-weight: 600; color: var(--ax-ink); }
.ax-hint { margin: 0; font-size: 0.8125rem; line-height: 1.45; color: var(--ax-muted); }
.ax-field input { width: 100%; height: 48px; margin: 0; border: 1px solid var(--ax-line); border-radius: 10px; padding: 0 14px;
  font-size: 1rem; font-family: inherit; color: var(--ax-ink); background: var(--surface); box-shadow: none; }
.ax-field .pw-field > input { padding-right: 52px; }
.ax-field input:focus-visible { outline: none; border-color: var(--ax-blue); box-shadow: 0 0 0 3px var(--d-sh-282460-a22); }
.ax-field input[aria-invalid="true"] { border-color: var(--d-bd-b3141b); }
.ax-field .pw-field .pw-toggle { right: 2px; width: 44px; height: 44px; padding: 0; justify-content: center; border-radius: 8px;
  color: var(--ax-muted); }
.ax-field .pw-field .pw-toggle:hover { background: var(--ax-soft); color: var(--ax-blue); }
.ax-err { margin: -6px 0 0; font-size: 0.875rem; color: var(--d-fg-8f1016); }
.ax-small { margin: -4px 0 0; font-size: 0.8125rem; color: var(--ax-muted); }
.ax-btn, a.ax-btn { min-height: 50px; margin: 0; padding: 0 22px; border: 0; border-radius: 10px; background: var(--ax-blue); color: var(--on-fill);
  font-size: 1rem; font-weight: 700; font-family: inherit; cursor: pointer; display: inline-flex; align-items: center;
  justify-content: center; text-decoration: none; transition: background .15s; }
.ax-form > .ax-btn { width: 100%; margin-top: 4px; }
.ax-btn:hover, a.ax-btn:hover { background: var(--d-bg-1c1a47); color: var(--on-fill); text-decoration: none; }
.ax-btn:focus-visible { outline: 3px solid var(--d-bd-8e8cd8); outline-offset: 2px; box-shadow: none; }
.ax-btn[disabled] { opacity: .6; cursor: progress; }
.ax-btn-quiet, a.ax-btn-quiet { background: var(--surface); color: var(--ax-blue); border: 1px solid var(--ax-line); font-weight: 600; }
.ax-btn-quiet:hover, a.ax-btn-quiet:hover { background: var(--ax-soft); color: var(--ax-blue); }
.ax-links { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-top: -4px; }
.ax-links a { padding: 8px 0; font-size: 0.9375rem; font-weight: 600; text-decoration: underline; text-underline-offset: 3px; }
.ax-linkbtn { margin: 0; border: 0; background: transparent; padding: 8px 0; font-size: 0.9375rem; font-family: inherit; color: var(--ax-body);
  cursor: pointer; display: inline-flex; align-items: center; gap: 6px; }
.ax-linkbtn:hover { color: var(--ax-blue); }
.ax-linkbtn[aria-expanded="true"] { color: var(--ax-blue); font-weight: 600; }
.ax-first { margin-top: -10px; background: var(--ax-soft); border: 1px solid var(--d-bd-e1e3ee); border-radius: 12px; padding: 14px 16px; }
.ax-first p { margin: 0; font-size: 0.875rem; line-height: 1.55; color: var(--ax-ink); }
.ax-first code { font-family: ui-monospace, Menlo, Consolas, monospace; background: var(--surface); border: 1px solid var(--d-bd-e1e3ee); border-radius: 6px;
  padding: 1px 6px; font-size: 0.92em; }
.ax-foot { margin: 0; font-size: 0.875rem; color: var(--ax-muted); border-top: 1px solid var(--d-bd-ecedf2); padding-top: 18px; }
.ax-alert { display: flex; gap: 12px; align-items: flex-start; background: var(--d-bg-fdf1f1); border: 1px solid var(--d-bd-f2c1c3); border-radius: 12px;
  padding: 14px 16px; font-size: 0.875rem; line-height: 1.5; color: var(--ax-ink); }
.ax-alert > svg { flex: none; margin-top: 1px; color: var(--d-fg-b3141b); }
.ax-alert > div { display: flex; flex-direction: column; gap: 4px; }
.ax-alert strong { color: var(--d-fg-8f1016); }
.ax-alert p { margin: 0; }
.ax-alert-link { align-self: flex-start; padding: 4px 0; font-weight: 700; text-decoration: underline; text-underline-offset: 3px; }
.ax-note { display: flex; gap: 10px; align-items: flex-start; background: var(--d-bg-eef7f1); border: 1px solid var(--d-bd-bfe2cc); border-radius: 12px;
  padding: 12px 16px; font-size: 0.875rem; line-height: 1.5; color: var(--d-fg-1d5a36); }
.ax-note > svg { flex: none; margin-top: 1px; }
.ax-note p { margin: 0; }
.ax-info { margin: 0; padding: 14px 16px; list-style: none; background: var(--ax-soft); border-radius: 12px; display: flex;
  flex-direction: column; gap: 10px; font-size: 0.875rem; line-height: 1.5; color: var(--ax-body); }
.ax-info li { display: flex; gap: 10px; align-items: flex-start; }
.ax-info svg { flex: none; margin-top: 2px; color: var(--ax-blue); }
.ax-dev { background: var(--d-bg-fff7e6); border: 1px solid var(--d-bd-f0d49a); border-radius: 12px; padding: 12px 14px; font-size: 0.8125rem; line-height: 1.5;
  color: var(--d-fg-6a4a00); word-break: break-all; display: flex; flex-direction: column; gap: 4px; }
.ax-actions { display: flex; justify-content: flex-end; gap: 12px; flex-wrap: wrap; }
.ax-actions-start { justify-content: flex-start; }
.ax-rules { margin: -4px 0 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 10px; font-size: 0.875rem;
  color: var(--ax-body); }
.ax-rules li { display: flex; align-items: center; gap: 10px; }
.ax-rule-dot { width: 20px; height: 20px; border-radius: 999px; border: 2px solid var(--ax-line); color: transparent; flex: none;
