/* -- the forgot-password pop-out -- */
body.ax-modal-open { overflow: hidden; }
.ax-modal { position: fixed; inset: 0; z-index: 1000; background: var(--d-bg-121234-a55); display: flex; align-items: center;
  justify-content: center; padding: 24px; font-family: Aptos, "Aptos Display", "Segoe UI", Arial, Helvetica, sans-serif;
  color: var(--d-fg-212322); animation: axFade .16s ease-out; }
.ax-dialog { position: relative; width: 100%; max-width: 460px; max-height: calc(100vh - 48px); overflow-y: auto; background: var(--surface);
  border-radius: 16px; box-shadow: 0 28px 70px var(--d-sh-0a0a28-a4); padding: 32px; animation: axRise .18s ease-out;
  --ax-blue: var(--d-cv-282460); --ax-red: var(--d-cv-df1e26); --ax-ink: var(--d-cv-212322); --ax-body: var(--d-cv-3f4244); --ax-muted: var(--d-cv-55585a); --ax-line: var(--d-cv-c2c4cc);
