.gp-fold { width: 32px; height: 32px; border: 0; border-radius: 8px; background: transparent; color: var(--muted); display: flex;
  align-items: center; justify-content: center; cursor: pointer; flex: none; }
.gp-fold:hover { background: var(--d-bg-f1f3f8); color: var(--accent-ink); }
.gp-fold svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.gp-log { flex: 1; min-height: 0; overflow: auto; padding: 14px 14px 10px 16px; display: flex; flex-direction: column; gap: 12px; }
.gp-rest { display: flex; flex-direction: column; gap: 12px; }
.gp-rest[hidden] { display: none; }
.gp-lead { margin: 0; font-size: 0.875rem; line-height: 1.5; color: var(--ink); }
