.gp-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.gp-chip { min-height: 32px; padding: 5px 12px; border-radius: 999px; border: 1px solid var(--d-bd-c9cdda); background: var(--surface); color: var(--accent-ink);
  font: inherit; font-size: 0.8125rem; line-height: 1.3; cursor: pointer; text-align: left; }
.gp-chip:hover { border-color: var(--accent-line); background: var(--d-bg-f6f7fb); }
.gp-chip:disabled { opacity: .55; cursor: default; }
.gp-q { margin: 0; align-self: flex-end; max-width: 85%; padding: 8px 12px; border-radius: 12px 12px 4px 12px; background: var(--accent);
  color: var(--on-fill); font-size: 0.84375rem; line-height: 1.4; overflow-wrap: anywhere; }
.gp-a { display: flex; flex-direction: column; gap: 10px; }
.gp-a > p { margin: 0; font-size: 0.875rem; line-height: 1.5; color: var(--ink); }
