.gp-act { min-height: 36px; padding: 6px 14px; border-radius: 8px; border: 1px solid var(--d-bd-c9cdda); background: var(--surface); color: var(--accent-ink);
  font: inherit; font-size: 0.84375rem; line-height: 1.3; cursor: pointer; text-decoration: none; display: inline-flex; align-items: center; }
.gp-act:hover { border-color: var(--accent-line); text-decoration: none; }
.gp-act.is-primary { background: var(--accent); border-color: var(--accent-line); color: var(--on-fill); font-weight: 600; }
.gp-act.is-primary:hover { background: var(--d-bg-1b1f48); }
.gp-guide { padding: 9px 12px; border: 1px solid var(--d-bd-e2e5ee); border-radius: 10px; font-size: 0.8125rem; color: var(--d-fg-4a5066); }
.gp-guide b { display: block; color: var(--accent-ink); font-weight: 600; }
.gp-guide small { display: block; margin-top: 2px; color: var(--faint); font-size: max(10px, 0.71875rem); }
.gp-note { font-size: max(10px, 0.71875rem); color: var(--faint); }
.gp-thinking { margin: 0; font-size: 0.8125rem; color: var(--faint); }
.gp-form { padding: 10px 14px 12px 16px; border-top: 1px solid var(--line-soft); display: flex; flex-direction: column; gap: 6px; flex: none; }
.gp-box { display: flex; align-items: center; gap: 8px; padding: 4px 4px 4px 12px; border: 1px solid var(--d-bd-c9cdda); border-radius: 12px; background: var(--surface); }
.gp-box:focus-within { border-color: var(--accent-line); box-shadow: 0 0 0 3px var(--d-sh-252a59-a12); }
.gp-box input { flex: 1; min-width: 0; height: 34px; border: 0; outline: none; font: inherit; font-size: 0.84375rem; color: var(--ink); background: transparent; }
.gp-box input:focus, .gp-box input:focus-visible { outline: none; box-shadow: none; border: 0; }   /* the box draws the ring (2026-10-16) */
.gp-send { width: 36px; height: 36px; border: 0; border-radius: 9px; background: var(--ai); color: var(--on-fill); display: flex; align-items: center;
  justify-content: center; cursor: pointer; flex: none; }
.gp-send.is-offline { background: var(--accent); }
.gp-send:disabled { opacity: .6; cursor: default; }
.gp-send svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.gp-foot { margin: 0; font-size: max(10px, 0.71875rem); color: var(--muted); }
.gp-rail { width: 56px; display: flex; flex-direction: column; align-items: center; padding-top: 14px; gap: 10px; }
.gp-open { position: relative; width: 40px; height: 40px; border: 0; border-radius: 11px; background: var(--ai); color: var(--on-fill);
  display: flex; align-items: center; justify-content: center; cursor: pointer; }
.gp-open svg { width: 17px; height: 17px; fill: currentColor; }
.gp-badge { position: absolute; top: -5px; right: -5px; min-width: 18px; height: 18px; padding: 0 5px; box-sizing: border-box;
  border-radius: 999px; background: var(--accent); color: var(--on-fill); border: 2px solid var(--surface); font-size: max(10px, 0.65625rem); font-weight: 700;
  display: flex; align-items: center; justify-content: center; }
.gp-rail-lab { writing-mode: vertical-rl; transform: rotate(180deg); font-size: 0.75rem; color: var(--muted); letter-spacing: .04em; }
/* the card a guide answer points to: a navy ring and a "Here" tag, until the next question */
.gp-marked { position: relative; box-shadow: 0 0 0 2px var(--accent-line), 0 0 0 7px var(--d-sh-252a59-a12); }
.gp-marked::after { content: "Here"; position: absolute; top: -10px; right: 12px; padding: 2px 9px; border-radius: 999px;
  background: var(--accent); color: var(--on-fill); font-size: max(10px, 0.6875rem); font-weight: 700; line-height: 1.4; pointer-events: none; }

/* ===== The first sign-in (2026-10-15; canvas "OneHR Display Name and Avatar"): the guide panel is the one live
   thing on the page, the rest dimmed and inert; the tour lifts one part at a time out of the dim. ===== */
.ob-dim { position: fixed; inset: 0; background: var(--d-bg-141834-a46); z-index: 895; }
.gp.is-onboarding { z-index: 900; box-shadow: 8px 0 32px var(--d-sh-141834-a28); }
.ob-steps { list-style: none; margin: 0; padding: 10px 16px 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px; flex: none; }
.ob-steps li { display: flex; flex-direction: column; gap: 5px; font-size: max(10px, 0.71875rem); color: var(--muted); }
.ob-steps li span { height: 4px; border-radius: 999px; background: var(--d-bg-e2e5ee); }
.ob-steps li.is-done span { background: var(--accent); }
.ob-steps li.is-now { color: var(--accent-ink); font-weight: 700; }
.ob-steps li.is-now span { background: var(--ai); }
.ob-hint { margin: 0; font-size: 0.78125rem; color: var(--muted); }
.ob-picset { border: 0; margin: 0; padding: 0; min-width: 0; display: flex; flex-direction: column; gap: 7px; }
.ob-pics-h { margin: 0 0 3px; font-size: max(10px, 0.71875rem); font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
/* six across since the 31 (2026-10-22): five ran the step past the guide panel's fold at 1280x800; at 38 the tiles
   lost 2px top and bottom (and the gaps a little) so the step still fits */
.ob-pics { border: 0; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 4px; }
.ob-pic { position: relative; display: flex; align-items: center; justify-content: center; padding: 3px 0; border-radius: 10px;
  border: 1px solid var(--d-bd-e2e5ee); background: var(--surface); cursor: pointer; }
.ob-pic:hover { border-color: var(--d-bd-a9b0c2); }
.ob-pic.is-on { border: 2px solid var(--accent-line); background: var(--d-bg-f3f5fc); padding: 2px 0; }
.ob-pic input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.ob-pic:focus-within { box-shadow: 0 0 0 3px var(--d-sh-252a59-a18); }
.ob-pic img, .ob-init { width: 38px; height: 38px; border-radius: 999px; display: block; }
.ob-init { background: var(--accent); color: var(--on-fill); display: flex; align-items: center; justify-content: center; font-weight: 800;
  font-size: 0.8125rem; }
.ob-tour-k { margin: 0; font-size: 0.75rem; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
