.pf-name { font-size: 1.12rem; color: var(--accent-ink); overflow-wrap: anywhere; }
.pf-title { font-size: 0.9rem; color: var(--d-fg-333948); overflow-wrap: anywhere; }
.pf-jg { align-self: flex-start; margin-top: 3px; font-size: 0.75rem; font-weight: 600; color: var(--accent-ink); background: var(--d-bg-eef0f6);
  border-radius: 999px; padding: 2px 9px; }
.pf-dl { margin: 0; display: grid; grid-template-columns: 128px minmax(0, 1fr); row-gap: 11px; column-gap: 14px;
  font-size: 0.86rem; border-top: 1px solid var(--line-soft); padding-top: 16px; }
.pf-dl dt { color: var(--muted); }
.pf-dl dd { margin: 0; color: var(--ink); overflow-wrap: anywhere; font-variant-numeric: tabular-nums; }
.pf-dl dd.pf-none, .pf-title.pf-none { color: var(--d-fg-8a90a3); }
.pf-foot { margin: 0; padding-top: 12px; border-top: 1px solid var(--line-soft); font-size: 0.8rem; line-height: 1.5; color: var(--muted); }
.pf-row { flex-direction: row; align-items: center; gap: 16px; }
.pf-row-t { display: flex; flex-direction: column; gap: 3px; min-width: 0; flex: 1; }
.pf-row-t span { font-size: 0.8rem; color: var(--muted); }
.pf-row .st-link { flex: none; background: var(--surface); font: inherit; font-size: 0.86rem; font-weight: 600; cursor: pointer; }
/* the panels: the dashboard drawer's frame, a form inside with a header, a scrolling body and a footer */
.pf-sheet { margin: 0; }
.pf-dh { padding: 18px 24px 14px; border-bottom: 1px solid var(--line-soft); }
.pf-db { flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: 18px 24px; display: flex; flex-direction: column; gap: 16px; }
