.pf-cancel { min-height: 40px; padding: 0 16px; border: 1px solid var(--d-bd-c9cdda); border-radius: 8px; background: var(--surface); color: var(--ink);
  font: inherit; font-size: 0.86rem; font-weight: 600; cursor: pointer; }
