.pf-drawer .st-pic { padding: 8px 2px; }
.pf-drawer .st-pic.is-on { padding: 7px 1px; }
.pf-drawer .st-pic img, .pf-drawer .st-pic .st-init { width: 44px; height: 44px; font-size: 0.9375rem; }
.pf-f { display: flex; flex-direction: column; gap: 6px; }
