.od-nrow .od-ats.od-ats-wrap { white-space: normal; overflow: visible; text-overflow: clip; }   /* the Grade H HOD row (Your next step): its sentence is the point of the row, so it wraps (2026-11-02) */
.od-nrow .od-btn-ai, .od-nrow .od-btn-nv { flex: none; min-height: 30px; min-width: 212px; padding: 0 12px; font-size: 0.75rem;
  justify-content: center; box-sizing: border-box; }
.od-chips { margin: 0; display: flex; flex-wrap: wrap; gap: 6px; }
.od-chip { padding: 2px 8px; border-radius: 999px; background: var(--d-bg-f1f3f8); font-size: max(10px, 0.71875rem); color: var(--d-fg-3a4050); text-decoration: none; }
.od-chip b { font-weight: 600; }
.od-chip:hover { background: var(--d-bg-e6e9f2); color: var(--accent-ink); text-decoration: none; }
.od-chip:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--d-sh-252a59-a22); }
.od-calm .od-lines { border-top: 0; gap: 2px; }
.od-calm .od-ln { padding: 0; font-size: max(10px, 0.71875rem); color: var(--faint); border-bottom: 0; }
.od-calm .od-ln.is-done { gap: 10px; font-size: 0.78125rem; color: var(--d-fg-3a4050); }
.od-calm .od-ln .od-btn-ai { flex: none; min-height: 30px; min-width: 212px; padding: 0 12px; font-size: 0.75rem;
  justify-content: center; box-sizing: border-box; }
/* where you stand: label and value, nothing else */
.od-stand { gap: 2px; }
.od-stand .od-hd { margin-bottom: 8px; }
.od-stand .od-li, #od-own-p-own .od-li { padding: 9px 0; border-bottom: 0; border-top: 1px solid var(--d-bd-f0f1f5); }
.od-stand .od-li dt, #od-own-p-own .od-li dt { font-size: 0.78125rem; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--muted); }
.od-stand .od-li .v, #od-own-p-own .od-li .v { font-size: 0.78125rem; font-weight: 600; color: var(--ink); }
.od-stand .od-li .v.is-pending, #od-own-p-own .od-li .v.is-pending { font-weight: 400; color: var(--muted); }
/* a BU / BG CEO's card, BU / Own (Chris, 2026-10-26): the switch in the head, the count under the title, and Own as the
   employee's Where you stand rows with Details at the foot */
.od-hd.is-tabs { align-items: center; }
.od-own-sub { margin: -8px 0 0; }
.od-own-pane { display: flex; flex-direction: column; gap: inherit; min-height: 0; }
.od-own-pane[hidden], .od-own-sub[hidden] { display: none; }
#od-own-p-own { gap: 0; }
.od-own-foot { display: flex; justify-content: flex-end; padding-top: 6px; }
.od-vlink { font-size: inherit; font-weight: inherit; color: var(--accent-ink); text-align: right; }
/* history and tools: compact rows, a line between them */
.od-hist, .od-tools { gap: 2px; }
.od-hist .od-hd, .od-tools .od-hd { margin-bottom: 6px; }
.od-rows { gap: 0; }
.od-row { padding: 9px 2px; border: 0; border-top: 1px solid var(--d-bd-f0f1f5); border-radius: 0; }
.od-row:hover { border-color: var(--d-bd-f0f1f5); background: var(--d-bg-fafbfd); }
.od-row .cy { font-size: 0.78125rem; font-weight: 600; color: var(--ink); }
.od-row .cy small { font-size: max(10px, 0.71875rem); }
.od-tcard { padding: 9px 2px; border: 0; border-top: 1px solid var(--d-bd-f0f1f5); border-radius: 0; gap: 10px; }
.od-tcard:hover { border-color: var(--d-bd-f0f1f5); background: var(--d-bg-fafbfd); }
.od-tc-ico { display: none; }
.od-tc-txt { flex-direction: row; align-items: baseline; gap: 10px; }
.od-tc-txt b { flex: none; white-space: nowrap; font-size: 0.78125rem; font-weight: 600; }   /* the tool's name whole; its line gives way */
