.rm2-when > .rm-h, .rm2-when > .rm2-acts { grid-column: 1 / -1; }
.rm2-email { grid-area: email; } .rm2-prev { grid-area: prev; }
.rm2 .rm-card { min-width: 0; }
.rm2-col { flex-direction: column; align-items: flex-start; gap: 5px; }
.rm2-dayrow { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
