.rm2-two { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.rm2-secs { display: flex; flex-direction: column; gap: 4px; }
.rm2-four { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.rm2-lbl { font-size: .78rem; font-weight: 600; color: var(--d-fg-2f3552); }
.rm2-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.rm2-chip { min-height: 24px; padding: 0 8px; border: 1px solid var(--d-bd-d7dbe6); border-radius: 999px; background: var(--d-bg-f6f7fb); color: var(--d-fg-3a4157);
  font: 0.75rem ui-monospace, Menlo, monospace; cursor: pointer; }
