/* Email (Chris, 2026-10-24, canvas QUJSd9ATVKeiNrC7Kwb244 option A): Schedule, Everyone's reminder in sentences,
   Emails and templates with the preview docked on the right, Sent */
.eml { display: flex; flex-direction: column; gap: 14px; }
.eml .admin-card { margin: 0; min-width: 0; }
.eml h2 { margin: 0; font-size: 1.05rem; }
.eml-tpl { display: inline-block; border-radius: 6px; padding: 2px 8px; font-size: .78rem; font-weight: 600; line-height: 1.4;
  background: var(--d-bg-eef0f8); color: var(--accent-ink); white-space: nowrap; }
.eml-tpl.is-dated { background: var(--d-bg-fdebec); color: var(--d-fg-9e1219); }
.eml-tpl.is-off { background: var(--d-bg-f1f2f5); color: var(--muted); }
.eml-tpl.is-gh { background: var(--d-bg-efeaf7); color: var(--d-fg-5b4b8a); }   /* Grade H's own email (the module's purple) */
.eml-tpl:not(.is-gh) + .eml-tpl.is-gh { margin-left: 6px; }
.eml-pvo { row-gap: 6px; }
.eml-pvo [data-v="en"] { margin-left: 14px; }   /* the preview's two choices (case, language) read as two groups */
.eml-amber { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 6px 8px; border: 1px solid var(--d-bd-f1dfb5); border-radius: 8px; background: var(--d-bg-fdf3df); color: var(--d-fg-7a4b00); font-size: .88rem; }
.eml-amber b { flex: none; }
.eml-switch { display: inline-flex; align-items: center; gap: 10px; border: 0; background: none; padding: 0; font: inherit;
  font-weight: 700; color: var(--accent-ink); cursor: pointer; white-space: nowrap; }
.eml-switch.is-ro { cursor: default; }
.eml-track { position: relative; width: 40px; height: 22px; border-radius: 999px; background: var(--line-strong); flex: none; transition: background .15s; }
.eml-track::after { content: ""; position: absolute; left: 3px; top: 3px; width: 16px; height: 16px; border-radius: 50%; background: var(--surface);
  transition: left .15s; }
.eml-switch.is-on .eml-track { background: var(--accent); }
.eml-switch.is-on .eml-track::after { left: 21px; }
.eml-setup { white-space: nowrap; }
/* Schedule: the days, and the first one at a glance */
.eml-grid { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: 14px; align-items: stretch; }
.eml-plan-h { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; }
.eml-chips { display: flex; gap: 6px; flex-wrap: wrap; }
.eml-chip { min-height: 28px; padding: 0 11px; border: 1px solid var(--d-bd-d7dbe6); border-radius: 999px; background: var(--surface); color: var(--d-fg-3a4157); font: inherit;
  font-size: .8rem; font-weight: 600; cursor: pointer; }
.eml-chip.is-on { background: var(--accent); border-color: var(--accent-line); color: var(--on-fill); }
.eml-parts { display: flex; flex-wrap: wrap; gap: 4px 14px; margin: 10px 0 0; font-size: .82rem; color: var(--ink-2); }
.eml-parts[hidden], .eml-row[hidden], .eml-grp[hidden], .eml-none[hidden] { display: none; }
.eml-grp { margin: 16px 0 2px; font-size: .74rem; font-weight: 800; letter-spacing: .05em; text-transform: uppercase; color: var(--d-fg-5b6275); }
.eml-row { display: grid; grid-template-columns: 150px 44px minmax(0, 1fr) 160px; gap: 12px; padding: 9px 0; border-top: 1px solid var(--line-soft);
  align-items: start; font-size: .88rem; }
.eml-row > div:first-child { display: flex; flex-direction: column; gap: 1px; }
.eml-what { display: block; margin-top: 4px; color: var(--ink-2); }
.eml-none { margin: 8px 0 0; }
.eml-foot { margin: 12px 0 0; }
.eml-glance { display: flex; flex-direction: column; gap: 8px; }
.eml-glance > p { margin: 0; }
.eml-dl { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 6px 12px; margin: 4px 0; font-size: .88rem; }
.eml-dl dt { color: var(--ink-2); } .eml-dl dd { margin: 0; text-align: right; font-weight: 700; overflow-wrap: anywhere; }
.eml-pick { flex-direction: column; align-items: stretch; gap: 4px; margin-top: 6px; }
.eml-frame iframe { height: 460px; }
.eml-glance .eml-frame { flex: 1 1 auto; min-height: 460px; overflow: hidden; border: 1px solid var(--line); border-radius: 10px; }
.eml-glance .eml-frame iframe { position: absolute; left: 0; top: 0; border: 0; border-radius: 0; transform-origin: 0 0; }   /* scaled by the page */
/* Everyone's reminder: four sentences */
.eml-main { display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.eml-card { display: flex; flex-direction: column; gap: 6px; }
.eml-when { margin: 0; display: flex; flex-direction: column; gap: 4px; }
.eml-when fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }
.eml-when-h, .eml-card-h { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.eml-own { margin: 0; }
.eml-sent { display: flex; align-items: center; gap: 8px 10px; flex-wrap: wrap; padding: 11px 0; border-top: 1px solid var(--line-soft); font-size: .95rem; }
.eml-when-h + fieldset .eml-sent:first-of-type { border-top: 0; }
.eml-step { flex: none; width: 22px; height: 22px; border-radius: 50%; background: var(--d-bg-e9ecf6); color: var(--accent-ink); font-size: .76rem; font-weight: 800;
  display: inline-flex; align-items: center; justify-content: center; }
.eml-tick { display: inline-flex; align-items: center; gap: 7px; }
.eml-tick input { width: 16px; height: 16px; margin: 0; accent-color: var(--accent-ink); }
.eml-sel { height: 34px; box-sizing: border-box; padding: 0 9px; border: 1px solid var(--line-strong); border-radius: 8px; font: inherit; font-size: .9rem;
