.eml-when fieldset:disabled .eml-sel { background: var(--d-bg-f6f7fa); color: var(--muted); }
.eml-words { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px 16px; align-items: center; margin-top: 4px; }
.eml-who-p { margin: 0; font-size: .92rem; }
.eml-tiles { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-top: 4px; }
.eml-tile { display: flex; flex-direction: column; gap: 2px; background: var(--surface-2); border-radius: 8px; padding: 9px 12px; font-size: .86rem; }
