.eml-acts { display: flex; justify-content: flex-end; align-items: center; gap: 10px; flex-wrap: wrap; }
.eml-acts form { margin: 0; }
.eml-day { display: flex; flex-direction: column; gap: 3px; padding: 8px 0; border-top: 1px solid var(--line-soft); font-size: .86rem; }
/* Emails and templates: the list, the editor, the preview docked on the right (the list folds while it's open) */
.eml-tg { display: grid; grid-template-columns: 270px minmax(0, 1fr); gap: 14px; align-items: stretch; }
.eml-tg.is-pv { grid-template-columns: minmax(0, 1fr) 440px; }
