.eml-list { padding: 12px; display: flex; flex-direction: column; gap: 2px; }
.eml-mod { margin: 12px 4px 4px; font-size: .72rem; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: var(--d-fg-5b6275); }
.eml-mod:first-child { margin-top: 2px; }
.eml-em { border-radius: 10px; padding: 8px 10px; border: 1px solid transparent; display: flex; flex-direction: column; gap: 2px; }
.eml-em.is-on { background: var(--d-bg-f1f3fa); border-color: var(--d-bd-d9ddec); }
.eml-em > b, .eml-em > a b { font-size: .9rem; }
.eml-t { display: flex; justify-content: space-between; align-items: center; gap: 8px; padding: 4px 6px 4px 10px; border-radius: 6px;
  font-size: .84rem; color: var(--d-fg-1e2230); text-decoration: none; }
.eml-t:hover { background: var(--d-bg-e9ecf6); }
.eml-t.is-on { font-weight: 700; color: var(--accent-ink); background: var(--surface); box-shadow: inset 3px 0 0 var(--accent-line); }
.eml-t-n { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.eml-ed { display: flex; flex-direction: column; gap: 10px; }
.eml-ed-h, .eml-pv-h { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; flex-wrap: wrap; }
