.eml-ed-btns { display: flex; gap: 8px; flex-wrap: wrap; }
.eml-ed-meta { margin: 0; }
.eml-form { flex: 1 1 auto; }
.eml-name { max-width: 420px; }
.eml-modes, .rm2-form fieldset.eml-modes { border: 0; margin: 0; padding: 0; display: flex; flex-direction: row; align-items: center;
  gap: 6px 18px; flex-wrap: wrap; min-width: 0; }
.eml-modes legend { float: left; width: 100%; margin-bottom: 2px; }
.eml-modes .muted { flex-basis: 100%; }
.rm2-form .eml-modes label { flex-direction: row; align-items: center; gap: 7px; font-size: .88rem; font-weight: 400; color: var(--d-fg-1e2230); }
.rm2-form .eml-modes input[type=radio] { width: auto; height: auto; margin: 0; accent-color: var(--accent-ink); }
.rm2-form .eml-modes input[type=date] { width: 9.375rem; }
.eml-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px 12px; }
.eml-wide { grid-column: 1 / -1; }
.eml-ed-foot { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-top: auto; padding-top: 12px; border-top: 1px solid var(--line-soft); }
.eml-ed-foot .em-danger { padding: 0; }
.rm2-btn2.is-on { background: var(--d-bg-e9ecf6); border-color: var(--d-bd-c3c9de); }
.eml-pv { display: flex; flex-direction: column; gap: 10px; box-shadow: -8px 0 24px var(--d-sh-141830-a06); }
.eml-pv[hidden] { display: none; }
.eml-pv > p { margin: 0; }
.eml-pv .rm2-pick { flex-direction: column; align-items: stretch; gap: 4px; }
.eml-pv .eml-frame { flex: 1 1 auto; min-height: 620px; overflow: hidden; border: 1px solid var(--line); border-radius: 10px; }
.eml-pv .eml-frame iframe { position: absolute; left: 0; top: 0; border: 0; border-radius: 0; transform-origin: 0 0; }   /* scaled by the page */
.eml-x { width: 34px; padding: 0; font-size: 1.1rem; }
/* Sent: the runs side by side */
.eml-two { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; align-items: stretch; }

/* Release results: what each release emails (2026-10-17) */
.rr2-mail { display: flex; flex-direction: column; gap: 4px; margin: 10px 0 0; padding: 10px 12px; border: 1px solid var(--d-bd-e1e4ec);
  border-radius: 10px; background: var(--d-bg-f8f9fc); font-size: .86rem; color: var(--ink-2); }
.rr2-mail > b { color: var(--accent-ink); font-size: .78rem; letter-spacing: .04em; }
