[data-kpi-scale-bad] { border-color: var(--d-bd-b5141d) !important; box-shadow: 0 0 0 2px var(--d-sh-d61923-a12); }
form[data-kpi-scale] button[type="submit"]:disabled { opacity: .45; cursor: not-allowed; }
/* Add a person's new fields (2026-10-18): a hint or the group-transfer tick takes the grid's whole row */
.adm-add-user .pp-fields .adm-add-hint { grid-column: 1 / -1; margin: -6px 0 2px; }
.adm-add-user .pp-fields label.adm-add-check { grid-column: 1 / -1; flex-direction: row; align-items: center; gap: 8px; color: var(--ink-2); }
/* The person page's Competency: their job in the architecture (2026-10-18) */
.pp-chip.is-warn { background: var(--d-bg-fdf3e1); color: var(--d-fg-8a5a00); }
.pp-place-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
