.pp-place-form { display: flex; flex-direction: column; gap: 8px; margin-top: 8px; }
.pp-place-opt { display: grid; grid-template-columns: 20px minmax(0, 1fr) auto; gap: 8px; align-items: center; padding: 8px 10px; border: 1px solid var(--line); border-radius: 8px; font-size: 0.8125rem; }
.pp-place-sel { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.pp-place-sel label { display: flex; flex-direction: column; gap: 4px; font-size: 0.78125rem; color: var(--muted); }
.pp-place-btns { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
/* People > New joiners (2026-10-18) */
.jn-via { margin-top: 8px; }
.jn-bar { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin: 12px 0 8px; }
.jn-card { padding: 0; overflow: hidden; }
.jn-row { display: grid; grid-template-columns: 28px minmax(0, 1.7fr) minmax(0, 1.2fr) 96px minmax(0, 1.5fr) 150px 70px 60px; gap: 12px; align-items: center; padding: 10px 16px; border-top: 1px solid var(--line-soft); font-size: 0.8125rem; }
.jn-row.jn-head { border-top: 0; font-size: max(10px, 0.71875rem); color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
