.jn-line { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.jn-ok { display: inline-block; padding: 2px 8px; border-radius: 999px; background: var(--d-bg-e8f5ee); color: var(--d-fg-1d6b41); font-size: max(10px, 0.71875rem); white-space: nowrap; }
.jn-wait { display: inline-block; padding: 2px 8px; border-radius: 999px; background: var(--d-bg-fdf3e1); color: var(--d-fg-8a5a00); font-size: max(10px, 0.71875rem); white-space: nowrap; }
/* Home's new-joiner card (2026-10-18) */
.hj-card { display: flex; flex-direction: column; gap: 12px; margin-bottom: 18px; }
.hj-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; flex-wrap: wrap; }
.hj-what { display: flex; flex-direction: column; gap: 4px; max-width: 820px; }
.hj-what b { font-size: 0.9375rem; }
.hj-k { font-size: max(10px, 0.71875rem); letter-spacing: .04em; text-transform: uppercase; color: var(--muted); font-weight: 600; display: inline-flex; gap: 8px; align-items: center; }
.hj-k a:hover { color: var(--d-fg-1d2249); background: var(--d-bg-eef1fa); box-shadow: 0 0 0 3px var(--d-bg-eef1fa); border-radius: 4px; }
