.lp-photo { width: 320px; flex: none; min-height: 190px; background: linear-gradient(135deg, var(--d-bg-3a4372), var(--accent) 55%, var(--d-bg-7d2a3a)); }
.lp-photo img { width: 100%; height: 100%; object-fit: cover; display: block; }
.lp-hero-txt { flex: 1; min-width: 0; padding: 16px 20px; display: flex; flex-direction: column; gap: 8px; }
.lp-title { margin: 0; font-size: 1.5rem; color: var(--accent-ink); }
.lp-sum { margin: 0; font-size: 0.875rem; line-height: 1.5; }
.lp-chips { display: flex; gap: 6px; flex-wrap: wrap; }
.ls-chip.lp-mine { background: var(--accent); color: var(--on-fill); }
.lp-hero-acts { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.lp-details .ls-h { margin-top: 12px; }
.lp-details .ls-h:first-child { margin-top: 0; }
.lp-list { margin: 4px 0 0; padding-left: 20px; font-size: 0.84375rem; line-height: 1.6; }
.lp-text { margin: 4px 0 0; font-size: 0.84375rem; line-height: 1.55; }
.lp-run { display: grid; grid-template-columns: 1fr auto auto; gap: 12px; align-items: center; padding: 10px 0;
  border-top: 1px solid var(--line); font-size: 0.84375rem; }
.lp-run:first-of-type { border-top: 0; }
@media (max-width: 760px) { .lp-hero, .ls-card.lp-hero { flex-direction: column; } .lp-photo { width: 100%; height: 180px; }
  .lp-run { grid-template-columns: 1fr; } }
.lm-pp-photo { height: 170px; border-radius: 10px; overflow: hidden; margin: 6px 0 10px;
  background: linear-gradient(135deg, var(--d-bg-3a4372), var(--accent) 55%, var(--d-bg-7d2a3a)); display: flex; align-items: center; justify-content: center; }
.lm-pp-photo img { width: 100%; height: 100%; object-fit: cover; }
.lm-pp-photo.is-empty .muted { color: var(--on-fill); opacity: .8; }
.lm-pp-doc { display: flex; gap: 10px; align-items: center; margin: 12px 0 6px; font-size: 0.8125rem; }
.lm-pp-pdf { width: 34px; height: 42px; border-radius: 5px; background: var(--d-bg-fdecec); color: var(--d-fg-a8151d); font-size: max(10px, 0.625rem); font-weight: 800;
  display: flex; align-items: center; justify-content: center; flex: none; }
.lm-pp-prop { border: 1px solid var(--d-bd-e9a3a7); background: var(--d-bg-fffafa); border-radius: 8px; padding: 10px 12px; margin-bottom: 10px;
  display: flex; flex-direction: column; gap: 6px; }
.lm-pp-from { font-size: max(10px, 0.6875rem); font-weight: 700; color: var(--ai-ink); }
.lm-pp-ptext { font-size: 0.8125rem; line-height: 1.5; }
/* Announce a programme (2026-10-22, board 16B) */
.lm-ann { display: flex; flex-direction: column; gap: 0; }
.lm-radio { display: flex; align-items: center; gap: 8px; font-size: 0.84375rem; margin: 4px 0; flex-wrap: wrap; }
.lm-ann-rows { margin: 8px 0 0 24px; display: flex; flex-direction: column; gap: 6px; }
.lm-pickrow { border: 1px solid var(--line); border-radius: 8px; background: var(--surface); }
.lm-pickrow > summary { list-style: none; display: flex; align-items: center; gap: 10px; padding: 8px 10px; cursor: pointer;
  flex-wrap: wrap; }
.lm-pickrow > summary::-webkit-details-marker { display: none; }
.lm-pickrow-l { width: 120px; flex: none; font-size: 0.78125rem; color: var(--muted); }
.lm-pickrow-v { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }
.lm-chip.on { background: var(--accent); color: var(--on-fill); }
.lm-picklist { border-top: 1px solid var(--line); padding: 8px 10px; }
.lm-pickfind { width: 100%; max-width: 320px; margin-bottom: 8px; padding: 6px 8px; border: 1px solid var(--d-bd-d7dbe6);
  border-radius: 8px; font: inherit; font-size: 0.8125rem; }
.lm-pickopts { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 4px 12px;
  max-height: 220px; overflow: auto; font-size: 0.8125rem; }
.lm-pickopts label { display: flex; align-items: center; gap: 6px; }
.lm-pickopts label[hidden] { display: none; }
.lm-ann-count { margin-top: 12px; padding: 10px 12px; border-radius: 8px; background: var(--d-bg-f7f8fc); font-size: 0.84375rem;
  display: flex; gap: 8px; align-items: baseline; flex-wrap: wrap; }
.lm-ann-count .lm-ann-aud { flex-basis: 100%; color: var(--muted); }
/* Learning › Settings › L&D admins: their emails one a line, an add box under them, the actions on one line
   (2026-10-23, the LMS gap check) */
.lm-lnd-table td { vertical-align: top; }
.lm-lnd-table form.lm-lnd-mail, .lm-lnd-table form.lm-lnd-add { display: flex; align-items: center; gap: 8px; margin: 0 0 4px; }
.lm-lnd-table form.lm-lnd-add input { width: 15rem; height: 30px; box-sizing: border-box; border: 1px solid var(--d-bd-d7dbe6);
  border-radius: 8px; padding: 0 8px; font: inherit; font-size: 0.8125rem; }
.lm-lnd-table td.lm-lnd-acts { white-space: nowrap; }
.lm-lnd-table td.lm-lnd-acts form { display: inline-block; margin: 0 12px 0 0; }
/* an external course after it ends (2026-10-23, boards 18E / 18F): the person's certificate card, L&D's check */
.ls-file { display: flex; flex-direction: column; gap: 4px; font-size: 0.78125rem; color: var(--muted); }
.ls-file input[type=file] { font: inherit; font-size: 0.8125rem; color: var(--ink); }
.ls-ext .ls-ext-up { display: flex; flex-direction: column; gap: 10px; margin: 10px 0 0; }
.ls-ext .ls-ext-up .ln-acts { justify-content: flex-end; }
.ls-ext-sent { font-size: 0.8125rem; margin: 6px 0 0; }
.lm-ext-dl { display: grid; grid-template-columns: 140px 1fr; gap: 6px 12px; margin: 8px 0 12px; font-size: 0.84375rem; }
.lm-ext-dl dt { color: var(--muted); }
.lm-ext-dl dd { margin: 0; }
.lm-ext-acts { display: flex; align-items: center; justify-content: flex-end; gap: 16px; flex-wrap: wrap; }
.lm-ext-check { display: inline-flex; align-items: center; gap: 8px; }
.lm-ext-check label { display: inline-flex; align-items: center; gap: 6px; font-size: 0.78125rem; color: var(--muted); }
.lm-ext-check input { width: 70px; height: 32px; box-sizing: border-box; border: 1px solid var(--d-bd-d7dbe6); border-radius: 8px;
  padding: 0 8px; font: inherit; font-size: 0.8125rem; }
.lm-units-k { margin: 10px 0 4px; }
.lm-units { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 2px 16px; }
.lm-unitpick summary { cursor: pointer; font-size: 0.8125rem; color: var(--ink); list-style: none; padding: 3px 0; }
.lm-unitpick summary::-webkit-details-marker { display: none; }
.lm-unitpick summary::before { content: "+"; display: inline-block; width: 14px; color: var(--muted); }
.lm-unitpick[open] summary::before { content: "\2013"; }
.lm-unitpick[open] { grid-column: 1 / -1; }
.lm-unitpick .lm-check { margin: 2px 0 2px 14px; }
.lm-fld { display: flex; flex-direction: column; gap: 4px; font-size: 0.78125rem; color: var(--muted); margin-bottom: 10px; }
.lm-fld input, .lm-fld textarea { font: inherit; font-size: 0.84375rem; color: var(--ink); border: 1px solid var(--d-bd-d7dbe6);
  border-radius: 8px; padding: 8px 10px; }
.lm-ann-send { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.lm-ann-send .grow { flex: 1; }
/* Settings › Emails (2026-10-22, board 16A) */
.lm-emails .lm-egroup th { text-align: left; font-size: max(10px, 0.6875rem); letter-spacing: .07em; text-transform: uppercase;
  color: var(--muted); background: var(--d-bg-f7f8fc); padding: 7px 10px; }
.lm-switch { width: 34px; height: 19px; border-radius: 999px; border: 0; background: var(--d-bg-c3c8d6); position: relative;
  cursor: pointer; padding: 0; }
.lm-switch span { position: absolute; top: 2px; left: 2px; width: 15px; height: 15px; border-radius: 50%; background: var(--surface);
  transition: left .15s; }
.lm-switch.is-on { background: var(--accent); }
.lm-switch.is-on span { left: 17px; }
.lm-switch:focus-visible { outline: 3px solid var(--d-bd-8e96c4); outline-offset: 2px; }
.lm-wacts { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }   /* Preview and Wording...: their boxes (10px padding) stay 8px apart, side by side or stacked */
.lm-words { display: inline-block; margin-left: 0; }
.lm-words > summary { list-style: none; display: inline-block; cursor: pointer; }
.lm-words > summary::-webkit-details-marker { display: none; }
.lm-words[open] form { margin-top: 8px; min-width: 320px; }
.ls-none { margin: 0; font-size: 0.8125rem; color: var(--muted); }
.ls-rate { display: flex; flex-direction: column; gap: 8px; }
.ls-scale { border: 0; margin: 0; padding: 0; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.ls-scale legend { float: left; width: 260px; padding: 0; font-size: 0.8125rem; color: var(--ink); }
.ls-scale label { position: relative; }
.ls-scale input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.ls-scale span { display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 30px;
  border: 1px solid var(--d-bd-c3c8d6); border-radius: 8px; font-size: 0.8125rem; font-weight: 600; cursor: pointer; background: var(--surface); }
.ls-scale input:checked + span { background: var(--accent); border-color: var(--accent-line); color: var(--on-fill); }
.ls-scale input:focus-visible + span { outline: 2px solid var(--accent-line); outline-offset: 2px; }
.ls-full { display: flex; flex-direction: column; gap: 4px; font-size: 0.78125rem; color: var(--muted); }
.ls-table { width: 100%; border-collapse: collapse; font-size: 0.8125rem; }
.ls-table th { text-align: left; font-size: max(10px, 0.71875rem); color: var(--muted); font-weight: 600; padding: 6px 8px;
  border-bottom: 1px solid var(--line); }
.ls-table td { padding: 8px; border-bottom: 1px solid var(--line-soft); vertical-align: top; }
.ls-table tr:last-child td { border-bottom: 0; }
.ls-num, .ls-table th.ls-num { text-align: right; white-space: nowrap; }
.ls-decide { align-items: flex-start; }
.ls-ret { display: flex; gap: 8px; flex: 1; min-width: 260px; }
.ls-ret input { flex: 1; min-width: 0; }
.ls-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.ls-nom { display: flex; align-items: flex-end; gap: 12px; flex-wrap: wrap; margin: 0; }
.ls-nom label { display: flex; flex-direction: column; gap: 4px; font-size: 0.78125rem; color: var(--muted); min-width: 220px; flex: 1; }
.ls-round { display: flex; flex-direction: column; gap: 10px; margin: 0; padding-top: 10px; border-top: 1px solid var(--line-soft); }
.ls-h + .ls-round { border-top: 0; padding-top: 0; }
.ls-rsess { border: 1px solid var(--line); border-radius: 10px; padding: 8px 12px 10px; margin: 0;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 4px 14px; }
.ls-rsess legend { font-size: 0.8125rem; padding: 0 4px; }
.ls-pk { display: flex; align-items: flex-start; gap: 8px; padding: 5px 6px; border-radius: 8px; font-size: 0.8125rem; }
.ls-pk.is-fit { background: var(--d-bg-f3f4fa); }
.ls-pk input { margin-top: 3px; }
/* the nomination forms' reason (2026-10-23, the LMS gap check): Who and Session side by side, the reason under them
   full width, the button at the right; .ln-card's column rule otherwise stacked them right-aligned */
#ln form.ls-nom { display: grid; grid-template-columns: minmax(220px, 1fr) minmax(0, 2fr); gap: 12px; align-items: end; }
#ln form.ls-nom label { min-width: 0; }
#ln form.ls-nom .ls-why, #ln form.ls-nom .ln-acts { grid-column: 1 / -1; }
#ln form.ls-nom .ln-acts { justify-content: flex-end; }
.ls-why { display: flex; flex-direction: column; gap: 4px; font-size: 0.78125rem; color: var(--muted); }
.ls-why input { width: 100%; box-sizing: border-box; height: 34px; border: 1px solid var(--d-bd-d7dbe6); border-radius: 8px;
  padding: 0 10px; font: inherit; font-size: 0.8125rem; color: var(--ink, var(--d-fg-1f2433)); }
.ls-pk > span { display: flex; flex-direction: column; min-width: 0; }
.ls-star { display: inline-block; margin-left: 4px; padding: 0 6px; border-radius: 999px; font-size: max(10px, 0.65625rem); font-weight: 700;
  background: var(--d-bg-eef0f7); color: var(--accent-ink); }
@media (max-width: 900px) {
  .ls-body { grid-template-columns: minmax(0, 1fr); }
  .ls-queue { position: static; border-bottom: 1px solid var(--line); }
  .ls-main { border-left: 0; }
  .ls-aside { display: none; }
  .ls-main { padding: 16px; }
  .ls-tiles, .ls-tiles:has(.ls-tile-xp), .ls-grid2, .ls-rsess { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .ls-dl { grid-template-columns: minmax(0, 1fr); gap: 4px; }
  .ls-scale legend { float: none; width: 100%; }
}
/* clock in, on a phone */
.ck { max-width: 440px; margin: 8px auto 24px; background: var(--surface); border: 1px solid var(--line); border-radius: 14px;
  padding: 22px 20px; display: flex; flex-direction: column; gap: 12px; align-items: flex-start; }
.ck-title { margin: 0; font-size: 1.25rem; color: var(--accent-ink); line-height: 1.3; }
.ck-line { margin: 0; font-size: 0.84375rem; color: var(--muted); }
.ck-done { align-self: stretch; display: flex; flex-direction: column; align-items: center; gap: 6px; text-align: center;
  padding: 18px 14px; border-radius: 12px; background: var(--d-bg-e8f5ee); color: var(--d-fg-1d6b43); font-size: 0.84375rem; line-height: 1.5; }
.ck-done b { font-size: 1.125rem; }
.ck-done span:last-child { color: var(--d-fg-2c5a41); }
.ck-done.is-walkin { background: var(--d-bg-fff4dc); color: var(--d-fg-7a4b00); }
.ck-done.is-walkin span:last-child { color: var(--d-fg-6a4a10); }
.ck-tick { width: 48px; height: 48px; border-radius: 50%; background: currentColor; display: flex; align-items: center;
  justify-content: center; }
.ck-tick svg { width: 26px; height: 26px; color: var(--on-fill); }
.ck-msg { margin: 0; align-self: stretch; padding: 8px 10px; border-radius: 8px; background: var(--d-bg-fdecec); color: var(--d-fg-a8151d); font-size: 0.8125rem; }
.ck-form { align-self: stretch; display: flex; flex-direction: column; gap: 8px; margin: 0; }
.ck-form label { font-size: 0.8125rem; color: var(--muted); }
.ck-form input[name=c] { font: 700 1.75rem/1 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: .25em; text-align: center;
  padding: 12px; border: 1px solid var(--d-bd-c3c8d6); border-radius: 10px; color: var(--accent-ink); }
.ck-form button { min-height: 44px; }
.ck-note { margin: 0; font-size: 0.75rem; color: var(--muted); }
.ck-back { font-size: 0.8125rem; }
/* clock out, on a phone (2026-10-22, board 3D): one tap, or the last day's rating */
.ck-k { font-size: max(10px, 0.6875rem); font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
.ck-card { margin: 0; align-self: stretch; padding: 12px 14px; border: 1px solid var(--line); border-radius: 12px;
  font-size: 0.84375rem; line-height: 1.5; }
.ck-form .ck-big { min-height: 48px; font-size: 0.9375rem; }
.ck-rate { gap: 12px; }
.ck-rate .ls-scale legend { float: none; width: 100%; margin-bottom: 4px; }
/* the admin pages */
.lm-roomnote { margin: 0 0 10px; max-width: 760px; line-height: 1.5; }
.lm-roomlink { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.lm-roomlink input { flex: 1 1 360px; min-width: 0; font: 0.78125rem ui-monospace, SFMono-Regular, Menlo, monospace; color: var(--ink);
  background: var(--d-bg-f7f8fc); border: 1px solid var(--d-bd-d7dbe6); border-radius: 8px; padding: 8px 10px; }
.lm-shead { flex: 1; min-width: 0; }
.lm-kick { font-size: max(10px, 0.6875rem); font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--muted); }
.lm-stitle { margin: 2px 0; font-size: 1.1875rem; color: var(--accent-ink); }
.lm-shead p { margin: 0; }
.lm-cardhead { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin: 0 0 10px; }
.lm-cardhead .lm-h { margin: 0; flex: 1; min-width: 0; }
.lm-cardhead .lm-st + .lm-grow { flex: 1; }
.lm-tiles.is-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.lm-tile.is-flag b { color: var(--d-fg-a8151d); }
/* Learning › HRDC (2026-10-22, S13, board 10): sessions by business group against D-14, claims and queries */
.lm-hrdc { display: flex; flex-direction: column; gap: 16px; }
.lm-hrdc > .admin-card, .lm-hrdc-two > .admin-card { margin-top: 0; }
.lm-hg th[scope=row] { font-weight: 400; min-width: 220px; }
.lm-hg th[scope=row] b { color: var(--ink); }
.lm-hg-bg { text-align: center; font-size: max(10px, 0.71875rem); min-width: 84px; max-width: 120px; white-space: normal; line-height: 1.3; }
.lm-hg-note { display: block; font-size: max(10px, 0.71875rem); color: var(--muted); }
.lm-hg-d14 { white-space: nowrap; font-size: 0.78125rem; }
.lm-hg-d14.is-red { color: var(--d-fg-a8151d); font-weight: 600; }
.lm-hg tr.is-risk > * { background: var(--d-bg-fff8f8); }
.lm-hg-c { text-align: center; padding: 6px 6px; }
.lm-hc { display: flex; align-items: center; justify-content: center; min-height: 26px; padding: 2px 6px; border-radius: 6px;
  font-size: max(10px, 0.71875rem); font-weight: 600; white-space: nowrap; text-decoration: none; background: var(--d-bg-f7f8fc); color: var(--d-fg-9aa0ad); }
a.lm-hc:hover { text-decoration: none; box-shadow: 0 0 0 1px var(--accent-line); }
.lm-hc.is-not_filed { background: var(--d-bg-f1f3f8); color: var(--ink-2); }
.lm-hc.is-filed { background: var(--d-bg-eef0f7); color: var(--accent-ink); }
.lm-hc.is-query { background: var(--d-bg-fff4dc); color: var(--d-fg-8a5a00); }
.lm-hc.is-approved { background: var(--d-bg-e8f5ee); color: var(--d-fg-1d6b43); }
.lm-hc.is-rejected, .lm-hc.is-red { background: var(--d-bg-fdecec); color: var(--d-fg-a8151d); }
.lm-hrdc-two { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 16px; align-items: start; }
.lm-hl td, .lm-hl th { font-size: 0.78125rem; }
.lm-hl td.is-red { color: var(--d-fg-a8151d); font-weight: 600; }
.lm-hl td.is-amber { color: var(--d-fg-8a5a00); font-weight: 600; }
/* the L&D agent (2026-10-22, S15, board 14): today for L&D on the left, its conversation on the right */
.ld { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 16px; align-items: stretch;
  height: calc(100vh - 300px); min-height: 480px; }
.ld-more > summary { cursor: pointer; color: var(--accent-ink); font-weight: 600; padding: 4px 10px; }
.ld-more[open] { display: flex; flex-direction: column; gap: 6px; }
.ld > .admin-card { margin-top: 0; }
.ld-left { display: flex; flex-direction: column; gap: 6px; overflow: auto; }
.ld-k { font-size: max(10px, 0.6875rem); font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--muted); }
.ld-k2 { margin-top: 10px; }
.ld-q { display: flex; align-items: center; gap: 8px; padding: 8px 10px; border-radius: 8px; font-size: 0.8rem; color: var(--ink);
  text-decoration: none; border: 1px solid transparent; }
.ld-q:hover { text-decoration: none; border-color: var(--line); }
.ld-q.is-first { background: var(--d-bg-eef0f7); font-weight: 600; }
.ld-q > span:first-child { flex: 1; min-width: 0; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
  overflow: hidden; }
.ld-chip { flex: none; display: inline-flex; padding: 2px 8px; border-radius: 999px; font-size: max(10px, 0.71875rem); font-weight: 600;
  background: var(--d-bg-eef0f7); color: var(--accent-ink); white-space: nowrap; }
.ld-chip.is-red { background: var(--d-bg-fdecec); color: var(--d-fg-a8151d); }
.ld-chip.is-amber { background: var(--d-bg-fff4dc); color: var(--d-fg-8a5a00); }
.ld-asks { display: flex; flex-direction: column; gap: 6px; }
.ld-ask { text-align: left; border: 1px solid var(--d-bd-d7dbe6); background: var(--surface); color: var(--accent-ink); border-radius: 8px; padding: 7px 10px;
  font: inherit; font-size: 0.8rem; cursor: pointer; }
.ld-ask:hover:not(:disabled) { border-color: var(--accent-line); }
.ld-ask:disabled { opacity: .55; cursor: default; }
.ld-foot { margin-top: auto; padding-top: 10px; }
.ld-conv { display: flex; flex-direction: column; min-height: 0; padding: 0; overflow: hidden; }
.ld-log { flex: 1; min-height: 0; overflow: auto; padding: 18px 22px 8px; display: flex; flex-direction: column; gap: 12px; }
.ld-ai { display: flex; gap: 10px; align-items: flex-start; }
.ld-ai-b { display: flex; flex-direction: column; gap: 10px; min-width: 0; flex: 1; }
