.bk2-pill { display: inline-flex; align-items: center; justify-content: center; flex: none; height: 20px; box-sizing: border-box;
  padding: 0 10px; border-radius: 999px; font-size: max(10px, 0.6875rem); font-weight: 700; line-height: 1; white-space: nowrap; background: var(--surface-3); color: var(--ink-2); }
