.bk2-row:hover { background: var(--d-bg-f6f7fb); }
.bk2-row.is-on { background: var(--d-bg-ecedf6); }
.bk2-row.is-dim { opacity: .5; }
.bk2-rowh { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
.bk2-rowh b { font-size: 0.875rem; line-height: 1.25rem; min-width: 0; overflow-wrap: anywhere; color: var(--d-fg-1d2033); }
.bk2-sum { font-size: 0.78125rem; color: var(--muted); line-height: 1.4; }
.bk2-add { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 8px 4px; border-bottom: 1px solid var(--d-bd-f0f1f5); }
