.bk2-addt b { font-size: 0.84375rem; overflow-wrap: anywhere; }
.bk2-addb { flex: none; font: inherit; font-size: 0.78125rem; font-weight: 600; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--accent-line);
  background: var(--surface); color: var(--accent-ink); text-decoration: none; cursor: pointer; }
.bk2-addb:disabled { border-color: var(--d-bd-e0e2ea); background: var(--d-bg-f7f8fa); color: var(--d-fg-a3a6b5); cursor: default; }
.bk2-card { gap: 16px; padding: 20px 22px; }
.bk2-editing { border: 2px solid var(--accent-line); }
.bk2-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; }
