.bk2-form { margin: 0; display: inline-flex; }
.bk2-btn { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; min-height: 36px; padding: 0 16px;
  border-radius: 8px; font: inherit; font-size: 0.84375rem; font-weight: 600; text-decoration: none; cursor: pointer; white-space: nowrap; }
.bk2-off { color: var(--d-fg-a3141c); background: var(--surface); border: 1px solid var(--d-bd-e3a5a9); }
.bk2-off:hover { background: var(--d-bg-fdf3f3); }
