.bk2-editform { gap: 0; }

/* BU KPI setup: move some carriers to a variant (2026-10-29, canvas boards 1-5). A variant sits under its root in the rail; the
   panel is the super admin's. */
.bk2-row.is-sub { margin-left: 16px; border-left: 2px solid var(--d-bd-e4e6ee); border-radius: 0 10px 10px 0; }
/* the heading over 2+ saved variants of a root that is not saved (2026-11-06): the row's look, no pill, not a link; its variants sit under it as .is-sub */
.bk2-row.bk2-head { cursor: default; gap: 3px; }
.bk2-row.bk2-head:hover { background: transparent; }
.bk2-kick { display: block; }
.bk2-lk { background: none; border: 0; padding: 0; margin: 0; font: inherit; font-size: 0.8rem; font-weight: 600; color: var(--link); cursor: pointer;
  text-align: left; text-decoration: underline; text-underline-offset: 2px; align-self: flex-start; }
.bk2-lk:hover { color: var(--accent-ink); }
.bk2-tsub { font-size: 0.75rem; color: var(--muted); }
.bkv-form { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; }
.bkv-form [hidden] { display: none !important; }
#pnl-bkvar .bkv-body { gap: 18px; }
.bkv-sec { display: flex; flex-direction: column; gap: 8px; }
.bkv-nm { display: flex; align-items: center; gap: 8px; font-size: 0.875rem; flex-wrap: wrap; }
.bkv-fix { min-height: 34px; box-sizing: border-box; display: inline-flex; align-items: center; padding: 0 10px; background: var(--d-bg-f4f5fa); border: 1px solid var(--d-bd-e1e4ec);
  border-radius: 8px; color: var(--ink-2); font-weight: 600; max-width: 100%; }
.bkv-inp, .bkv-rates input, .bkv-one input, .bkv-band input { height: 34px; box-sizing: border-box; border: 1px solid var(--line-strong); border-radius: 8px; padding: 0 10px;
  font: inherit; font-size: 0.8125rem; font-weight: 400; background: var(--surface); color: var(--ink); min-width: 0; }
.bkv-q { width: 240px; }
.bkv-find { width: 100%; }
