.bkv-cnt { display: flex; align-items: baseline; gap: 14px; font-size: 0.8125rem; flex-wrap: wrap; }
.bkv-cntl { margin-left: auto; display: inline-flex; gap: 14px; }
.bkv-list { border: 1px solid var(--line-soft); border-radius: 8px; max-height: 300px; overflow-y: auto; overflow-x: hidden; scrollbar-width: thin; }
.bkv-pp { display: grid; grid-template-columns: 20px 150px minmax(0, 1fr) 52px 128px; column-gap: 14px; align-items: center; padding: 6px 10px; font-size: 0.8125rem;
  min-height: 32px; box-sizing: border-box; border-top: 1px solid var(--d-bd-f1f2f6); cursor: pointer; }
