.bkv-hh { position: sticky; top: 0; z-index: 1; background: var(--surface-2); color: var(--accent-ink); font-weight: 700; font-size: 0.75rem; min-height: 26px; border-top: 0; cursor: default; }
.bkv-pp span { min-width: 0; }
