.bkv-nmc { display: flex; align-items: center; gap: 6px; min-width: 0; }
.bkv-nmt { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.bkv-lock { flex: none; font-size: max(10px, 0.6875rem); font-weight: 700; color: var(--d-fg-8a5a00); background: var(--d-bg-fdf3e1); border-radius: 999px; padding: 1px 8px; white-space: nowrap; }
.bkv-pp.is-dis { color: var(--d-fg-a3a8b8); cursor: default; }
.bkv-list:has([data-gh]) .bkv-pp { grid-template-columns: 20px 14rem minmax(0, 1fr) 52px 128px; }   /* Grade H rows carry a chip beside the name: the name column grows so "Demo Staff H07" is never cut to "Demo Staff…" (2026-11-03) */
.bkv-pp.is-dis .bkv-id { color: var(--d-fg-a3a8b8); }
