.bkv-chg { background: var(--surface-2); border: 1px solid var(--line-soft); border-radius: 10px; padding: 12px 14px; display: flex; flex-direction: column; gap: 6px;
  font-size: 0.8125rem; color: var(--d-fg-2a3148); line-height: 1.45; }
.bkv-chg ul { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 4px; }
