.bf-rate { display: flex; flex-direction: column; gap: 2px; align-items: center; padding: 10px 6px; border-radius: 10px; background: var(--d-bg-f1f2f7); color: var(--d-fg-1d2033); min-width: 0; }
.bf-rate span { font-size: 0.75rem; color: var(--muted); }
