.bf-sub [data-bf-band]:empty { display: none; }
.bf-lab { font-size: 0.8125rem; font-weight: 600; line-height: 1.3; }
.bf-resin { display: flex; align-items: center; gap: 8px; }
.bf-resin input { flex: 1; min-width: 0; min-height: 2.5rem; box-sizing: border-box; border: 1px solid var(--line-strong); border-radius: 8px; padding: 0 12px; font-size: 1rem; font-weight: 700; }
.bf-resin input[readonly], .bf-note textarea[readonly] { background: var(--surface-2); }
.bf-resin em { font-style: normal; color: var(--muted); font-weight: 400; white-space: nowrap; }
.bf-fig { display: flex; align-items: center; min-height: 2.5rem; font-size: 1rem; font-weight: 700; line-height: 1.3; }
.bf-sub { display: flex; flex-wrap: wrap; gap: 0 6px; line-height: 1.3; }
.bf-card:not(.bf-f) .bf-sub, .bf-f.is-editing .bf-sub { min-height: 1.3em; }
.bf-ro { display: flex; align-items: center; gap: 8px; min-height: 2.5rem; box-sizing: border-box; padding: 0 12px; border-radius: 8px; background: var(--surface-2);
  border: 1px solid var(--line); font-size: 1rem; font-weight: 700; color: var(--ink); }
.bf-ro svg { flex: none; color: var(--muted); }
.bf-ro em { font-style: normal; }
.bf-ro[data-multi] { font-size: 0.8125rem; font-weight: 600; line-height: 1.25; padding-top: 3px; padding-bottom: 3px; }
.bf-notebox { display: flex; flex-direction: column; gap: 6px; }
.bf-ronote { margin: 0; padding: 10px 12px; border-radius: 8px; background: var(--surface-2); border: 1px solid var(--line); font-size: 0.84375rem; line-height: 1.5; overflow-wrap: anywhere; }
.bf-ronote.is-none { color: var(--muted); }
.bf-note { display: flex; flex-direction: column; gap: 6px; font-size: 0.8125rem; font-weight: 600; }
.bf-note textarea { border: 1px solid var(--line-strong); border-radius: 8px; padding: 8px 12px; font: inherit; font-size: 0.84375rem; font-weight: 400; resize: vertical; }
/* the filled card: read first, Edit turns the same card into the entry form (one class on the form, no reload) */
.bf-f:not(.is-editing) .bf-ed, .bf-f.is-editing .bf-rd { display: none !important; }
.bf-f:not(.is-editing) .bf-rd-hide { visibility: hidden; }
.bf-card.is-editing { box-shadow: 0 0 0 2px var(--accent-line), 0 2px 8px var(--d-sh-000000-a04); }
.bf-grid .bk2-btn { flex: none; white-space: nowrap; }
.bf-t td .bk2-pill { max-width: 100%; height: auto; min-height: 1.25rem; padding: 3px 10px; white-space: normal; text-align: left; line-height: 1.25; border-radius: 12px; justify-content: flex-start; }
.bf-t td:nth-child(5) { white-space: normal; }
.bf-t th:nth-child(1), .bf-t td:nth-child(1) { width: 20%; }   /* wide enough for "Northwind" whole at the largest text size */
.bf-t th:nth-child(2), .bf-t td:nth-child(2) { width: 26%; }
.bf-t th:nth-child(3), .bf-t td:nth-child(3) { width: 14%; }
.bf-t th:nth-child(4), .bf-t td:nth-child(4) { width: 14%; }
.bf-t th:nth-child(5), .bf-t td:nth-child(5) { width: 26%; }

/* BU CEOs tab: a unit's own calibration panel and its "In the <panel> panel" lines sit under the unit's row (2026-10-27) */
#ld-bu-table tr.ld-has-subs > td { border-bottom: 0; }
#ld-bu-table tr.ld-subrow > td { background: var(--d-bg-f9fafc); border-top: 0; padding-top: 4px; padding-bottom: 6px; }
