.kpe-mod input[type=radio] { position: absolute; opacity: 0; pointer-events: none; }
.kpe-radio { width: 16px; height: 16px; border-radius: 50%; border: 1.5px solid var(--d-bd-8a90a2); flex: none; margin-top: 2px; display: flex; align-items: center; justify-content: center; }
