.kpe-gobu { display: flex; flex-direction: column; gap: 8px; border: 1px solid var(--d-bd-c9cfe6); background: var(--d-bg-f7f8fd); border-radius: 10px; padding: 12px 14px; }
.kpe-gobu p { margin: 0; font-size: 0.78125rem; line-height: 1.5; color: var(--ink-2); }
.kpe-linkbtn { align-self: flex-start; display: inline-flex; align-items: center; min-height: 36px; padding: 0 16px; border-radius: 8px; background: var(--accent); color: var(--on-fill); font-weight: 600; font-size: 0.875rem; text-decoration: none; }
.kpe-linkbtn:hover { background: var(--accent-hover); color: var(--on-fill); }
.kpe-outlink { align-self: flex-start; display: inline-flex; align-items: center; min-height: 36px; padding: 0 16px; border-radius: 8px; border: 1px solid var(--line-strong); background: var(--surface); color: var(--accent-ink); font-weight: 600; font-size: 0.875rem; text-decoration: none; }
.kpe-danger { border-top: 1px solid var(--line-soft); padding-top: 14px; display: flex; align-items: center; gap: 14px; }
.kpe-danger.is-col { flex-direction: column; align-items: stretch; gap: 8px; }
.kpe-danger p { margin: 0; font-size: 0.78125rem; color: var(--muted); flex: 1; min-width: 0; line-height: 1.5; }
.kpe-danger p b { color: var(--ink); }
.kpe-delbtn { flex: none; min-height: 36px; padding: 0 16px; border-radius: 8px; border: 1px solid var(--d-bd-f0b4ae); background: var(--surface); color: var(--d-fg-b42318); font: inherit; font-size: 0.875rem; font-weight: 600; cursor: pointer; white-space: nowrap; }
.kpe-delbtn:hover { background: var(--d-bg-c0392b); border-color: var(--d-bd-c0392b); color: var(--on-fill); }
.kpe-body .kpi-scale-msg { margin: 0; }
/* the line manager change's hand-over box (2026-10-30): what the old line manager already did, kept or handed over */
.pp-ho [hidden] { display: none !important; }
.pp-ho .pp-ho-p { margin: 0; line-height: 1.45; }
.pp-pfields .pp-fs.pp-ho .pp-ho-row { align-items: flex-start; gap: 8px; }
.pp-ho .pp-ho-row input { margin: 2px 0 0; flex: none; }
.pp-ho .pp-ho-txt { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.pp-ho .pp-ho-row .muted { overflow-wrap: anywhere; }
.pp-ho .pp-ho-why { display: flex; flex-direction: column; gap: 8px; margin-top: 4px; }
.pp-pfields .pp-fs.pp-ho .pp-ho-why label { flex-direction: column; align-items: stretch; gap: 4px; font-size: .82rem; font-weight: 600; }
.pp-ho textarea { width: 100%; box-sizing: border-box; border: 1px solid var(--line-strong); border-radius: 8px; padding: 8px 10px;
  font: inherit; font-size: .85rem; font-weight: 400; resize: vertical; }
.pp-ho .pp-ho-note { margin: 0; padding: 8px 10px; border-radius: 8px; background: var(--surface-2); font-size: .78rem; color: var(--d-fg-3b4150);
  line-height: 1.45; }

/* Edit details: what a change asks (profile-change guards piece 3, 2026-11-08; canvas "Profile Change Prompts" boards A1-A5): the competency
   table, the choices, the read-only line. A danger answer turns its option and the foot button red. */
.pp-ask { gap: 10px; }
.pp-chip { display: inline-block; margin-left: 8px; padding: 1px 7px; border: 1px solid var(--line-strong); border-radius: 999px;
  font-size: max(10px, .72rem); font-weight: 600; color: var(--ink-2); white-space: nowrap; }
.pp-ask > legend .pp-chip { background: var(--surface-3); border-color: transparent; }
.pp-chip.is-new { background: var(--ok-tint); border-color: var(--ok-ink); color: var(--ok-ink); }
.pp-chip.is-go { background: var(--bad-tint); border-color: var(--danger-line); color: var(--bad-ink); }
.pp-ask-p { margin: 0; font-size: .8rem; line-height: 1.45; color: var(--muted); }
.pp-cmp { display: flex; flex-direction: column; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.pp-cmp-r { display: grid; grid-template-columns: minmax(0, 1fr) 6.25rem 7.5rem; column-gap: 14px; align-items: start; padding: 6px 8px;
  font-size: .8rem; border-top: 1px solid var(--line-soft); }
.pp-cmp > .pp-cmp-r:first-child { border-top: 0; }
.pp-cmp-h { background: var(--surface-2); font-size: max(10px, .72rem); font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
.pp-cmp-h span { white-space: nowrap; }
.pp-cmp-n { font-weight: 700; overflow-wrap: anywhere; }
.pp-cmp-l { font-variant-numeric: tabular-nums; white-space: nowrap; }
.pp-cmp-a { display: block; font-size: max(10px, .72rem); font-weight: 600; color: var(--warn-ink); }
.pp-cmp-fold > summary { padding: 6px 8px; cursor: pointer; font-size: .8rem; font-weight: 600; color: var(--link); border-top: 1px solid var(--line-soft); }
.pp-cmp-fold[open] > .pp-cmp-r:first-of-type { border-top: 1px solid var(--line-soft); }
.pp-cmp-fold .fold-less { margin: 4px 8px 6px; }
.pp-opts { display: flex; flex-direction: column; gap: 8px; }
.pp-opt { display: flex; flex-direction: row; align-items: flex-start; gap: 10px; padding: 10px 12px; border: 1px solid var(--line);
  border-radius: 10px; font-size: .85rem; font-weight: 400; cursor: pointer; }
.pp-opt input { margin: 3px 0 0; flex: none; accent-color: var(--accent); }
.pp-opt.is-on { border-color: var(--accent-line); box-shadow: 0 0 0 1px var(--accent-line); }
.pp-opt.is-danger.is-on { border-color: var(--danger-ink); box-shadow: 0 0 0 1px var(--danger-ink); }
.pp-opt.is-danger input { accent-color: var(--danger-ink); }
.pp-opt-t { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.pp-opt-t b { font-weight: 700; }
.pp-opt-s { font-size: .8rem; color: var(--muted); }
.pp-ask-why { display: flex; flex-direction: column; gap: 4px; font-size: .82rem; font-weight: 600; color: var(--ink-2); }
.pp-ask-why[hidden] { display: none; }
.pp-ask-why textarea { width: 100%; box-sizing: border-box; min-height: 3.2rem; border: 1px solid var(--line-strong); border-radius: 8px; padding: 8px 10px;
  font: inherit; font-size: .85rem; font-weight: 400; resize: vertical; }
.pp-ask-why .muted { font-weight: 400; }
.pp-ro { margin: 0; padding: 8px 10px; border-radius: 8px; background: var(--surface-2); font-size: .8rem; color: var(--muted); }
.pp-lk { font-weight: 700; color: var(--accent-ink); white-space: nowrap; text-decoration: none; }
.pp-lk:hover { background: var(--surface-3); text-decoration: none; }
.adm-panel-foot button.primary.is-danger { background: var(--d-bg-b3261e); border-color: var(--d-bd-b3261e); }
.adm-panel-foot button.primary.is-danger:hover { background: var(--d-bg-8f1e18); }

/* ---- Calibration filter rules (Chris, 2026-10-30, canvas "OneHR Calibration Filter Rules": Option 2 for the settings, boards
   C2 / D2 for the leaders' filter line). Settings: one row per filter in Filters at BU level, its rule in the 560px side panel. ---- */
.cfr-table td, .cfr-table th { vertical-align: middle; }
.cfr-table .cfr-code { margin-top: 2px; font-size: max(10px, 0.6875rem); font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--d-fg-6b7186); white-space: nowrap; }
.cfr-table th:nth-child(1) { width: 24%; }
.cfr-table th:nth-child(3) { width: 29%; }
.cfr-table td:nth-child(3) { white-space: nowrap; }
.cfr-table th:nth-child(4), .cfr-table td.cfr-edit { width: 72px; text-align: right; white-space: nowrap; }
.cfr-table td, .cfr-table th { white-space: normal; }
.cfr-table thead th { white-space: nowrap; }
details.cfr-fold { display: inline; }
details.cfr-fold > summary { display: inline; cursor: pointer; color: var(--link); font-weight: 600; list-style: none; }
details.cfr-fold > summary::-webkit-details-marker { display: none; }
details.cfr-fold .fold-less { display: inline-flex; margin: 0 0 0 6px; padding: 2px 8px; }
.cfr-pform .adm-panel-body { gap: 22px; }
.cfr-sec { display: flex; flex-direction: column; gap: 10px; }
.cfr-sec-h { display: flex; align-items: center; gap: 12px; }
.cfr-grow { flex: 1 1 auto; }
.cfr-lbl { font-size: 0.78125rem; font-weight: 700; color: var(--d-fg-6b7186); text-transform: uppercase; letter-spacing: .04em; }
.cfr-units { list-style: none; margin: 0; padding: 0; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; }
.cfr-unit { border-top: 1px solid var(--line-soft); }
.cfr-unit:first-child { border-top: 0; }
.cfr-unit.is-changed { background: var(--d-bg-fffaf1); }
.cfr-unit label { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 10px 14px; margin: 0; cursor: pointer; font-size: 0.84375rem; }
.cfr-unit input[type=checkbox] { margin: 0; width: 16px; height: 16px; accent-color: var(--accent-ink); }
.cfr-uname { min-width: 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 8px; }
.cfr-uname b { color: var(--ink, var(--ink)); }
.cfr-ufull { font-size: 0.75rem; color: var(--d-fg-6b7186); overflow-wrap: anywhere; }
.cfr-cover { font-size: 0.78125rem; color: var(--muted); text-align: right; white-space: nowrap; }
.cfr-cover.is-none { color: var(--faint); }
.cfr-unit.is-off { background: var(--d-bg-f6f7fa); }
.cfr-unit.is-off label { cursor: not-allowed; }
.cfr-unit.is-off .cfr-uname b, .cfr-unit.is-off .cfr-ufull { color: var(--d-fg-9aa0b4); }
.cfr-screens { display: flex; flex-direction: column; gap: 8px; font-size: 0.84375rem; }
.cfr-screens label { display: flex; align-items: center; gap: 8px; margin: 0; }
.cfr-screens input { margin: 0; accent-color: var(--accent-ink); }
.cfr-note { margin: 0; }
.cfr-chip { display: inline-flex; align-items: center; gap: 6px; min-height: 28px; padding: 0 10px 0 12px; border-radius: 999px; border: 1px solid var(--line-strong);
  background: var(--surface); color: var(--d-fg-4a5165); font-size: 0.75rem; font-weight: 600; white-space: nowrap; }
.cfr-chip b { font-size: max(10px, 0.6875rem); font-weight: 500; color: var(--faint); }
.cfr-chip svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.cfr-prev { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; padding: 12px 14px; background: var(--d-bg-f8fafd); border: 1px solid var(--line-soft); border-radius: 10px; }

/* The leader's chip, in the BU CEO's filter strip and under the Talent Box's BU row (shared by calFilterLine and tbFilterLine) */
.rv-cal-filter { min-height: 48px; box-sizing: border-box; }
.rv-cal-fline { display: flex; align-items: center; gap: 8px; flex: 1 1 auto; min-width: 0; min-height: 34px; }
.rv-cal-flbl { flex: none; font-size: max(10px, 0.6875rem); font-weight: 800; letter-spacing: .44px; text-transform: uppercase; color: var(--muted); margin-right: 4px; }
.rv-cal-fgrow { flex: 1 1 auto; min-width: 8px; }
.rv-cal-fcount { flex: none; font-size: 0.78125rem; color: var(--muted); white-space: nowrap; }
.rv-cal-fclear { flex: none; border: 0; background: transparent; padding: 4px 6px; font: inherit; font-size: 0.78125rem; font-weight: 600; color: var(--link); cursor: pointer; border-radius: 6px; }
.rv-cal-fclear:hover { background: var(--d-bg-eef1fa); }
.rv-cal-chip { flex: none; display: inline-flex; align-items: center; gap: 8px; min-height: 28px; padding: 0 10px 0 12px; border-radius: 999px;
  border: 1px solid var(--line-strong); background: var(--surface); color: var(--d-fg-4a5165); font: inherit; font-size: 0.75rem; font-weight: 600; cursor: pointer; white-space: nowrap; max-width: 280px; }
.rv-cal-chip-t { display: flex; min-width: 0; overflow: hidden; }
.rv-cal-chip-k { flex: 0 4 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: pre; }
.rv-cal-chip-v { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.rv-cal-t-short { display: none; }
.rv-cal-fline.is-tight .rv-cal-t-long { display: none; }
.rv-cal-fline.is-tight .rv-cal-t-short { display: inline; }
.rv-cal-fline.is-tighter .rv-cal-chip.is-picked { flex: 0 1 auto; min-width: 0; }   /* a long pick gives way first: "..." and the full words on hover */
.rv-cal-fline.is-tighter .rv-cal-chip-k { display: none; }   /* the picked value alone (the chip's title names the filter) */
.rv-cal-chip-n { font-size: max(10px, 0.6875rem); font-weight: 500; color: var(--faint); }
.rv-cal-chip-chev { width: 12px; height: 12px; flex: none; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.rv-cal-chip:hover { border-color: var(--d-bd-aeb4c6); }
.rv-cal-chip.is-picked { background: var(--accent); border-color: var(--accent-line); color: var(--on-fill); }
.rv-cal-chip.is-picked .rv-cal-chip-n { color: var(--d-fg-d5d8ee); }
.rv-cal-chip.is-open { border: 1.5px solid var(--accent-line); box-shadow: 0 0 0 3px var(--d-sh-252a59-a12); padding: 0 9.5px 0 11.5px; }
.rv-cal-chip:focus-visible { outline: 2px solid var(--accent-line); outline-offset: 2px; }
.rv-cal-pop { position: fixed; z-index: 1100; width: 300px; box-sizing: border-box; padding: 8px; background: var(--surface); border: 1px solid var(--line);
  border-radius: 12px; box-shadow: 0 12px 32px var(--d-sh-1f2330-a16); }
.rv-cal-pop-q { width: 100%; box-sizing: border-box; height: 34px; margin: 0 0 6px; padding: 0 10px; border: 1px solid var(--line-strong); border-radius: 8px; font: inherit; font-size: 0.8125rem; }
.rv-cal-pop-list { max-height: 280px; overflow-y: auto; display: flex; flex-direction: column; gap: 1px; scrollbar-width: thin; }
.rv-cal-opt { display: flex; align-items: center; gap: 10px; width: 100%; box-sizing: border-box; min-height: 32px; padding: 4px 10px; border: 0; border-radius: 8px; background: transparent;
  font: inherit; font-size: 0.8125rem; color: var(--ink); text-align: left; cursor: pointer; }
.rv-cal-opt[hidden] { display: none; }
.rv-cal-opt:hover, .rv-cal-opt:focus { background: var(--d-bg-f4f5fa); outline: none; }
.rv-cal-opt.is-on { background: var(--d-bg-eef1fa); color: var(--accent-ink); font-weight: 600; }
.rv-cal-opt.is-quiet { color: var(--muted); }
.rv-cal-opt.is-quiet { border-top: 1px solid var(--line-soft); border-radius: 0 0 8px 8px; }
.rv-cal-opt-t { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rv-cal-opt-h { flex: none; font-size: max(10px, 0.6875rem); color: var(--d-fg-1a7a54); font-weight: 600; }
.rv-cal-opt-n { flex: none; font-size: 0.75rem; color: var(--d-fg-6b7186); font-weight: 500; min-width: 24px; text-align: right; }
.rv-cal-opt.is-on .rv-cal-opt-n { color: var(--accent-ink); font-weight: 600; }
/* the tick box ahead of each value (several values in one filter, canvas board E): navy and ticked when picked */
.rv-cal-opt-box { flex: none; width: 16px; height: 16px; box-sizing: border-box; border: 1.5px solid var(--line-strong); border-radius: 4px; background: var(--surface);
  display: inline-flex; align-items: center; justify-content: center; }
.rv-cal-opt.is-on .rv-cal-opt-box { background: var(--accent); border-color: var(--accent-line); }
.rv-cal-opt-tick { width: 11px; height: 11px; fill: none; stroke: var(--on-fill); stroke-width: 3.2; stroke-linecap: round; stroke-linejoin: round; visibility: hidden; }
.rv-cal-opt.is-on .rv-cal-opt-tick { visibility: visible; }
.rv-cal-pop-foot { margin: 2px 0 0; padding: 2px 10px; font-size: max(10px, 0.71875rem); color: var(--muted); }
.rv-cal-pop-act { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 6px; padding: 8px 4px 2px; border-top: 1px solid var(--line-soft); }
.rv-cal-pop-sum { min-width: 0; font-size: 0.78125rem; color: var(--muted); white-space: nowrap; }
.rv-cal-pop-btns { flex: none; display: inline-flex; gap: 8px; }
.rv-cal-pop-clear, .rv-cal-pop-apply { height: 30px; box-sizing: border-box; border-radius: 8px; font: inherit; font-size: 0.78125rem; font-weight: 600; cursor: pointer; }
.rv-cal-pop-clear { padding: 0 12px; color: var(--accent-ink); background: var(--surface); border: 1px solid var(--line-strong); }
.rv-cal-pop-clear:hover { background: var(--d-bg-f4f5fa); }
.rv-cal-pop-apply { padding: 0 14px; color: var(--on-fill); background: var(--accent); border: 0; }
.rv-cal-pop-apply:hover { background: var(--accent-hover); }
.rv-cal-pop-clear:focus-visible, .rv-cal-pop-apply:focus-visible { outline: 2px solid var(--accent-line); outline-offset: 2px; }
.rv-tbox-filter { display: flex; align-items: center; min-height: 40px; box-sizing: border-box; padding: 2px 10px; margin: 6px 0 0; background: var(--surface-2);
  border: 1px solid var(--line-soft); border-radius: 8px; }
/* the Chairman's strip with All business groups picked: only a muted line saying what to do (2026-11-02, canvas board F) */
.rv-cal-fhint { font-size: 0.78125rem; color: var(--muted); }
/* THE TALENT BOX LIMITS (Chris, 2026-11-03, canvas boards T1-T3): drawn only while Group People has one on. The LIMITS line is the
   filter line's box; amber Full at a limit (the .rv-nodata pair), red "N over" past it; a full Star / Super Star box is not a
   target in the Move picker. */
.rv-tbox-limits { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 18px; min-height: 40px; box-sizing: border-box; padding: 2px 10px; margin: 6px 0 0;
  background: var(--surface-2); border: 1px solid var(--line-soft); border-radius: 8px; font-size: 0.78125rem; color: var(--ink-2); }
.rv-tbox-limk { font-size: max(10px, 0.6875rem); font-weight: 800; letter-spacing: .04em; color: var(--muted); }
.rv-tbox-limp { display: inline-flex; align-items: center; gap: 8px; white-space: nowrap; }
.rv-tbox-limp b { color: var(--ink); font-weight: 700; }
.rv-tbox-limp > .rv-tbox-lchip { margin-left: -2px; }   /* the 8px gap less 2: 6px from its figure */
.rv-tbox-limby { margin-left: auto; color: var(--muted); }
.rv-tbox-lchip { display: inline-flex; align-items: center; margin-left: 6px; padding: 2px 8px; border-radius: 999px; font-size: max(10px, 0.6875rem);
  font-weight: 700; white-space: nowrap; background: var(--d-bg-fdf0e2); color: var(--warn-ink); }
.rv-tbox-lchip.is-over { background: var(--d-bg-fdecec); color: var(--d-fg-b42318); }
.rv-tbox-lchip.is-sm { margin-left: 0; padding: 1px 7px; font-size: max(10px, 0.65625rem); }
.rv-tbox-num > .rv-tbox-lchip { margin-left: auto; align-self: center; }
.rv-tbox-dlim { font-size: 0.75rem; color: var(--warn-ink); }
