.lp-st.is-open { padding: 2px 10px; border-radius: 999px; border: 1px solid var(--d-bd-f3e2bf); background: var(--d-bg-fdf6e8); color: var(--d-fg-6b4300); font-weight: 700; }
.lp-st.is-used { color: var(--d-fg-1a7a54); }
.lp-act { text-align: right; white-space: nowrap; }
.lp-act form { margin: 0; display: inline; }
.lp-none { padding: 18px 12px; }
.lp-foot { margin: 8px 0 0; }
.pp-late-foot > button { flex: none; white-space: nowrap; }
.pp-late-foot .adm-panel-grow { min-width: 0; }
.confirm-dialog__body:has(> .pp-late-boxk) { margin: 12px 0 0; gap: 4px; }
.confirm-dialog__body .pp-late-boxk { margin: 0; }
.lp-table { table-layout: fixed; width: 100%; }
.lp-table th:nth-child(1) { width: 18%; } .lp-table th:nth-child(2) { width: 14%; } .lp-table th:nth-child(3) { width: 15%; }
.lp-table th:nth-child(4) { width: 11%; } .lp-table th:nth-child(5) { width: 17%; } .lp-table th:nth-child(6) { width: 12%; }
