.oo-lnk:hover { background: var(--d-bg-eef0f8); }
/* Email › Sent: the two runs as tables */
.es-card { margin: 0 0 14px; }
.es-table { table-layout: fixed; width: 100%; }
.es-table th { white-space: nowrap; }
.es-table td { padding: 9px 14px; vertical-align: top; }
