.ecp-res { container-type: inline-size; container-name: ecpres; background: var(--surface); border: 1px solid var(--d-bd-e2e5ee); border-radius: 10px; padding: 12px 14px;
  min-width: 0; }
.ecp-res-h { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 10px; margin-bottom: 6px; }
.ecp-res-h b { font-size: 0.84375rem; color: var(--accent-ink); min-width: 0; }
.ecp-muted { font-size: 0.75rem; color: var(--muted); }
.ecp-res-h .ecp-muted { margin-left: auto; text-align: right; min-width: 0; }
.ecp-tbl { width: 100%; border-collapse: collapse; font-size: 0.78125rem; table-layout: fixed; }
.ecp-tbl th { font-size: max(10px, 0.6875rem); text-transform: uppercase; letter-spacing: .04em; color: var(--muted); text-align: left; font-weight: 650; padding: 6px 14px 6px 0;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; border-bottom: 1px solid var(--d-bd-e6e8ef); }
.ecp-tbl td { padding: 8px 14px 8px 0; border-bottom: 1px solid var(--d-bd-f0f1f5); vertical-align: top; min-width: 0; overflow-wrap: anywhere; }
