.ecp-hs { display: none; }
.ecp-nmrow { display: flex; flex-wrap: wrap; align-items: center; gap: 2px 8px; min-width: 0; }
.ecp-nm { display: block; min-width: 0; max-width: 100%; margin: 0; padding: 0; border: 0; background: none; font: inherit; font-weight: 650; font-size: 0.8125rem;
  color: var(--accent-ink); text-align: left; cursor: pointer; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ecp-nm:hover { color: var(--d-fg-1d2249); background: var(--d-bg-eef1fa); box-shadow: 0 0 0 3px var(--d-bg-eef1fa); border-radius: 4px; }
.ecp-sub { display: block; font-size: max(10px, 0.71875rem); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ecp-tag { display: inline-flex; align-items: center; flex: none; height: 18px; padding: 0 7px; border-radius: 999px; background: var(--d-bg-eef0f8); color: var(--accent-ink);
  font-size: max(10px, 0.65625rem); font-weight: 650; white-space: nowrap; }
.ecp-ts { display: flex; gap: 6px; flex-wrap: wrap; }
.ecp-tc { display: inline-flex; align-items: center; height: 20px; padding: 0 7px; border-radius: 999px; font-size: max(10px, 0.6875rem); font-weight: 600; white-space: nowrap; }
.ecp-tc.ecp-ss { background: var(--d-bg-262c63); color: var(--on-fill); }
.ecp-tc.ecp-st { background: var(--d-bg-4a548f); color: var(--on-fill); }
.ecp-tc.ecp-sc { background: var(--d-bg-e3e6ef); color: var(--accent-ink); }
.ecp-tc.ecp-pip { background: var(--d-bg-f6dcc6); color: var(--d-fg-7a3e12); }
.ecp-tc.na { background: var(--surface); color: var(--d-fg-6f758a); border: 1px dashed var(--d-bd-c9cdda); }
.ecp-mt { display: flex; align-items: center; gap: 8px; font-weight: 700; color: var(--accent-ink); min-width: 0; }
.ecp-mb { flex: 1 1 20px; min-width: 20px; max-width: 52px; height: 6px; border-radius: 3px; background: var(--surface-3); overflow: hidden; display: flex; }
.ecp-mb i { display: block; height: 100%; background: var(--accent); }
.ecp-cov { display: inline-flex; align-items: center; max-width: 100%; height: 22px; padding: 0 8px; border-radius: 999px; font-size: max(10px, 0.71875rem); font-weight: 650;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; box-sizing: border-box; }
.ecp-cov.none { background: var(--d-bg-fbe7e7); color: var(--d-fg-a32424); }
.ecp-cov.some { background: var(--d-bg-eef0f8); color: var(--accent-ink); }
.ecp-why { display: block; margin-top: 2px; font-size: max(10px, 0.71875rem); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ecp-src { margin: 8px 0 0; font-size: max(10px, 0.71875rem); color: var(--muted); line-height: 1.4; }
