.ecp-tbl[data-k="match"] col:nth-child(5) { width: 18%; }
.ecp-tbl[data-k="key"] col:nth-child(1) { width: 36%; } .ecp-tbl[data-k="key"] col:nth-child(2) { width: 9%; }
.ecp-tbl[data-k="key"] col:nth-child(3) { width: 29%; } .ecp-tbl[data-k="key"] col:nth-child(4) { width: 26%; }
.ecp-tbl[data-k="list"] col:nth-child(1) { width: 46%; } .ecp-tbl[data-k="list"] col:nth-child(2) { width: 10%; }
