  .ecp-tbl[data-k="match"] col:nth-child(3) { width: 22%; } .ecp-tbl[data-k="match"] col:nth-child(4) { width: 15%; }
  .ecp-tbl[data-k="match"] col:nth-child(5) { width: 20%; }
  .ecp-tbl[data-k="key"] col:nth-child(1) { width: 34%; } .ecp-tbl[data-k="key"] col:nth-child(2) { width: 13%; }
  .ecp-tbl[data-k="key"] col:nth-child(3) { width: 27%; } .ecp-tbl[data-k="key"] col:nth-child(4) { width: 26%; }
  .ecp-tbl[data-k="list"] col:nth-child(1) { width: 44%; } .ecp-tbl[data-k="list"] col:nth-child(2) { width: 13%; }
  .ecp-tbl[data-k="list"] col:nth-child(3) { width: 43%; }
}
/* narrow (the 320px rest, a few answers): each row stacks, the headings are read out but not drawn */
@container ecpres (max-width: 439px) {
  .ecp-tbl:not(.ecp-cmp), .ecp-tbl:not(.ecp-cmp) tbody, .ecp-tbl:not(.ecp-cmp) tr, .ecp-tbl:not(.ecp-cmp) td { display: block; width: auto; }
  .ecp-tbl:not(.ecp-cmp) colgroup, .ecp-tbl:not(.ecp-cmp) thead { display: none; }
  .ecp-tbl:not(.ecp-cmp) tr { padding: 8px 0; border-bottom: 1px solid var(--d-bd-f0f1f5); }
  .ecp-tbl:not(.ecp-cmp) tr:last-child { border-bottom: 0; }
  .ecp-tbl:not(.ecp-cmp) td { padding: 2px 0; border: 0; }
  .ecp-tbl:not(.ecp-cmp) td[data-l]::before { content: attr(data-l) "  "; font-size: max(10px, 0.6875rem); color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
  .ecp-tbl:not(.ecp-cmp) td.ecp-c-ts[data-l], .ecp-tbl:not(.ecp-cmp) td.ecp-c-mt[data-l] { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 8px; }
  .ecp-tbl:not(.ecp-cmp) td.ecp-c-nm { padding-bottom: 4px; }
}
