.ld-now > summary { display: flex; flex-wrap: wrap; align-items: center; column-gap: 8px; row-gap: 4px; list-style: none; cursor: pointer;
  font-size: 0.75rem; line-height: 1.125rem; }
.ld-now > summary::-webkit-details-marker { display: none; }
.ld-now-k { color: var(--muted); }
.ld-now-h { display: inline-flex; align-items: center; column-gap: 8px; }
