.ld-now-ppl { margin-top: 8px; padding-top: 10px; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 12px; }
.ld-gh { display: flex; flex-wrap: wrap; align-items: center; column-gap: 8px; row-gap: 2px; margin-bottom: 4px; font-size: 0.75rem; font-weight: 700; }
.ld-gh-n { color: var(--muted); font-weight: 400; }
.ld-pt { display: grid; grid-template-columns: minmax(0, 1fr) 6.5rem 3.25rem; column-gap: 14px; font-size: 0.78125rem; line-height: 1.125rem; }
.ld-pt > span { padding: 3px 0; border-bottom: 1px solid var(--line-soft); overflow-wrap: anywhere; }
.ld-pt > .m { color: var(--muted); }
.ld-pt > .th { font-size: max(10px, 0.6875rem); font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--muted); }
.ld-more > summary { list-style: none; cursor: pointer; font-size: 0.75rem; font-weight: 600; color: var(--accent-ink); padding-top: 6px; }
.ld-more > summary::-webkit-details-marker { display: none; }

/* ---- A Grade H person's page (2026-11-03, canvases P1, P2): Grade H's own cards and the read-only Grade H Appraisal tab ---- */
.pp-role.is-gh { background: var(--d-bg-ebdff7); color: var(--d-fg-5e2a96); }
.pp-nonormal { margin-left: 0; }
.pp-step.is-warn { background: var(--bad-tint); color: var(--bad-ink); }
.pp-gh { display: flex; flex-direction: column; gap: 10px; }
.pp-gh-steps { margin-top: 0.375rem; }
.pp-gh-card .pp-gh-bands { display: flex; flex-wrap: wrap; align-items: center; gap: 0.25rem 0.5rem; }
.pp-gh-mods .pp-gh-card:first-child { grid-column: 1 / -1; }
.pp-gh-note { margin: 0.375rem 0 0; }
.pp-gh-table { width: 100%; border-collapse: collapse; font-size: .84rem; }
.pp-gh-table th { text-align: left; white-space: nowrap; font-size: max(10px, .74rem); font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--muted); background: var(--surface-2); border-bottom: 1px solid var(--line-soft); padding: 0.5rem 0.875rem 0.5rem 0.75rem; }
.pp-gh-table td { vertical-align: top; padding: 0.5625rem 0.875rem 0.5625rem 0.75rem; border-bottom: 1px solid var(--line-soft); }
.pp-gh-table th.pp-gh-prose, .pp-gh-table td.pp-gh-prose { white-space: normal; overflow-wrap: anywhere; min-width: 7rem; }   /* the line manager's reason is prose: it wraps, so the table fits the side panel at every text size */
.pp-gh-table th.pp-gh-prose, .pp-gh-table td.pp-gh-rate { white-space: nowrap; overflow-wrap: normal; }   /* its heading ("Reason", full words in title) and the total's rating stay on one line */
.pp-gh-table tr.pp-gh-total td { background: var(--surface-2); border-top: 2px solid var(--accent-line); font-weight: 700; }
.pp-gh-sm { margin-top: 0.1875rem; font-size: .78rem; color: var(--muted); }
.pp-gh-h3 { margin: 0.625rem 0 0.125rem; font-size: .82rem; font-weight: 700; color: var(--ink); }
.pp-gh-move { display: flex; flex-wrap: wrap; gap: 0.25rem 0.875rem; font-size: .84rem; padding: 0.3125rem 0; border-top: 1px solid var(--line-soft); }
.pp-gh-two { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; align-items: start; }
.pp-gh-q { margin-top: 0.5rem; font-size: .8rem; font-weight: 700; color: var(--ink); }
.pp-gh-p { margin: 0.125rem 0 0; font-size: .84rem; overflow-wrap: anywhere; }
.pp-prof-pct { margin-left: 0.5rem; font-weight: 400; font-size: .8rem; color: var(--muted); }
.pp-prof-note { margin: 0.5rem 0 0; }

/* Transferred (2026-11-03): the person page's Performance tab card (super admin). One line off; the summary on; the form opens
   under it. Tokens and rem only; the roles and figures wrap, never touch (8px between side-by-side text). */
.pp-split { margin: 0 0 10px; padding: 9px 14px; display: grid; gap: 8px; }
.pp-split-head { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px; font-size: .86rem; }
