.ais-seg { display: inline-flex; flex-wrap: wrap; border: 1px solid var(--line-strong); border-radius: 8px; overflow: hidden; }
.ais-seg button { border: 0; border-left: 1px solid var(--line-strong); background: var(--surface); color: var(--ink-2); padding: 6px 12px;
  font: inherit; font-size: 0.8rem; cursor: pointer; }
