.sg-open { padding: 4px 10px; min-height: 1.75rem; font-size: 0.8rem; }
.sg-row { display: flex; align-items: center; gap: 0.75rem; padding: 8px 11px; border: 1px solid var(--line); border-radius: 10px; }
.sg-row.is-off .sg-who b { color: var(--muted); }
.sg-who { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 2px; overflow-wrap: anywhere; }
.sg-who b { display: flex; flex-wrap: wrap; align-items: center; column-gap: 0.625rem; font-size: 0.88rem; color: var(--ink); }
.sg-chip { display: inline-block; padding: 1px 7px; border-radius: 999px; background: var(--d-bg-eef1fa); color: var(--accent-ink); font-size: max(10px, 0.66rem); font-weight: 700; }
