.sg-add[hidden] { display: none; }
.sg-add .pick { display: block; flex: none; min-width: 0; width: 100%; }
.sg-add .pick-q { width: 100%; min-height: 2.25rem; box-sizing: border-box; padding: 0 10px; border: 1px solid var(--line-strong); border-radius: 8px; background: var(--surface); font: inherit; font-size: 0.82rem; color: var(--ink); }
.sg-add .pick-list { position: static; width: auto; max-width: none; max-height: 17.5rem; margin-top: 6px; }
.sg-add .pick-list[hidden] { display: none; }
