.sg-add .pick-list li.pick-grp { cursor: default; padding: 6px 9px 2px; font-size: max(10px, 0.66rem); font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); }
.sg-add .pick-list li.pick-grp:hover { background: transparent; }
