.bk-late-reach { margin: 0; font-size: 0.8125rem; line-height: 1.45; color: var(--ink-2); }
.pp-chip.is-unit, .kpe-badge.is-unit { background: transparent; border: 1px solid var(--line-strong); color: var(--ink-2); }
.pp-kline .pp-chip.is-unit { flex: 0 1 auto; min-width: 0; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; display: inline-block; vertical-align: middle; }   /* a guest carrier's unit chip stays inside its cell and ends in "..." (full words in its title), 2026-11-08 */
.clp-who .clp-chip { margin-left: 6px; vertical-align: middle; margin-top: 2px; }   /* the "From <unit>" chip in a people list: 6px after the name (2026-11-07) */
.bk2-guestn { color: var(--ink-2); font-size: 0.78rem; }
.bk2-pl { color: var(--accent-ink); font-weight: inherit; text-decoration: none; }
.bk2-pl:hover { color: var(--accent); }
.bk-gp { grid-template-columns: 20px 7.75rem minmax(0, 1fr) 7rem 6.5rem 4.625rem; gap: 8px 14px; }   /* 20 / 124 / rest / 112 / 104 / 74 px at the standard size: the unit's add grid plus a Unit column */
.bk-gp > span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
