.pts-when { border: 0; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.5rem; min-width: 0; }
.pts-when legend { padding: 0; margin-bottom: 0.5rem; font-size: 0.72rem; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); }
.pts-opt { display: flex; align-items: flex-start; gap: 0.625rem; border: 1px solid var(--line); border-radius: 10px; padding: 0.75rem 0.875rem; cursor: pointer; background: var(--surface); }
.pts-opt input[type="radio"] { margin: 0.1875rem 0 0; accent-color: var(--accent); }
.pts-opt.is-on { border-color: var(--accent-line); background: var(--d-bg-f4f5f9); }
.pts-opt.is-off { background: var(--surface-2); color: var(--faint); cursor: default; }
.pts-opt-t { display: flex; flex-direction: column; gap: 0.25rem; min-width: 0; }
