.pts-why textarea { font: inherit; font-size: 0.875rem; font-weight: 400; border: 1px solid var(--line-strong); border-radius: 8px; padding: 0.5rem 0.625rem; resize: vertical; background: var(--surface); color: var(--ink); }
.pts-step .actions { display: flex; justify-content: flex-end; gap: 0.625rem; margin: 0.25rem 0 0; }
.pts-step .actions .pts-cancel { display: inline-flex; align-items: center; min-height: 2.25rem; padding: 0 1rem; border-radius: 8px; border: 1px solid var(--line-strong); background: var(--surface); color: var(--ink); font-size: 0.85rem; font-weight: 600; text-decoration: none; }
