.eco-f input[type=text], .eco-f input[type=date], .eco-f select, .eco-f textarea, .eco-row select, .eco-n { box-sizing: border-box; min-height: 34px; width: 100%; padding: 0 10px; border: 1px solid var(--line-strong);
  border-radius: 8px; background: var(--surface); color: var(--ink); font: inherit; font-size: .86rem; font-weight: 400; }
