.eco-n { width: 4.5rem; text-align: center; }
.eco-hint { margin: 2px 0 0; font-size: .78rem; font-weight: 400; color: var(--muted); }
.eco-warn { margin: 6px 0 0; font-size: .8rem; color: var(--warn-ink); }
.eco-lbl { font-size: .78rem; font-weight: 600; color: var(--ink-2); }
.eco-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.eco-chip { min-height: 24px; padding: 0 8px; border: 1px solid var(--d-bd-d7dbe6); border-radius: 999px; background: var(--surface-2); color: var(--ink-2); font: .76rem ui-monospace, Menlo, monospace; cursor: pointer; }
.eco-chip:hover, .eco-chip:focus-visible { background: var(--surface-3); border-color: var(--accent-line); outline: none; }
.eco-sp { flex: 1 1 auto; }
.eco-pvb { min-height: 30px; }
.eco-pv { margin-top: 8px; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; }
.eco-pv iframe { display: block; width: 100%; height: 26rem; border: 0; background: var(--surface); }
.eco-more { margin: 8px 0 0; }
.eco-more > summary { cursor: pointer; padding: 4px 0; font-size: .82rem; font-weight: 700; color: var(--link); }
.eco-more[open] > summary { margin-bottom: 8px; }
.eco-tks { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 10px; }
.eco-tk { position: relative; display: inline-flex; }
.eco-tk input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer; }
.eco-tk span { display: inline-flex; align-items: center; gap: 6px; min-height: 28px; padding: 0 11px; box-sizing: border-box; border: 1px solid var(--d-bd-d7dbe6); border-radius: 999px;
  background: var(--surface); color: var(--ink-2); font-size: .8rem; font-weight: 600; }
.eco-tk input:checked + span { background: var(--accent); border-color: var(--accent-line); color: var(--on-fill); }
.eco-tk input:checked + span::before { content: "\2713"; }
